static void check_media_conservation(const char *track, uint64_t decoded,
                                    uint64_t delivered, uint64_t held,
                                    uint64_t eos_drained, uint64_t rejected) {
    uint64_t accounted = delivered + held + eos_drained + rejected;
    checks++;
    if (decoded != accounted) {
        failures++;
        fprintf(stderr,
                "FAIL: %s disposition conservation: decoded=%llu delivered=%llu "
                "held=%llu eos_drained=%llu rejected=%llu accounted=%llu\n",
                track, (unsigned long long)decoded, (unsigned long long)delivered,
                (unsigned long long)held, (unsigned long long)eos_drained,
                (unsigned long long)rejected, (unsigned long long)accounted);
    }
}

/* Bounded diagnostics for the acceptance runs: SR_PSMF_MEDIA_DEBUG=1 prints the counters that
 * say where a media chain stopped, without making the normal run noisy. */
#define MEDIA_DEBUG(...) do { if (getenv("SR_PSMF_MEDIA_DEBUG")) fprintf(stderr, __VA_ARGS__); } while (0)

/* The flight recorder sees only these scalar milestones when the selftest is
 * explicitly run with SR_FLIGHT=media;N. They describe this source-owned
 * fixture, not a PSP media ABI or a private-title observation. */
static void flight_media_test_milestone(uint32_t stage, uint32_t arg1,
                                        uint32_t arg2, uint32_t arg3) {
    (void)stage; (void)arg1; (void)arg2; (void)arg3;
    SR_FLIGHT_RECORD_CLASS(SR_FLIGHT_CLASS_MEDIA, SR_FLIGHT_KIND_MEDIA_TEST_MILESTONE,
                           stage, arg1, arg2, arg3);
}

/* ---- guest arena ------------------------------------------------------------------------ */
/* The linked production runtime owns memory, scheduler, and debug state. This
 * fixture installs only its flat synthetic arena into that runtime memory. */

static uint32_t guest_mpeg_import(uint32_t nid, uint32_t a0, uint32_t a1, uint32_t a2,
                                  uint32_t a3, uint32_t a4) {
    CpuState cpu;
    memset(&cpu, 0, sizeof(cpu));
    cpu.r[4] = a0; cpu.r[5] = a1; cpu.r[6] = a2; cpu.r[7] = a3; cpu.r[8] = a4;
    return sr_syscall(&cpu, nid);
}

static int guest_bytes_are(uint32_t addr, uint32_t size, uint8_t value) {
    const uint8_t *bytes = (const uint8_t *)SR_HOST(addr);
    for (uint32_t i = 0; i < size; i++) if (bytes[i] != value) return 0;
    return 1;
}

static int guest_rgba_matches(uint32_t addr, uint32_t width, uint32_t height,
                              const uint8_t expected[4]) {
    const uint8_t *pixels = (const uint8_t *)SR_HOST(addr);
    for (uint32_t i = 0; i < width * height; i++) {
        if (memcmp(pixels + (size_t)i * 4u, expected, 4u) != 0) return 0;
    }
    return 1;
}

/* ---- swizzled VRAM mirror oracle (#1049) ---------------------------------------------------
 * The physical eDRAM byte a CPU address reaches is sr_vram_cpu_address(); the helpers below read
 * and compare physical bytes directly, never through the writer under test. */
#define VRAM_PHYS_BYTES  0x00200000u
#define VRAM_SENTINEL    0xA5u

static uint8_t *vram_phys_byte(uint32_t guest_addr) {
    return g_mem + (int32_t)(sr_vram_cpu_address(guest_addr) - SR_RAM_BASE);
}

static void vram_fill_sentinel(void) {
    memset(vram_phys_byte(SR_VRAM_CPU_BASE), (int)VRAM_SENTINEL, VRAM_PHYS_BYTES);
}

static uint32_t vram_changed_bytes(void) {
    const uint8_t *vram = vram_phys_byte(SR_VRAM_CPU_BASE);
    uint32_t changed = 0;
    for (uint32_t i = 0; i < VRAM_PHYS_BYTES; i++) if (vram[i] != VRAM_SENTINEL) changed++;
    return changed;
}

/* A width x height RGBA8888 picture of one colour starting at guest address `base`, every byte
 * read from the physical address its guest address translates to. */
static int vram_rgba_matches(uint32_t base, uint32_t width, uint32_t height,
                             const uint8_t expected[4]) {
    for (uint32_t i = 0; i < width * height * 4u; i++)
        if (*vram_phys_byte(base + i) != expected[i & 3u]) return 0;
    return 1;
}

/* Destinations the movie frame writers must accept: the swizzled views, an uncached alias of
 * one, an unaligned start that makes the first piece short, plus two linear controls. */
typedef struct { uint32_t base; const char *name; int swizzled; } VramDest;
static const VramDest k_vram_dests[] = {
    { SR_VRAM_CPU_BASE + 0x00040000u,       "linear base view",         0 },
    { SR_VRAM_CPU_BASE + 0x00440000u,       "linear 0x044 view",        0 },
    { SR_VRAM_CPU_BASE + 0x00240000u,       "0x042 mirror",             1 },
    { SR_VRAM_CPU_BASE + 0x00240014u,       "0x042 mirror, unaligned",  1 },
    { SR_VRAM_CPU_BASE + 0x00640000u,       "0x046 mirror",             1 },
    { SR_VRAM_CPU_BASE + 0x00640014u,       "0x046 mirror, unaligned",  1 },
    { 0x40000000u + SR_VRAM_CPU_BASE + 0x00641F10u, "0x046 mirror, uncached alias", 1 },
};
#define VRAM_DEST_COUNT (sizeof(k_vram_dests) / sizeof(k_vram_dests[0]))

#define FIX_PICTURES 3
#define ARENA_BYTES (8u * 1024u * 1024u)
#define GUEST_BUF   (0x08000000u + 0x00400000u)   /* 4 MiB into guest RAM */
#define GUEST_VRAM_BUF (SR_VRAM_CPU_BASE + 0x00040000u)
#define GUEST_VRAM_PREFIX_BYTES 0x04000000u

typedef struct {
    int kind;
    uint32_t addr;
    uint32_t bytes;
} MediaVramEvent;

#define MEDIA_VRAM_EVENT_CAP 16384u
static MediaVramEvent media_vram_events[MEDIA_VRAM_EVENT_CAP];
static unsigned media_vram_event_count;

static void media_vram_record(int kind, uint32_t addr, uint32_t bytes) {
    if (media_vram_event_count < sizeof(media_vram_events) / sizeof(media_vram_events[0])) {
        MediaVramEvent *event = &media_vram_events[media_vram_event_count++];
        event->kind = kind;
        event->addr = addr;
        event->bytes = bytes;
    }
}

static void media_vram_dirty(uint32_t addr, uint32_t bytes) {
    media_vram_record(2, addr, bytes);
}

static int media_vram_write_prepare(uint32_t addr, uint32_t bytes) {
    media_vram_record(1, addr, bytes);
    return 1;
}

static int media_vram_pending(void) {
    return 1;
}

/* ---- source-authored H.264 elementary stream -------------------------------------------- */

typedef struct {
    uint8_t *d; uint32_t cap, n;
    uint32_t acc; int bits;
    int overflow;
} BitW;

static void bw_byte(BitW *w, uint8_t b) {
    if (w->n >= w->cap) { w->overflow = 1; return; }
    w->d[w->n++] = b;
}
static void bw_bit(BitW *w, int b) {
    w->acc = (w->acc << 1) | (uint32_t)(b & 1);
    if (++w->bits == 8) { bw_byte(w, (uint8_t)w->acc); w->acc = 0; w->bits = 0; }
}
static void bw_u(BitW *w, uint32_t v, int n) {
    for (int i = n - 1; i >= 0; i--) bw_bit(w, (int)((v >> (unsigned)i) & 1u));
}
static void bw_ue(BitW *w, uint32_t v) {
    uint32_t x = v + 1u;
    int n = 0;
    for (uint32_t t = x; t; t >>= 1) n++;
    for (int i = 0; i < n - 1; i++) bw_bit(w, 0);
    bw_u(w, x, n);
}
static void bw_pad(BitW *w) { while (w->bits) bw_bit(w, 0); }
static void bw_trailing(BitW *w) { bw_bit(w, 1); bw_pad(w); }
/* Byte run inside a bit stream (I_PCM macroblock payload); pads partial bits with zeros,
 * which is exactly the pcm_alignment_zero_bit the syntax defines. */
static void bw_raw(BitW *w, const uint8_t *p, uint32_t n) {
    bw_pad(w);
    if (w->n + n > w->cap) { w->overflow = 1; return; }
    memcpy(w->d + w->n, p, n);
    w->n += n;
}

typedef struct { uint8_t *d; uint32_t cap, n; int overflow; } ByteOut;
static void bo_raw(ByteOut *o, const uint8_t *p, uint32_t n) {
    if (o->n + n > o->cap) { o->overflow = 1; return; }
    memcpy(o->d + o->n, p, n);
    o->n += n;
}
static void bo_byte(ByteOut *o, uint8_t b) { bo_raw(o, &b, 1); }
/* Annex-B NAL unit: start code, header, then the RBSP with emulation prevention. */
static void emit_nal(ByteOut *o, uint8_t hdr, const BitW *rbsp) {
    static const uint8_t start_code[3] = { 0, 0, 1 };
    bo_raw(o, start_code, 3u);
    bo_byte(o, hdr);
    int zeros = 0;
    for (uint32_t i = 0; i < rbsp->n; i++) {
        uint8_t b = rbsp->d[i];
        if (zeros >= 2 && b <= 3u) { bo_byte(o, 3u); zeros = 0; }
        bo_byte(o, b);
        zeros = (b == 0) ? zeros + 1 : 0;
    }
}

#define FIX_W_MBS 4
#define FIX_H_MBS 4

static void write_sps_ex(BitW *w, uint32_t w_mbs, uint32_t h_mbs) {
    bw_u(w, 66u, 8);          /* profile_idc: baseline */
    bw_u(w, 0u, 8);           /* constraint set flags  */
    bw_u(w, 30u, 8);          /* level_idc 3.0         */
    bw_ue(w, 0u);             /* seq_parameter_set_id */
    bw_ue(w, 0u);             /* log2_max_frame_num_minus4 */
    bw_ue(w, 0u);             /* pic_order_cnt_type */
    bw_ue(w, 0u);             /* log2_max_pic_order_cnt_lsb_minus4 */
    bw_ue(w, 1u);             /* max_num_ref_frames */
    bw_bit(w, 0);             /* gaps_in_frame_num_value_allowed_flag */
    bw_ue(w, w_mbs - 1u);     /* pic_width_in_mbs_minus1 */
    bw_ue(w, h_mbs - 1u);     /* pic_height_in_map_units_minus1 */
    bw_bit(w, 1);             /* frame_mbs_only_flag */
    bw_bit(w, 1);             /* direct_8x8_inference_flag */
    bw_bit(w, 0);             /* frame_cropping_flag */
    bw_bit(w, 0);             /* vui_parameters_present_flag */
    bw_trailing(w);
}

static void write_pps(BitW *w) {
    bw_ue(w, 0u);             /* pic_parameter_set_id */
    bw_ue(w, 0u);             /* seq_parameter_set_id */
    bw_bit(w, 0);             /* entropy_coding_mode_flag: CAVLC */
    bw_bit(w, 0);             /* bottom_field_pic_order_in_frame_present_flag */
    bw_ue(w, 0u);             /* num_slice_groups_minus1 */
    bw_ue(w, 0u);             /* num_ref_idx_l0_default_active_minus1 */
    bw_ue(w, 0u);             /* num_ref_idx_l1_default_active_minus1 */
    bw_bit(w, 0);             /* weighted_pred_flag */
    bw_u(w, 0u, 2);           /* weighted_bipred_idc */
    bw_ue(w, 0u);             /* pic_init_qp_minus26 (se(0)) */
    bw_ue(w, 0u);             /* pic_init_qs_minus26 (se(0)) */
    bw_ue(w, 0u);             /* chroma_qp_index_offset (se(0)) */
    bw_bit(w, 0);             /* deblocking_filter_control_present_flag */
    bw_bit(w, 0);             /* constrained_intra_pred_flag */
    bw_bit(w, 0);             /* redundant_pic_cnt_present_flag */
    bw_trailing(w);
}

/* When set, every I_PCM sample differs with its position (the YCbCr layout test); otherwise each
 * picture is flat. */
static int s_fixture_textured;

/* One IDR picture, every macroblock I_PCM, so luma and chroma are exactly (y, cb, cr). */
static void write_idr_ex(BitW *w, int picture, uint32_t w_mbs, uint32_t h_mbs, uint8_t y, uint8_t cb, uint8_t cr) {
    uint8_t pcm[256 + 64 + 64];
    memset(pcm, y, 256u);
    memset(pcm + 256, cb, 64u);
    memset(pcm + 320, cr, 64u);
    bw_ue(w, 0u);                       /* first_mb_in_slice */
    bw_ue(w, 2u);                       /* slice_type: I */
    bw_ue(w, 0u);                       /* pic_parameter_set_id */
    bw_u(w, (uint32_t)(picture % 16), 4);   /* frame_num */
    bw_ue(w, (uint32_t)(picture % 2));      /* idr_pic_id */
    bw_u(w, 0u, 4);                     /* pic_order_cnt_lsb */
    bw_bit(w, 0);                       /* dec_ref_pic_marking.no_output_of_prior_pics_flag */
    bw_bit(w, 0);                       /* dec_ref_pic_marking.long_term_reference_flag */
    bw_ue(w, 0u);                       /* slice_qp_delta (se(0)) */
    for (uint32_t mb = 0; mb < w_mbs * h_mbs; mb++) {
        if (s_fixture_textured)         /* 1..254: no sample is 0 */
            for (uint32_t i = 0; i < (uint32_t)sizeof(pcm); i++)
                pcm[i] = (uint8_t)(1u + (y + i * 7u + mb * 29u) % 254u);
        bw_ue(w, 25u);                  /* mb_type: I_PCM */
        bw_raw(w, pcm, (uint32_t)sizeof(pcm));
    }
    bw_trailing(w);
}

/* Decoded plane values per picture.  Chosen so the BT.601 limited-range conversion lands on
 * values that are stable, non-clipping, and easy to state as a literal expectation. */
static const uint8_t k_y[FIX_PICTURES]  = { 200u, 128u, 128u };
static const uint8_t k_cb[FIX_PICTURES] = {  90u, 128u, 160u };
static const uint8_t k_cr[FIX_PICTURES] = { 160u, 128u,  96u };

/* One access unit = access-unit delimiter + (on the first picture) parameter sets + IDR. */
static void build_au_ex(int picture, uint32_t w_mbs, uint32_t h_mbs,
                        uint8_t y, uint8_t cb, uint8_t cr, ByteOut *out) {
    static const uint8_t aud[5] = { 0, 0, 1, 0x09, 0x10 };
    BitW w;
    uint8_t scratch[8192];
    bo_raw(out, aud, sizeof(aud));
    if (picture == 0) {
        w.d = scratch; w.cap = sizeof(scratch); w.n = 0; w.acc = 0; w.bits = 0; w.overflow = 0;
        write_sps_ex(&w, w_mbs, h_mbs);
        CHECK(!w.overflow, "SPS fits the scratch buffer");
        emit_nal(out, 0x67, &w);
        w.n = 0; w.acc = 0; w.bits = 0; w.overflow = 0;
        write_pps(&w);
        CHECK(!w.overflow, "PPS fits the scratch buffer");
        emit_nal(out, 0x68, &w);
    }
    w.d = scratch; w.cap = sizeof(scratch); w.n = 0; w.acc = 0; w.bits = 0; w.overflow = 0;
    write_idr_ex(&w, picture, w_mbs, h_mbs, y, cb, cr);
    CHECK(!w.overflow, "IDR picture fits the scratch buffer");
    emit_nal(out, 0x65, &w);
}

/* Build the annex-B elementary stream and report each access unit's byte range, which is what
 * the producer must reproduce exactly. */
static int build_stream_ex(uint8_t *dst, uint32_t cap, uint32_t w_mbs, uint32_t h_mbs,
                           const uint8_t y[FIX_PICTURES], const uint8_t cb[FIX_PICTURES],
                           const uint8_t cr[FIX_PICTURES],
                           uint32_t au_off[FIX_PICTURES], uint32_t au_len[FIX_PICTURES],
                           uint32_t *total) {
    ByteOut o;
    o.d = dst; o.cap = cap; o.n = 0; o.overflow = 0;
    for (int i = 0; i < FIX_PICTURES; i++) {
        au_off[i] = o.n;
        build_au_ex(i, w_mbs, h_mbs, y[i], cb[i], cr[i], &o);
        au_len[i] = o.n - au_off[i];
    }
    *total = o.n;
    return !o.overflow;
}

static int build_stream(uint8_t *dst, uint32_t cap, uint32_t au_off[FIX_PICTURES],
                        uint32_t au_len[FIX_PICTURES], uint32_t *total) {
    return build_stream_ex(dst, cap, FIX_W_MBS, FIX_H_MBS, k_y, k_cb, k_cr, au_off, au_len, total);
}

/* ---- synthetic PSMF container ------------------------------------------------------------ */

typedef struct { uint8_t *data; uint32_t size; uint32_t max_chunk; int fail; } MemSource;

static int mem_read(void *opaque, uint64_t off, void *dst, uint32_t cap, uint32_t *got) {
    MemSource *m = (MemSource *)opaque;
    if (!m || !dst || !got || off > m->size) { if (got) *got = 0; return SR_PSMF_SOURCE_ERROR; }
    if (m->fail) { *got = 0; return SR_PSMF_SOURCE_ERROR; }
    if (off == m->size) { *got = 0; return SR_PSMF_SOURCE_EOF; }
    uint32_t n = m->size - (uint32_t)off;
    if (n > cap) n = cap;
    if (m->max_chunk && n > m->max_chunk) n = m->max_chunk;
    memcpy(dst, m->data + (uint32_t)off, n);
    *got = n;
    return SR_PSMF_SOURCE_DATA;
}

typedef struct { uint8_t *d; uint32_t at, cap; int overflow; } Buf;
static void put(Buf *b, const uint8_t *p, uint32_t n) {
    if (b->at + n > b->cap) { b->overflow = 1; return; }
    memcpy(b->d + b->at, p, n);
    b->at += n;
}
static void be32_at(uint8_t *p, uint32_t v) {
    p[0] = (uint8_t)(v >> 24); p[1] = (uint8_t)(v >> 16); p[2] = (uint8_t)(v >> 8); p[3] = (uint8_t)v;
}
/* A PSMF header timestamp: six big-endian bytes, the layout of the first (0x54) and last
 * (0x5a) presentation times. */
static void be48_at(uint8_t *p, int64_t v) {
    for (int i = 0; i < 6; i++) p[i] = (uint8_t)((uint64_t)v >> (40 - 8 * i));
}

static void put_pts(uint8_t *p, int64_t v) {
    uint64_t x = (uint64_t)v;
    p[0] = (uint8_t)(0x21u | (((x >> 30) & 7u) << 1) | 1u);
    p[1] = (uint8_t)(x >> 22);
    p[2] = (uint8_t)((((x >> 15) & 0x7fu) << 1) | 1u);
    p[3] = (uint8_t)(x >> 7);
    p[4] = (uint8_t)(((x & 0x7fu) << 1) | 1u);
}
/* One MPEG-PS packet: pack header, then a PES packet with a single video payload slice.
 * The '10' marker in the first flags byte is mandatory even on a packet that carries no
 * presentation time; the second flags byte states which timestamps follow, and the
 * optional-header length is what bounds them.  All three are written from `has_pts` here,
 * so a packet that claims a time is one whose declared header actually holds it. */
static void add_video_pes_sid(Buf *b, uint8_t sid, int has_pts, int64_t pts, const uint8_t *payload, uint32_t len) {
    static const uint8_t pack[14] = { 0,0,1,0xba, 0x44,0,4,0,4,1,0,0,1,0 };
    uint32_t opt = has_pts ? 5u : 0u;
    uint32_t total = 3u + opt + len;
    uint8_t hdr[9];
    put(b, pack, sizeof(pack));
    hdr[0]=0; hdr[1]=0; hdr[2]=1; hdr[3]=sid;
    hdr[4]=(uint8_t)(total >> 8); hdr[5]=(uint8_t)total;
    hdr[6]=0x80u; hdr[7]=(uint8_t)(has_pts ? 0x80u : 0x00u); hdr[8]=(uint8_t)opt;
    put(b, hdr, sizeof(hdr));
    if (has_pts) { uint8_t p[5]; put_pts(p, pts); put(b, p, sizeof(p)); }
    put(b, payload, len);
}

static void add_video_pes(Buf *b, int has_pts, int64_t pts, const uint8_t *payload, uint32_t len) {
    add_video_pes_sid(b, 0xe0u, has_pts, pts, payload, len);
}

/* Audio access unit: private-stream-1 sub-header + one self-delimiting ATRAC frame. */
static void add_audio_pes_sub(Buf *b, uint8_t sub_id, int has_pts, int64_t pts, const uint8_t *frame, uint32_t len) {
    static const uint8_t pack[14] = { 0,0,1,0xba, 0x44,0,4,0,4,1,0,0,1,0 };
    uint32_t opt = has_pts ? 5u : 0u;
    uint8_t prefix[4] = { sub_id, 0x00, 0x00, 0x00 };
    uint32_t total = 3u + opt + 4u + len;
    uint8_t hdr[9];
    put(b, pack, sizeof(pack));
    hdr[0]=0; hdr[1]=0; hdr[2]=1; hdr[3]=0xbd;
    hdr[4]=(uint8_t)(total >> 8); hdr[5]=(uint8_t)total;
    hdr[6]=0x80u; hdr[7]=(uint8_t)(has_pts ? 0x80u : 0x00u); hdr[8]=(uint8_t)opt;
    put(b, hdr, sizeof(hdr));
    if (has_pts) { uint8_t p[5]; put_pts(p, pts); put(b, p, sizeof(p)); }
    put(b, prefix, sizeof(prefix));
    put(b, frame, len);
}

static void add_audio_pes(Buf *b, const uint8_t *frame, uint32_t len) {
    add_audio_pes_sub(b, 0x00u, 0, 0, frame, len);
}
/* One self-delimiting ATRAC frame (8-byte header + data); the size field is
 * ((code1 & 3) << 8 | code2 * 8) + 0x10 total bytes. */
static uint32_t make_audio_frame(uint8_t *dst, uint32_t cap, uint8_t code1, uint8_t code2,
                                 uint8_t fill) {
    uint32_t total = (uint32_t)(((code1 & 0x03u) << 8) | ((uint32_t)code2 * 8u)) + 0x10u;
    if (total > cap) return 0;
    memset(dst, fill, total);
    dst[0] = 0x0f; dst[1] = 0xd0; dst[2] = code1; dst[3] = code2;
    dst[4] = dst[5] = dst[6] = dst[7] = 0;
    return total;
}

/* PSMF presentation base and per-picture PES times.  Picture 2 deliberately carries no PTS,
 * which is the normal case in a PSP movie and the case a consumer must extrapolate rather
 * than invent. */
#define FIX_BASE      90000
#define FIX_PTS_STEP  3003
static const int k_has_pts[FIX_PICTURES] = { 1, 1, 0 };

/* ---- fixture self-validation ------------------------------------------------------------ */
/* Building this fixture wrongly has twice produced a failure that looked like a demux or
 * decoder defect: a NAL emitted without its start code, and a PES header written without the
 * mandatory '10' marker bits.  Both are structural, so the fixture now checks its own output
 * before any test reads it -- a malformed fixture fails here, as a fixture problem, instead of
 * being diagnosed from the pipeline's behaviour. */
static void mp4_picture_marks(const uint8_t *au, uint32_t n, int picture);

static uint32_t pes_count(const uint8_t *s, uint32_t n) {
    uint32_t at = 2048u;              /* the stream begins after the PSMF header */
    uint32_t packets = 0;
    while (at + 6u <= n) {
        CHECK(memcmp(s + at, "\0\0\1\xba", 4u) == 0, "every packet is preceded by a pack header");
        at += 14u;
        if (at + 6u > n) break;
        CHECK(s[at] == 0u && s[at + 1] == 0u && s[at + 2] == 1u, "PES start-code prefix is 00 00 01");
        uint8_t id = s[at + 3];
        CHECK(id == 0xbdu || (id & 0xe0u) == 0xe0u, "PES stream id is a video or private stream");
        CHECK((s[at + 6] & 0xc0u) == 0x80u, "PES marker byte carries the mandatory '10' bits");
        uint32_t ts_flags = ((uint32_t)s[at + 7] >> 6) & 0x3u;
        uint32_t opt = s[at + 8];
        CHECK(opt == 0u || opt == 5u, "optional PES header is absent or exactly one PTS field");
        CHECK(ts_flags == (opt ? 2u : 0u),
              "PTS/DTS flags state exactly the timestamp fields the declared header holds");
        if (opt == 5u) {
            CHECK((s[at + 9] & 0xf0u) == 0x20u, "PTS field carries the '0010' prefix");
            CHECK((s[at + 9] & 1u) != 0u && (s[at + 11] & 1u) != 0u && (s[at + 13] & 1u) != 0u,
                  "PTS field carries all three marker bits");
        }
        uint32_t declared = ((uint32_t)s[at + 4] << 8) | s[at + 5];
        CHECK(declared >= 3u + opt, "declared PES length covers its own header fields");
        uint32_t span = 6u + declared;      /* start code + id + length, then the declared body */
        CHECK(at + span <= n, "declared PES length stays inside the container");
        at += span;
        packets++;
    }
    CHECK(at == n, "the packet walk consumes the container exactly, with no trailing bytes");
    return packets;
}

/* Every picture's elementary bytes must be a real Annex-B access unit: a leading access-unit
 * delimiter, and inside the stream the parameter sets before the first slice.  The scan is
 * safe as a literal search because emit_nal() escapes emulation sequences, so a NAL never
 * contains a byte pattern that could be mistaken for a start code. */
static void check_es_wellformed(const uint8_t *es, uint32_t n, const uint32_t *au_off,
                               const uint32_t *au_len) {
    int sps = 0, pps = 0, idr = 0, aud = 0, slices_before_pps = 0;
    for (uint32_t i = 0; i + 3u < n; i++) {
        if (es[i] != 0u || es[i + 1] != 0u || es[i + 2] != 1u) continue;
        uint8_t hdr = es[i + 3];
        CHECK((hdr & 0x80u) == 0u, "every start code is followed by a NAL header, not payload");
        switch (hdr & 0x1fu) {
            case 9:  aud++; break;
            case 7:  sps++; break;
            case 8:  pps++; break;
            case 5:  if (!pps) slices_before_pps++; idr++; break;
            default: break;
        }
    }
    CHECK(sps == 1, "the elementary stream carries exactly one SPS");
    CHECK(pps == 1, "the elementary stream carries exactly one PPS");
    CHECK(aud == FIX_PICTURES, "one access-unit delimiter per picture");
    CHECK(idr == FIX_PICTURES, "one IDR slice per picture");
    CHECK(slices_before_pps == 0, "the parameter sets precede the first slice");
    for (int i = 0; i < FIX_PICTURES; i++) {
        CHECK(au_len[i] > 8u, "a picture access unit is longer than its header");
        CHECK(au_off[i] + au_len[i] <= n, "a picture access unit stays inside the stream");
        mp4_picture_marks(es + au_off[i], au_len[i], i);
    }
}

/* Each picture must start with its delimiter and contain an IDR slice carrying the picture's
 * own marker, so a fixture that silently emitted the wrong picture cannot pass a test that
 * only counts bytes. */
static void mp4_picture_marks(const uint8_t *au, uint32_t n, int picture) {
    CHECK(n >= 5u && au[0] == 0u && au[1] == 0u && au[2] == 1u && (au[3] & 0x1fu) == 9u,
          "a picture access unit begins with an access-unit delimiter");
    int idr = 0;
    for (uint32_t i = 0; i + 4u < n; i++) {
        if (au[i] == 0u && au[i + 1] == 0u && au[i + 2] == 1u && (au[i + 3] & 0x1fu) == 5u) idr++;
    }
    CHECK(idr == 1, "a picture access unit carries exactly one IDR slice");
    (void)picture;
}

/* Assemble the whole container: a validated PSMF header, then the video elementary stream cut
 * into two PES packets per picture (so access units always straddle packet boundaries) with an
 * audio track interleaved between them. */
static uint8_t *build_psmf(uint32_t *size_out, uint32_t au_off[FIX_PICTURES],
                           uint32_t au_len[FIX_PICTURES]) {
    uint8_t es[65536];
    uint32_t es_len = 0;
    CHECK(build_stream(es, sizeof(es), au_off, au_len, &es_len), "generated H.264 stream fits");
    Buf b;
    (void)es_len;
    b.cap = 2048u + es_len * 2u + 4096u;
    b.d = (uint8_t *)calloc(1, b.cap);
    b.at = 2048u;
    b.overflow = 0;
    if (!b.d) return NULL;
    b.d[0] = 'P'; b.d[1] = 'S'; b.d[2] = 'M'; b.d[3] = 'F';
    be32_at(b.d + 8, 2048u);
    uint8_t aframe[128];
    for (int i = 0; i < FIX_PICTURES; i++) {
        uint32_t half = au_len[i] / 2u;
        add_video_pes(&b, k_has_pts[i], FIX_BASE + (int64_t)i * FIX_PTS_STEP, es + au_off[i], half);
        add_video_pes(&b, 0, 0, es + au_off[i] + half, au_len[i] - half);
        if (i == 0) {
            uint32_t n = make_audio_frame(aframe, sizeof(aframe), 0x28, 6, 0xa5);
            add_audio_pes(&b, aframe, n);
        }
        if (i == 1) {
            uint8_t junk[24];
            memset(junk, 0xb7, sizeof(junk));       /* no frame header: the producer resyncs */
            add_audio_pes(&b, junk, sizeof(junk));
        }
    }
    /* Trailing audio frame, so the last thing in the stream is not part of the video track. */
    {
        uint32_t n = make_audio_frame(aframe, sizeof(aframe), 0x28, 7, 0x5a);
        add_audio_pes(&b, aframe, n);
    }
    be32_at(b.d + 12, b.at - 2048u);
    CHECK(!b.overflow, "synthetic PSMF container fits its buffer");
    /* The fixture proves its own structure before any test reads it. */
    CHECK(pes_count(b.d, b.at) >= (uint32_t)(FIX_PICTURES * 2 + 2),
          "the container holds every packet the builder wrote");
    check_es_wellformed(es, es_len, au_off, au_len);
    *size_out = b.at;
    return b.d;
}

/* ---- tests ------------------------------------------------------------------------------ */

static SrPsmfProducer *open_fixture(uint8_t *data, uint32_t size, MemSource *mem,
                                    uint32_t chunk) {
    mem->data = data; mem->size = size; mem->max_chunk = chunk; mem->fail = 0;
    SrPsmfSource source;
    source.read = mem_read;
    source.opaque = mem;
    source.size = size;
    return sr_psmf_producer_open(&source, FIX_BASE);
}

/* The producer must reproduce, byte for byte, the access units the fixture generator wrote,
 * while reading the container in fragments that never align with a packet boundary. */
static void test_demux_and_au_contract(void) {
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    CHECK(bytes != NULL, "fixture allocated");
    if (!bytes) return;
    flight_media_test_milestone(SR_FLIGHT_MEDIA_TEST_SOURCE_READY, size, FIX_PICTURES, 0u);
    /* The generator is deterministic, so the expected elementary stream can be rebuilt here
     * and compared against what the producer hands back. */
    static uint8_t es[65536];
    uint32_t es_total = 0;
    CHECK(build_stream(es, sizeof(es), au_off, au_len, &es_total), "expected stream rebuilds");

    MemSource mem;
    SrPsmfProducer *p = open_fixture(bytes, size, &mem, 7u);   /* 7-byte reads */
    CHECK(p != NULL, "producer opens the synthetic PSMF");
    if (!p) { free(bytes); return; }
    flight_media_test_milestone(SR_FLIGHT_MEDIA_TEST_PRODUCER_OPEN,
                                sr_psmf_producer_video_streams(p),
                                sr_psmf_producer_audio_streams(p), 7u);

    uint32_t got_sizes[FIX_PICTURES + 2];
    uint32_t got_pts[FIX_PICTURES + 2];
    int got_has_pts[FIX_PICTURES + 2];
    uint8_t *got_bytes[FIX_PICTURES + 2];
    int n = 0;
    for (int guard = 0; guard < 4096 && !sr_psmf_producer_eof(p); guard++) {
        sr_psmf_producer_pump(p, 1);
        SrPsmfAu au;
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) {
            CHECK(n < FIX_PICTURES + 2, "no more video access units than pictures were written");
            if (n < FIX_PICTURES + 2) {
                got_sizes[n] = au.size;
                got_pts[n] = (uint32_t)au.pts;
                got_has_pts[n] = au.has_pts != 0;
                got_bytes[n] = au.data;
                au.data = NULL;
            }
            sr_psmf_au_release(&au);
            if (n < FIX_PICTURES + 2) {
                flight_media_test_milestone(SR_FLIGHT_MEDIA_TEST_AU_READY,
                                            (uint32_t)n, got_sizes[n],
                                            (uint32_t)got_has_pts[n]);
            }
            n++;
        }
    }
    CHECK(n == FIX_PICTURES, "one video access unit per authored picture");
    for (int i = 0; i < FIX_PICTURES && i < n; i++) {
        CHECK(got_sizes[i] == au_len[i], "access unit size matches the authored picture");
        if (got_sizes[i] == au_len[i])
            CHECK(memcmp(got_bytes[i], es + au_off[i], au_len[i]) == 0,
                  "access unit bytes match the authored elementary stream");
        CHECK(got_has_pts[i] == k_has_pts[i],
              "PES presentation-time presence survives AU formation");
        if (k_has_pts[i])
            CHECK(got_pts[i] == (uint32_t)(i * FIX_PTS_STEP),
                  "timestamp normalized against the PSMF presentation base");
        if (!k_has_pts[i])
            CHECK(!got_has_pts[i], "a packet with no PTS is reported as unknown, not invented");
        free(got_bytes[i]);
    }

    SrPsmfProducerStats st;
    sr_psmf_producer_stats(p, &st);
    MEDIA_DEBUG("demux: bytes=%llu packs=%llu pes=%llu vpes=%llu apes=%llu vau=%llu aau=%llu"
                " pf=%llu sf=%llu fail_at=%llu failed=%d eof=%d first=%lld last=%lld\n",
                (unsigned long long)st.bytes_read, (unsigned long long)st.packs,
                (unsigned long long)st.pes_packets, (unsigned long long)st.video_pes,
                (unsigned long long)st.audio_pes, (unsigned long long)st.video_aus,
                (unsigned long long)st.audio_aus, (unsigned long long)st.parser_failures,
                (unsigned long long)st.source_failures, (unsigned long long)st.fail_offset,
                st.failed, st.eof, (long long)st.first_pts, (long long)st.last_pts);
    CHECK(st.video_aus == FIX_PICTURES, "producer counts every picture");
    CHECK(st.audio_aus >= 1, "the interleaved audio track is demuxed independently");
    CHECK(st.source_failures == 0, "fragmented reads never report a source failure");
    CHECK(st.failed == 0, "no parser failure on well-formed input");
    CHECK(st.eof, "the producer reaches end of file");
    flight_media_test_milestone(SR_FLIGHT_MEDIA_TEST_EOF,
                                (uint32_t)st.video_aus, (uint32_t)st.audio_aus,
                                st.eof ? 1u : 0u);
    sr_psmf_producer_close(p);
    free(bytes);
}

/* The generated stream feeds a deterministic consumer-stage model so both video and audio
 * accounting can cover warm-up hold, normal delivery, rejection, and EOS disposition even on
 * platforms whose real media backend is unavailable. Real H.264 output accounting is checked
 * separately below. */
static void test_media_disposition_conservation(void) {
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    if (!bytes) { CHECK(0, "disposition fixture allocated"); return; }
    MemSource mem;
    SrPsmfProducer *p = open_fixture(bytes, size, &mem, 512u);
    CHECK(p != NULL, "producer opens for disposition accounting");
    if (!p) { free(bytes); return; }

    uint64_t video_aus = 0, audio_aus = 0;
    for (int guard = 0; guard < 4096 && !sr_psmf_producer_eof(p); guard++) {
        sr_psmf_producer_pump(p, 4);
        SrPsmfAu au;
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                         SR_PSMF_MEDIA_SUBMITTED);
            video_aus++;
            sr_psmf_au_release(&au);
        }
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_AUDIO, &au)) {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_AUDIO,
                                         SR_PSMF_MEDIA_SUBMITTED);
            audio_aus++;
            sr_psmf_au_release(&au);
        }
    }
    CHECK(sr_psmf_producer_eof(p), "disposition fixture reaches EOS");
    CHECK(video_aus == FIX_PICTURES, "disposition fixture submits each picture once");
    CHECK(audio_aus >= 2, "disposition fixture submits interleaved audio blocks");

    for (uint64_t i = 0; i < video_aus; i++) {
        sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO, SR_PSMF_MEDIA_DECODED);
        if (i == 0) {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                         SR_PSMF_MEDIA_WARMUP_HELD);
        } else if (i + 1 == video_aus) {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                         SR_PSMF_MEDIA_EOS_DRAINED);
        } else {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                         SR_PSMF_MEDIA_DELIVERED);
        }
    }
    for (uint64_t i = 0; i < audio_aus; i++) {
        sr_psmf_producer_media_stage(p, SR_PSMF_AU_AUDIO, SR_PSMF_MEDIA_DECODED);
        if (i == 0) {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_AUDIO,
                                         SR_PSMF_MEDIA_WARMUP_HELD);
        } else if (i + 1 == audio_aus) {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_AUDIO,
                                         SR_PSMF_MEDIA_REJECTED);
        } else {
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_AUDIO,
                                         SR_PSMF_MEDIA_DELIVERED);
        }
    }

    SrPsmfProducerStats st;
    sr_psmf_producer_stats(p, &st);
    CHECK(st.video_warmup_held == 1 && st.audio_warmup_held == 1,
          "warm-up outputs remain explicitly accounted while held");
    for (int call = 0; call < 3; call++) {
        /* The first three synthetic getter calls return NO_DATA without changing a held output. */
        CHECK(st.video_warmup_held == 1 && st.audio_warmup_held == 1,
              "warm-up getter keeps decoded outputs held");
    }
    CHECK(sr_psmf_producer_resolve_warmup_hold(p, SR_PSMF_AU_VIDEO,
                                                SR_PSMF_MEDIA_DELIVERED),
          "video warm-up output transitions to delivery");
    CHECK(sr_psmf_producer_resolve_warmup_hold(p, SR_PSMF_AU_AUDIO,
                                                SR_PSMF_MEDIA_DELIVERED),
          "audio warm-up output transitions to delivery");
    sr_psmf_producer_stats(p, &st);

    check_media_conservation("video", st.video_decoded, st.video_delivered,
                             st.video_warmup_held, st.video_eos_drained,
                             st.video_rejected);
    check_media_conservation("audio", st.audio_decoded, st.audio_delivered,
                             st.audio_warmup_held, st.audio_eos_drained,
                             st.audio_rejected);
    CHECK(st.video_submitted == video_aus && st.video_decoded == video_aus,
          "video submission and decode counters are exact");
    CHECK(st.video_delivered == video_aus - 1 && st.video_eos_drained == 1 &&
              st.video_rejected == 0 && st.video_warmup_held == 0,
          "video dispositions classify warm-up and EOS outputs");
    CHECK(st.audio_submitted == audio_aus && st.audio_decoded == audio_aus,
          "audio submission and decode counters are exact");
    CHECK(st.audio_delivered == audio_aus - 1 && st.audio_rejected == 1 &&
              st.audio_eos_drained == 0 && st.audio_warmup_held == 0,
          "audio dispositions classify warm-up delivery and rejection");

    sr_psmf_producer_close(p);
    free(bytes);
}

/* One decoder, the producer's own access units, the guest display buffer. */
/* A backend reports the decoder's own output layout, never a converted format: NV12 for Media
 * Foundation, planar YUV420P for libavcodec. Both are explicit native 4:2:0 formats. */
static int native_decoder_format(SrH264PixelFormat f) {
    return f == SR_H264_PIXEL_NATIVE_NV12 || f == SR_H264_PIXEL_NATIVE_YUV420P;
}

#if defined(SR_H264_FFMPEG)
static void check_ffmpeg_output_pts(const SrH264FrameInfo *info,
                                    int *known_count, int *unknown_count) {
    CHECK(info->has_pts == 0 || info->has_pts == 1,
          "FFmpeg frame timestamp presence is a strict boolean");
    if (info->has_pts) {
        CHECK(info->pts == 0 || info->pts == FIX_PTS_STEP,
              "FFmpeg reports only submitted, normalized access-unit PTS values");
        (*known_count)++;
    } else {
        CHECK(info->pts == -1,
              "an FFmpeg frame without a source PTS remains explicitly unknown");
        (*unknown_count)++;
    }
}
#endif

static void test_video_eos_waits_for_all_access_units(void) {
    CHECK(!sr_hle_test_psmf_video_eos_gate(0, 0, 0, 0),
          "decoder EOS stays closed before parser EOF");
    CHECK(!sr_hle_test_psmf_video_eos_gate(1, 1, 0, 0),
          "decoder EOS waits for the player video queue");
    CHECK(!sr_hle_test_psmf_video_eos_gate(1, 0, 1, 0),
          "decoder EOS waits for producer-owned video access units");
    CHECK(!sr_hle_test_psmf_video_eos_gate(1, 0, 0, 1),
          "decoder EOS waits for the producer's trailing video bytes");
    CHECK(sr_hle_test_psmf_video_eos_gate(1, 0, 0, 0),
          "decoder EOS opens after every video input queue is empty");
    CHECK(sr_hle_test_psmf_video_submit_limit(0) == PSMF_OUT_PTS_RING,
          "normal decode keeps the measured presentation lead bound");
    /* MUTANT: the earlier bound of 8 -- fails here; a decoder that fills a 16-frame picture
     * buffer before its first output never receives the picture that releases one. */
    CHECK(sr_hle_test_psmf_video_submit_limit(0) > PSMF_H264_MAX_DPB_FRAMES,
          "normal decode can submit a full H.264 picture buffer and the picture that releases it");
    CHECK(sr_hle_test_psmf_video_submit_limit(1) == PSMF_OUT_PTS_CAPACITY &&
              PSMF_OUT_PTS_CAPACITY == PSMF_OUT_PTS_RING +
                  PSMF_Q_DEPTH + SR_PSMF_QUEUE_DEPTH + 1u,
          "EOS can submit the bounded producer/player tail without overwriting PTS entries");
}

static void test_real_decode_into_guest_buffer(void) {
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    if (!bytes) { CHECK(0, "fixture allocated"); return; }
    MemSource mem;
    SrPsmfProducer *p = open_fixture(bytes, size, &mem, 512u);
    CHECK(p != NULL, "producer opens for the decode test");

    int dec = sr_h264_create();
    if (dec < 0 || !p) {
        fprintf(stderr, "SKIP: no H.264 backend on this build (demux contract still verified)\n");
        sr_psmf_producer_close(p);
        free(bytes);
        return;
    }

    /* Feed exactly like the guest player: every produced access unit goes to the decoder, and
     * frames are pulled while the stream is still being fed (eos = 0). */
    int frames_before_eos = 0, frames_after_eos = 0, aus = 0;
#if defined(SR_H264_FFMPEG)
    int ffmpeg_known_pts = 0, ffmpeg_unknown_pts = 0;
#endif
    int64_t last_pts = -1;
    SrH264FrameTarget target;
    SrH264FrameInfo info;
    memset(&target, 0, sizeof(target));
    target.kind = SR_H264_TARGET_GUEST;
    target.guest_buffer = GUEST_BUF;
    target.frame_width = 64;
    target.pixel_mode = 3;
    for (int guard = 0; guard < 65536; guard++) {
        sr_psmf_producer_pump(p, 4);
        SrPsmfAu au;
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) {
            if (au.has_pts) {
                CHECK(au.pts >= last_pts, "known video timestamps remain ordered");
                last_pts = au.pts;
            }
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                         SR_PSMF_MEDIA_SUBMITTED);
            int submit_rc = sr_h264_submit_au_timed(dec, au.data, au.size,
                                                    au.pts, au.has_pts);
            CHECK(submit_rc == 0, "a complete picture is accepted by the decoder");
            sr_psmf_au_release(&au);
            aus++;
        }
        int r = sr_h264_frame_ex(dec, 0, &target, &info);
        CHECK(r >= 0, "decoding a fed access unit never fails");
        if (r > 0) {
#if defined(SR_H264_FFMPEG)
            check_ffmpeg_output_pts(&info, &ffmpeg_known_pts, &ffmpeg_unknown_pts);
#endif
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                         SR_PSMF_MEDIA_DECODED);
            int valid = info.width == 64 && info.height == 64 &&
                        native_decoder_format(info.native_format) &&
                        info.delivered_format == SR_H264_PIXEL_8888 &&
                        info.stride == 64 * 4;
            CHECK(info.width == 64 && info.height == 64,
                  "decoded frame reports the fixture dimensions");
            CHECK(native_decoder_format(info.native_format),
                  "decoder-native format remains explicit");
            CHECK(info.delivered_format == SR_H264_PIXEL_8888,
                  "guest delivery format remains explicit");
            CHECK(info.stride == 64 * 4, "guest delivery stride is explicit");
            sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                         valid ? SR_PSMF_MEDIA_DELIVERED :
                                                 SR_PSMF_MEDIA_REJECTED);
            frames_before_eos++;
            flight_media_test_milestone(SR_FLIGHT_MEDIA_TEST_FRAME_READY,
                                        (uint32_t)frames_before_eos,
                                        (uint32_t)info.width, (uint32_t)info.height);
        }
        if (sr_psmf_producer_eof(p) && r == 0) break;
    }
    MEDIA_DEBUG("decode: aus=%d before_eos=%d after_eos=%d\n", aus, frames_before_eos, frames_after_eos);
    CHECK(aus == FIX_PICTURES, "every picture reached the decoder");
    CHECK(frames_before_eos >= 1, "a real decoder produced a picture before end of stream");

    /* Drain pictures the codec buffered. A low-delay backend may already have delivered the
     * final picture before EOS, so the assertions below check conservation and reject duplicates
     * without requiring a particular buffering choice. */
    for (int i = 0; i < 16; i++) {
        int r = sr_h264_drain(dec, &target, &info);
        CHECK(r >= 0, "end-of-stream drain never fails");
        if (r <= 0) break;
#if defined(SR_H264_FFMPEG)
        check_ffmpeg_output_pts(&info, &ffmpeg_known_pts, &ffmpeg_unknown_pts);
#endif
        sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                     SR_PSMF_MEDIA_DECODED);
        int valid = info.width == 64 && info.height == 64 &&
                    native_decoder_format(info.native_format) &&
                    info.delivered_format == SR_H264_PIXEL_8888 &&
                    info.stride == 64 * 4;
        CHECK(valid, "EOS-drained frame satisfies the fixture contract");
        sr_psmf_producer_media_stage(p, SR_PSMF_AU_VIDEO,
                                     valid ? SR_PSMF_MEDIA_EOS_DRAINED :
                                             SR_PSMF_MEDIA_REJECTED);
        frames_after_eos++;
    }
    CHECK(frames_before_eos + frames_after_eos == FIX_PICTURES,
          "the stream yields exactly one picture per authored picture across EOS drain");
#if defined(SR_H264_FFMPEG)
    CHECK(ffmpeg_known_pts == 2 && ffmpeg_unknown_pts == 1,
          "FFmpeg preserves two known PTS values and one unknown picture time");
#endif
    /* Repeated end-of-stream must not duplicate output. */
    int extra = 0;
    for (int i = 0; i < 8; i++) if (sr_h264_drain(dec, &target, &info) > 0) extra++;
    CHECK(extra == 0, "a drained decoder produces no further pictures");
    static const uint8_t post_eos_au[] = {0, 0, 1, 0x09, 0x10};
    CHECK(sr_h264_submit_au(dec, post_eos_au, sizeof(post_eos_au)) < 0,
          "a drained decoder refuses new input until reset");
    CHECK(sr_h264_reset(dec) == 0, "reset reopens a drained decoder for a new stream");
    CHECK(sr_h264_submit_au(dec, post_eos_au, sizeof(post_eos_au)) == 0,
          "a reset decoder accepts a new access unit");
    SrPsmfProducerStats st;
    sr_psmf_producer_stats(p, &st);
    check_media_conservation("real H.264 video", st.video_decoded,
                             st.video_delivered, st.video_warmup_held,
                             st.video_eos_drained, st.video_rejected);
    CHECK(st.video_submitted == (uint64_t)aus,
          "real H.264 submission counter matches accepted pictures");
    CHECK(st.video_decoded == (uint64_t)(frames_before_eos + frames_after_eos),
          "real H.264 decode counter matches output pictures");
    CHECK(st.video_delivered == (uint64_t)frames_before_eos &&
              st.video_eos_drained == (uint64_t)frames_after_eos &&
              st.video_warmup_held == 0 && st.video_rejected == 0,
          "real H.264 outputs have exact getter and EOS dispositions");
    sr_h264_destroy(dec);
    sr_psmf_producer_close(p);
    free(bytes);
}

/* Decoded pixels are exactly the authored YCbCr, converted with BT.601 limited range. */
static void test_decoded_pixels(void) {
    static const uint8_t expect[FIX_PICTURES][3] = {
        { 255u, 203u, 138u },     /* (200,  90, 160) */
        { 130u, 130u, 130u },     /* (128, 128, 128) */
        {  79u, 144u, 195u },     /* (128, 160,  96) */
    };
    int dec = sr_h264_create();
    if (dec < 0) {
        fprintf(stderr, "SKIP: pixel assertions need a real H.264 backend\n");
        return;
    }
    uint8_t host[64 * 272 * 4];
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    if (!bytes) { CHECK(0, "fixture allocated"); sr_h264_destroy(dec); return; }
    MemSource mem;
    SrPsmfProducer *p = open_fixture(bytes, size, &mem, 2048u);
    if (!p) { CHECK(0, "producer opens"); free(bytes); sr_h264_destroy(dec); return; }

    int seen = 0;
    SrH264FrameTarget target;
    SrH264FrameInfo info;
    memset(&target, 0, sizeof(target));
    target.kind = SR_H264_TARGET_HOST;
    target.host_buffer = host;
    target.host_width = 64;
    target.host_height = 272;
    target.host_stride = 64 * 4;
    for (int guard = 0; guard < 65536 && seen < FIX_PICTURES; guard++) {
        SrPsmfAu au;
        sr_psmf_producer_pump(p, 2);
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) {
            sr_h264_submit_au(dec, au.data, au.size);
            sr_psmf_au_release(&au);
        }
        int eos = sr_psmf_producer_eof(p);
        while (seen < FIX_PICTURES) {
            int r = sr_h264_frame_ex(dec, eos, &target, &info);
            if (r < 0) { CHECK(0, "host decode failed"); break; }
            if (r == 0) break;
            CHECK(info.width == 64 && info.height == 64, "host frame reports the fixture dimensions");
            CHECK(native_decoder_format(info.native_format),
                  "host delivery preserves the native format distinction");
            CHECK(info.delivered_format == SR_H264_PIXEL_RGBA8888,
                  "host delivery reports RGBA8888 explicitly");
            CHECK(info.stride == 64 * 4, "host delivery reports its row stride");
            const uint8_t *want = expect[seen];
            int bad = 0;
            for (int y = 0; y < 64 && !bad; y++)
                for (int x = 0; x < 64; x++) {
                    const uint8_t *px = host + ((size_t)y * 64u + (size_t)x) * 4u;
                    if (px[0] != want[0] || px[1] != want[1] || px[2] != want[2] || px[3] != 0xFFu) {
                        bad = 1; break;
                    }
                }
            CHECK(!bad, "every decoded pixel matches the authored picture");
            seen++;
        }
    }
    CHECK(seen == FIX_PICTURES, "the decoder delivered every authored picture");
    sr_psmf_producer_close(p);
    free(bytes);
    sr_h264_destroy(dec);
}

/* A fresh decoder instance must never expose the previous stream's trailing picture. */
static void test_instance_isolation(void) {
    int dec = sr_h264_create();
    if (dec < 0) { fprintf(stderr, "SKIP: instance isolation needs a real H.264 backend\n"); return; }
    /* Nothing was ever fed: end of stream on an empty instance reports "no picture". */
    CHECK(sr_h264_frame(dec, 1, GUEST_BUF, 64, 3) == 0, "an unfed decoder produces no picture");
    sr_h264_destroy(dec);

    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint8_t es[65536];
    uint32_t es_len = 0;
    if (!build_stream(es, sizeof(es), au_off, au_len, &es_len)) { CHECK(0, "stream builds"); return; }

    int first = sr_h264_create();
    CHECK(first >= 0, "decoder instance for the isolation test");
    if (first < 0) return;
    for (int i = 0; i < FIX_PICTURES; i++) sr_h264_submit_au(first, es + au_off[i], au_len[i]);
    int got = 0;
    for (int i = 0; i < 16; i++) {
        int r = sr_h264_frame(first, 1, GUEST_BUF, 64, 3);
        if (r <= 0) break;
        got++;
    }
    MEDIA_DEBUG("isolation: first instance pictures=%d\n", got);
    CHECK(got >= 1, "the first instance decodes");
    sr_h264_destroy(first);

    int second = sr_h264_create();
    CHECK(second >= 0, "decoder instance after destroy");
    if (second < 0) return;
    int stale = 0;
    for (int i = 0; i < 8; i++) if (sr_h264_frame(second, 1, GUEST_BUF, 64, 3) > 0) stale++;
    CHECK(stale == 0, "a restarted decoder exposes no picture from the previous stream");
    sr_h264_destroy(second);
}

/* An unusable destination must not be reported as a produced frame, and must not poison the
 * decoder for the pictures that follow. */
static void test_destination_refusal(void) {
    int dec = sr_h264_create();
    if (dec < 0) { fprintf(stderr, "SKIP: destination checks need a real H.264 backend\n"); return; }
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint8_t es[65536];
    uint32_t es_len = 0;
    if (!build_stream(es, sizeof(es), au_off, au_len, &es_len)) { CHECK(0, "stream builds"); return; }

    /* Out-of-range guest buffer: the picture exists but cannot be delivered. */
    sr_h264_submit_au(dec, es + au_off[0], au_len[0]);
    sr_h264_submit_au(dec, es + au_off[1], au_len[1]);
    int r = sr_h264_frame(dec, 0, 0x0FFFFFF0u, 64, 3);
    CHECK(r <= 0, "an unusable destination is not reported as a produced frame");

    /* The decoder is still usable for the next picture. */
    int ok = 0;
    for (int i = 0; i < 8; i++) if (sr_h264_frame(dec, 1, GUEST_BUF, 64, 3) > 0) { ok = 1; break; }
    CHECK(ok, "a refused destination does not poison the decoder");
    sr_h264_destroy(dec);
}

/* The sceMpeg consumption path (feed -> au_take -> frame) must be unchanged by the EOS
 * release: each taken access unit still yields exactly one picture, including the last. */
static void test_legacy_feed_take_path(void) {
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    if (!bytes) { CHECK(0, "fixture allocated"); return; }
    int dec = sr_h264_create();
    if (dec < 0) {
        fprintf(stderr, "SKIP: the mpeg.c consumption path needs a real H.264 backend\n");
        free(bytes);
        return;
    }
    CHECK(sr_h264_feed(dec, bytes + 2048u, size - 2048u) == 0,
          "common program-stream demux accepts the source-owned PSMF bytes");
    const int64_t expected_pts[FIX_PICTURES] = {
        FIX_BASE, FIX_BASE + FIX_PTS_STEP, -1
    };
    uint64_t previous_consumed = 0;
    int frames = 0, taken = 0;
    for (int guard = 0; guard < 64; guard++) {
        uint64_t consumed = 0;
        int64_t pts = 0;
        int took = sr_h264_au_take(dec, 0, &consumed, &pts);
        if (took > 0) {
            CHECK(taken < FIX_PICTURES, "legacy demux does not emit extra pictures");
            if (taken < FIX_PICTURES)
                CHECK(pts == expected_pts[taken],
                      "common demux preserves raw PTS and unknown timestamp presence");
            CHECK(consumed >= previous_consumed && consumed <= size - 2048u,
                  "legacy demux consumption offsets remain within the fed PS stream");
            previous_consumed = consumed;
            taken++;
        }
        for (int i = 0; i < 8; i++) {
            int r = sr_h264_frame(dec, 0, GUEST_BUF, 64, 3);
            if (r < 0) { CHECK(0, "legacy path decode failed"); break; }
            if (r == 0) break;
            frames++;
        }
        if (took <= 0) break;
    }
    uint64_t consumed = 0;
    int64_t final_pts = 0;
    if (sr_h264_au_take(dec, 1, &consumed, &final_pts) > 0) {
        CHECK(taken < FIX_PICTURES, "EOS closes only the one trailing picture");
        if (taken < FIX_PICTURES)
            CHECK(final_pts == expected_pts[taken],
                  "EOS preserves the trailing picture's absent PTS");
        CHECK(consumed >= previous_consumed && consumed <= size - 2048u,
              "EOS consumption offset remains within the fed PS stream");
        taken++;
    }
    for (int i = 0; i < 16; i++) {
        int r = sr_h264_frame(dec, 1, GUEST_BUF, 64, 3);
        if (r < 0) { CHECK(0, "legacy path end-of-stream decode failed"); break; }
        if (r == 0) break;
        frames++;
    }
    MEDIA_DEBUG("legacy path: taken=%d frames=%d\n", taken, frames);
    CHECK(taken == FIX_PICTURES, "the demuxed stream hands out one access unit per picture");
    CHECK(frames == FIX_PICTURES, "each access unit yields exactly one decoded picture");
    sr_h264_destroy(dec);
    free(bytes);
}

typedef struct {
    const char *name;
    int (*create)(void);
    void (*destroy)(int);
    int (*reset)(int);
    int (*submit_au)(int, const uint8_t *, uint32_t);
    int (*frame_ex)(int, int, const SrH264FrameTarget *, SrH264FrameInfo *);
    int (*drain)(int, const SrH264FrameTarget *, SrH264FrameInfo *);
} SrH264ConformanceBackend;

static const SrH264ConformanceBackend conformance_backend = {
    "registry",
    sr_h264_create,
    sr_h264_destroy,
    sr_h264_reset,
    sr_h264_submit_au,
    sr_h264_frame_ex,
    sr_h264_drain
};

/* One decoder run into `dest` (a 64x64 RGBA8888 picture, three authored pictures): every
 * picture's bytes must land at the physical addresses the destination translates to, nothing else
 * may change, and the GE coherence hooks must see a prepare before each commit whose spans, taken
 * together, are exactly the physical bytes the picture occupies (#1054, #1049). */
static void guest_vram_write_coherence_case(const VramDest *dest, const uint8_t *es,
                                            const uint32_t *au_off, const uint32_t *au_len) {
    static const uint8_t expected_rgb[FIX_PICTURES][3] = {
        { 255u, 203u, 138u },
        { 130u, 130u, 130u },
        {  79u, 144u, 195u },
    };
    static uint8_t span_map[VRAM_PHYS_BYTES];
    const uint32_t picture_bytes = 64u * 64u * 4u;
    const uint32_t row_bytes = 64u * 4u;

    GeGpuHooks hooks;
    memset(&hooks, 0, sizeof(hooks));
    hooks.vram_dirty = media_vram_dirty;
    hooks.vram_write_prepare = media_vram_write_prepare;
    hooks.vram_pending = media_vram_pending;
    media_vram_event_count = 0;
    memset(media_vram_events, 0, sizeof(media_vram_events));
    g_sr_vram_read_pending = 0;
    ge_set_gpu_hooks(&hooks);
    sr_vram_mark_renderer_pending();
    vram_fill_sentinel();

    int decoder = conformance_backend.create();
    if (decoder < 0) {
#if defined(SR_H264_FFMPEG)
        CHECK(0, "the explicitly enabled FFmpeg backend creates a decoder for VRAM coherence");
#else
        fprintf(stderr, "SKIP: guest-VRAM coherence needs a real H.264 backend\n");
#endif
        ge_set_gpu_hooks(NULL);
        g_sr_vram_read_pending = 0;
        return;
    }

    for (int i = 0; i < FIX_PICTURES; i++)
        CHECK(conformance_backend.submit_au(decoder, es + au_off[i], au_len[i]) == 0,
              "the VRAM coherence fixture submits each complete picture");

    SrH264FrameTarget target;
    SrH264FrameInfo info;
    memset(&target, 0, sizeof(target));
    target.kind = SR_H264_TARGET_GUEST;
    target.guest_buffer = dest->base;
    target.frame_width = 64;
    target.pixel_mode = 3;

    int frames = 0;
    for (int guard = 0; guard < FIX_PICTURES + 4; guard++) {
        int result = conformance_backend.frame_ex(decoder, 1, &target, &info);
        if (result < 0) {
            fprintf(stderr, "  destination: %s\n", dest->name);
            CHECK(0, "a decoded picture targeting guest VRAM is accepted");
            break;
        }
        if (result == 0) break;
        CHECK(info.width == 64 && info.height == 64 && info.stride == 64 * 4,
              "the VRAM-targeted picture reports exact fixture geometry");
        if (frames < FIX_PICTURES) {
            uint8_t expected[4] = {
                expected_rgb[frames][0], expected_rgb[frames][1], expected_rgb[frames][2], 0x00u,   /* PSP alpha */
            };
            int match = vram_rgba_matches(dest->base, 64, 64, expected);
            if (!match) fprintf(stderr, "  destination: %s, picture %d\n", dest->name, frames);
            CHECK(match, "the VRAM-targeted picture writes its exact guest pixels");
        }
        frames++;
    }
    CHECK(frames == FIX_PICTURES, "the VRAM-targeted stream releases every authored picture");
    {
        const uint32_t changed = vram_changed_bytes();
        if (changed != picture_bytes)
            fprintf(stderr, "  destination: %s, %u physical bytes changed\n", dest->name,
                    (unsigned)changed);
        CHECK(changed == picture_bytes,
              "the VRAM-targeted pictures change exactly the physical bytes of the destination");
    }

    /* Event shape: one prepare then one commit per piece the writer stored. Their canonical
     * spans must cover each picture's physical bytes exactly once. */
    CHECK(media_vram_event_count != 0u && (media_vram_event_count & 1u) == 0u &&
              media_vram_event_count < MEDIA_VRAM_EVENT_CAP,
          "each CPU VRAM write publishes prepare and commit events in pairs");
    uint32_t paired = media_vram_event_count / 2u;
    int shape_ok = 1, linear_rows_ok = 1;
    for (unsigned i = 0; i < paired; i++) {
        const MediaVramEvent *prepare = &media_vram_events[i * 2u];
        const MediaVramEvent *commit = &media_vram_events[i * 2u + 1u];
        const uint32_t commit_canonical = sr_vram_cpu_aperture(commit->addr)
                                              ? sr_vram_cpu_address(commit->addr)
                                              : SR_PHYS(commit->addr);
        if (prepare->kind != 1 || commit->kind != 2 || prepare->bytes != commit->bytes ||
            prepare->addr != commit_canonical || prepare->bytes == 0u)
            shape_ok = 0;
        if (!dest->swizzled && !(prepare->bytes == row_bytes &&
                                 (prepare->addr - SR_PHYS(dest->base)) % row_bytes == 0u))
            linear_rows_ok = 0;
    }
    CHECK(shape_ok, "each prepare precedes a commit of the same physical span");
    CHECK(linear_rows_ok, "a linear destination is prepared and committed one row at a time");
    for (int f = 0; f < frames && f < FIX_PICTURES; f++) {
        /* Events are published picture by picture in order, and every picture writes the same
         * number of pieces, so picture f owns an equal slice of the list. */
        const unsigned per = paired / (unsigned)frames;
        memset(span_map, 0, sizeof(span_map));
        int covered_once = per != 0u && paired % (unsigned)frames == 0u;
        for (unsigned i = f * per; covered_once && i < (unsigned)(f + 1) * per; i++) {
            const MediaVramEvent *prepare = &media_vram_events[i * 2u];
            for (uint32_t b = 0; b < prepare->bytes; b++) {
                uint32_t off = prepare->addr + b - SR_VRAM_CPU_BASE;
                if (off >= VRAM_PHYS_BYTES || span_map[off]++) { covered_once = 0; break; }
            }
        }
        for (uint32_t i = 0; covered_once && i < picture_bytes; i++) {
            uint32_t off = sr_vram_cpu_address(dest->base + i) - SR_VRAM_CPU_BASE;
            if (span_map[off] != 1u) covered_once = 0;
        }
        if (!covered_once)
            fprintf(stderr, "  destination: %s, picture %d\n", dest->name, f);
        CHECK(covered_once,
              "each picture's prepare/commit spans cover exactly its physical bytes, once");
    }

    conformance_backend.destroy(decoder);
    ge_set_gpu_hooks(NULL);
    g_sr_vram_read_pending = 0;
}

static void test_guest_vram_write_coherence(void) {
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint8_t es[65536];
    uint32_t es_len = 0;
    CHECK(build_stream(es, sizeof(es), au_off, au_len, &es_len),
          "VRAM coherence fixture stream builds");
    if (!es_len) return;
    for (size_t d = 0; d < VRAM_DEST_COUNT; d++)
        guest_vram_write_coherence_case(&k_vram_dests[d], es, au_off, au_len);
}

static void test_backend_registry_fail_closed(void) {
    CHECK(sr_h264_select_backend("not-a-backend") == 0,
          "an unknown backend selection is refused");
    CHECK(sr_h264_select_backend("null"), "the null backend can be selected explicitly");
    CHECK(strcmp(sr_h264_selected_backend(), "null") == 0,
          "selection reports the null backend");
    CHECK(!sr_h264_backend_available(), "the null backend is not reported as usable");
    int id = sr_h264_create();
    CHECK(id < 0, "the null backend never creates a decoder instance");
    CHECK(strcmp(sr_h264_backend_unavailable_reason(), SR_H264_UNAVAILABLE_BOUNDARY) == 0,
          "selection exposes the named unavailable boundary");
    SrH264FrameTarget target;
    SrH264FrameInfo info;
    memset(&target, 0, sizeof(target));
    target.kind = SR_H264_TARGET_HOST;
    target.host_buffer = (uint8_t *)&info;
    target.host_width = 1;
    target.host_height = 1;
    target.host_stride = 4;
    CHECK(sr_h264_frame_ex(-1, 1, &target, &info) < 0,
          "an unavailable backend cannot fabricate a frame");
    CHECK(sr_h264_select_backend("auto"), "automatic backend selection can be restored");
#if defined(SR_H264_FFMPEG)
    CHECK(sr_h264_select_backend("ffmpeg"),
          "the explicitly enabled FFmpeg backend can be restored after the fail-closed checks");
#endif
}

static void test_backend_reset_and_restart(void) {
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint8_t es[65536];
    uint32_t es_len = 0;
    CHECK(build_stream(es, sizeof(es), au_off, au_len, &es_len),
          "reset fixture stream builds");
    int id = conformance_backend.create();
    if (id < 0) {
        fprintf(stderr, "SKIP: reset lifecycle needs a real H.264 backend\n");
        return;
    }
    CHECK(conformance_backend.submit_au(id, es + au_off[0], au_len[0]) == 0,
          "first stream AU is accepted");
    SrH264FrameTarget target;
    SrH264FrameInfo info;
    memset(&target, 0, sizeof(target));
    target.kind = SR_H264_TARGET_GUEST;
    target.guest_buffer = GUEST_BUF;
    target.frame_width = 64;
    target.pixel_mode = 3;
    CHECK(conformance_backend.frame_ex(id, 0, &target, &info) >= 0,
          "a decoder can be exercised before reset");
    CHECK(conformance_backend.reset(id) == 0, "decoder reset succeeds");
    for (int i = 0; i < FIX_PICTURES; i++)
        CHECK(conformance_backend.submit_au(id, es + au_off[i], au_len[i]) == 0,
              "restart stream AU is accepted");
    int frames = 0;
    for (int i = 0; i < FIX_PICTURES + 4; i++) {
        int r = conformance_backend.drain(id, &target, &info);
        if (r < 0) break;
        if (r == 0) break;
        frames++;
    }
    CHECK(frames == FIX_PICTURES, "reset exposes no stale picture and restarts at the first AU");
    conformance_backend.destroy(id);
}

static void test_backend_malformed_input(void) {
    int id = conformance_backend.create();
    if (id < 0) {
        fprintf(stderr, "SKIP: malformed-input contract needs a real H.264 backend\n");
        return;
    }
    static const uint8_t malformed[] = { 0xde, 0xad, 0xbe, 0xef, 0x01, 0x02, 0x03, 0x04 };
    CHECK(conformance_backend.submit_au(id, malformed, sizeof(malformed)) < 0,
          "malformed access-unit submission fails closed");
    conformance_backend.destroy(id);
}

static uint64_t demux_fuzz_state = 0x3194844345584D58ULL;

static uint64_t demux_fuzz_rand64(void) {
    uint64_t z = (demux_fuzz_state += 0x9E3779B97F4A7C15ULL);
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}

static void demux_fuzz_mutate(uint8_t *data, size_t size) {
    static const uint32_t values[] = {
        0, 1, 2, 3, 4, 8, 14, 16, 0x40, 0x80, 0xBD, 0xE0, 0xEF,
        0x7FFFu, 0x8000u, 0xFFFFu, 0x7FFFFFFFu, 0x80000000u, 0xFFFFFFFFu
    };
    unsigned operations = (unsigned)(demux_fuzz_rand64() % 8u) + 1u;
    for (unsigned op = 0; op < operations; op++) {
        unsigned kind = (unsigned)(demux_fuzz_rand64() % 5u);
        size_t index = (size_t)(demux_fuzz_rand64() % size);
        if (kind == 0) {
            data[index] ^= (uint8_t)(1u << (demux_fuzz_rand64() % 8u));
        } else if (kind == 1) {
            data[index] = (uint8_t)demux_fuzz_rand64();
        } else if (kind == 2 && index + 2u <= size) {
            uint16_t value = values[demux_fuzz_rand64() %
                                    (sizeof(values) / sizeof(values[0]))];
            data[index] = (uint8_t)value;
            data[index + 1] = (uint8_t)(value >> 8);
        } else if (kind == 3 && index + 4u <= size) {
            uint32_t value = values[demux_fuzz_rand64() %
                                    (sizeof(values) / sizeof(values[0]))];
            data[index] = (uint8_t)value;
            data[index + 1] = (uint8_t)(value >> 8);
            data[index + 2] = (uint8_t)(value >> 16);
            data[index + 3] = (uint8_t)(value >> 24);
        } else {
            size_t run = (size_t)(demux_fuzz_rand64() % 16u) + 1u;
            if (run > size - index) run = size - index;
            memset(data + index, (demux_fuzz_rand64() & 1u) ? 0u : 0xFFu, run);
        }
    }
}

static void test_legacy_demux_mutations(unsigned iterations) {
    if (iterations > 128u) iterations = 128u;
    demux_fuzz_state = 0x3194844345584D58ULL;
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    CHECK(bytes != NULL, "demux mutation fixture allocated");
    if (!bytes) return;
    uint8_t *mutated = (uint8_t *)malloc(size - 2048u);
    CHECK(mutated != NULL, "demux mutation buffer allocated");
    if (!mutated) { free(bytes); return; }
    unsigned attempted = 0;
    for (unsigned i = 0; i < iterations; i++) {
        memcpy(mutated, bytes + 2048u, size - 2048u);
        demux_fuzz_mutate(mutated, size - 2048u);
        int decoder = sr_h264_create();
        if (decoder < 0) {
            if (attempted == 0) fprintf(stderr, "SKIP: hostile legacy demux needs a real H.264 backend\n");
            break;
        }
        attempted++;
        sr_h264_feed(decoder, mutated, size - 2048u);
        for (unsigned take = 0; take < 32u; take++) {
            uint64_t consumed = 0;
            int64_t pts = 0;
            int rc = sr_h264_au_take(decoder, 0, &consumed, &pts);
            if (rc <= 0) break;
        }
        {
            uint64_t consumed = 0;
            int64_t pts = 0;
            (void)sr_h264_au_take(decoder, 1, &consumed, &pts);
        }
        (void)sr_h264_frame(decoder, 1, GUEST_BUF, 64, 3);
        sr_h264_destroy(decoder);
    }
    free(mutated);
    free(bytes);
    printf("Legacy MPEG-PS/H.264 mutation: %u iterations, %u executed, 0 crashes\n",
           iterations, attempted);
}

/* A malformed audio track must leave the video track alone. */
static void test_track_independence(void) {
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    if (!bytes) { CHECK(0, "fixture allocated"); return; }
    /* Corrupt the audio payload bytes in place: the video elementary stream is untouched. */
    for (uint32_t i = 2048u; i + 6u < size; i++) {
        if (bytes[i] != 0 || bytes[i + 1] != 0 || bytes[i + 2] != 1 || bytes[i + 3] != 0xbd) continue;
        uint32_t len = ((uint32_t)bytes[i + 4] << 8) | bytes[i + 5];
        uint32_t payload = i + 9u + 4u;
        if (payload + 8u > size) break;
        memset(bytes + payload, 0xb7, 8u);      /* destroy the audio frame header */
        i += 9u + len;
    }
    MemSource mem;
    SrPsmfProducer *p = open_fixture(bytes, size, &mem, 1024u);
    CHECK(p != NULL, "producer opens a PSMF with a corrupt audio track");
    if (!p) { free(bytes); return; }
    int video = 0;
    for (int guard = 0; guard < 4096 && !sr_psmf_producer_eof(p); guard++) {
        sr_psmf_producer_pump(p, 2);
        SrPsmfAu au;
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) { video++; sr_psmf_au_release(&au); }
    }
    CHECK(video == FIX_PICTURES, "a corrupt audio track cannot cost the video track its pictures");
    SrPsmfProducerStats st;
    sr_psmf_producer_stats(p, &st);
    CHECK(st.audio_resync_bytes > 0, "the corrupt audio bytes are counted, not silently trusted");
    sr_psmf_producer_close(p);
    free(bytes);
}

static uint8_t *build_multistream_psmf(uint32_t *size_out,
                                       uint32_t au0_off[FIX_PICTURES], uint32_t au0_len[FIX_PICTURES],
                                       uint32_t au1_off[FIX_PICTURES], uint32_t au1_len[FIX_PICTURES]) {
    uint8_t es0[65536], es1[65536];
    uint32_t es0_len = 0, es1_len = 0;
    CHECK(build_stream_ex(es0, sizeof(es0), 4, 4, k_y, k_cb, k_cr, au0_off, au0_len, &es0_len), "stream 0 builds");
    static const uint8_t k_y2[FIX_PICTURES]  = {  80u, 160u, 240u };
    static const uint8_t k_cb2[FIX_PICTURES] = { 100u, 128u, 140u };
    static const uint8_t k_cr2[FIX_PICTURES] = { 150u, 128u, 110u };
    CHECK(build_stream_ex(es1, sizeof(es1), 2, 2, k_y2, k_cb2, k_cr2, au1_off, au1_len, &es1_len), "stream 1 builds");

    Buf b;
    b.cap = 2048u + (es0_len + es1_len) * 2u + 8192u;
    b.d = (uint8_t *)calloc(1, b.cap);
    b.at = 2048u;
    b.overflow = 0;
    if (!b.d) return NULL;
    b.d[0] = 'P'; b.d[1] = 'S'; b.d[2] = 'M'; b.d[3] = 'F';
    be32_at(b.d + 8, 2048u);
    /* Stream table at 0x80 */
    b.d[0x80] = 0; b.d[0x81] = 4; /* 4 stream entries */
    /* Entry 0: Video 0 (0xE0) */
    b.d[0x82] = 0xE0; b.d[0x83] = 0x00;
    be32_at(b.d + 0x86, 1); be32_at(b.d + 0x8A, 1);
    b.d[0x8E] = 4; b.d[0x8F] = 4; /* 64x64 */
    /* Entry 1: Video 1 (0xE1) */
    b.d[0x92] = 0xE1; b.d[0x93] = 0x01;
    be32_at(b.d + 0x96, 1); be32_at(b.d + 0x9A, 1);
    b.d[0x9E] = 2; b.d[0x9F] = 2; /* 32x32 */
    /* Entry 2: Audio 0 (0xB0, sub 0x00) */
    b.d[0xA2] = 0xB0; b.d[0xA3] = 0x00;
    b.d[0xB0] = 2; /* 2 channels */
    /* Entry 3: Audio 1 (0xB1, sub 0x01) */
    b.d[0xB2] = 0xB1; b.d[0xB3] = 0x01;
    b.d[0xC0] = 1; /* 1 channel */

    uint8_t aframe[128];
    for (int i = 0; i < FIX_PICTURES; i++) {
        /* Video 0 PES 1 */
        uint32_t half0 = au0_len[i] / 2u;
        add_video_pes_sid(&b, 0xE0, k_has_pts[i], FIX_BASE + (int64_t)i * FIX_PTS_STEP, es0 + au0_off[i], half0);
        /* Video 1 PES 1 */
        uint32_t half1 = au1_len[i] / 2u;
        int v1_has_pts = (i != 0);
        int64_t v1_pts = FIX_BASE + (int64_t)(i + 1) * 3000;
        add_video_pes_sid(&b, 0xE1, v1_has_pts, v1_pts, es1 + au1_off[i], half1);

        if (i == 0) {
            uint32_t n = make_audio_frame(aframe, sizeof(aframe), 0x28, 6, 0x11);
            add_audio_pes_sub(&b, 0x00, 1, FIX_BASE, aframe, n);
            n = make_audio_frame(aframe, sizeof(aframe), 0x28, 6, 0x33);
            add_audio_pes_sub(&b, 0x01, 0, 0, aframe, n);
        } else if (i == 1) {
            uint32_t n = make_audio_frame(aframe, sizeof(aframe), 0x28, 6, 0x22);
            add_audio_pes_sub(&b, 0x00, 0, 0, aframe, n);
            n = make_audio_frame(aframe, sizeof(aframe), 0x28, 6, 0x44);
            add_audio_pes_sub(&b, 0x01, 1, FIX_BASE + 5000, aframe, n);
        }

        /* Video 0 PES 2 */
        add_video_pes_sid(&b, 0xE0, 0, 0, es0 + au0_off[i] + half0, au0_len[i] - half0);
        /* Video 1 PES 2 */
        add_video_pes_sid(&b, 0xE1, 0, 0, es1 + au1_off[i] + half1, au1_len[i] - half1);
    }
    be32_at(b.d + 12, b.at - 2048u);
    CHECK(!b.overflow, "multistream synthetic PSMF container fits");
    *size_out = b.at;
    return b.d;
}

static void test_multistream_selection(void) {
    uint32_t au0_off[FIX_PICTURES], au0_len[FIX_PICTURES];
    uint32_t au1_off[FIX_PICTURES], au1_len[FIX_PICTURES];
    uint32_t size = 0;
    uint8_t *bytes = build_multistream_psmf(&size, au0_off, au0_len, au1_off, au1_len);
    CHECK(bytes != NULL, "multistream fixture allocated");
    if (!bytes) return;

    uint8_t es0[65536], es1[65536];
    uint32_t es0_len = 0, es1_len = 0;
    static const uint8_t k_y2[FIX_PICTURES]  = {  80u, 160u, 240u };
    static const uint8_t k_cb2[FIX_PICTURES] = { 100u, 128u, 140u };
    static const uint8_t k_cr2[FIX_PICTURES] = { 150u, 128u, 110u };
    build_stream_ex(es0, sizeof(es0), 4, 4, k_y, k_cb, k_cr, au0_off, au0_len, &es0_len);
    build_stream_ex(es1, sizeof(es1), 2, 2, k_y2, k_cb2, k_cr2, au1_off, au1_len, &es1_len);

    MemSource mem;
    SrPsmfProducer *p = open_fixture(bytes, size, &mem, 1024u);
    CHECK(p != NULL, "producer opens multistream PSMF");
    if (!p) { free(bytes); return; }

    CHECK(sr_psmf_producer_video_streams(p) == 2, "producer identifies 2 video streams");
    CHECK(sr_psmf_producer_audio_streams(p) == 2, "producer identifies 2 audio streams");

    /* Out-of-range selection checks */
    CHECK(!sr_psmf_producer_select_streams(p, 2, 0), "selecting video stream 2 refuses out-of-range");
    CHECK(!sr_psmf_producer_select_streams(p, 0, 2), "selecting audio stream 2 refuses out-of-range");
    CHECK(!sr_psmf_producer_select_streams(p, 5, 5), "selecting out-of-range streams refuses");

    /* Test Track 0: Video 0, Audio 0 */
    CHECK(sr_psmf_producer_select_streams(p, 0, 0), "select video 0, audio 0");
    CHECK(sr_psmf_producer_selected_video_stream(p) == 0, "selected video is 0");
    CHECK(sr_psmf_producer_selected_audio_stream(p) == 0, "selected audio is 0");

    int n_v0 = 0, n_a0 = 0;
    for (int guard = 0; guard < 4096 && !sr_psmf_producer_eof(p); guard++) {
        sr_psmf_producer_pump(p, 2);
        SrPsmfAu au;
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) {
            CHECK(n_v0 < FIX_PICTURES, "no extra video AUs for stream 0");
            if (n_v0 < FIX_PICTURES) {
                CHECK(au.stream_id == 0xE0, "video AU has stream ID 0xE0");
                CHECK(au.size == au0_len[n_v0], "video 0 AU size matches authored picture");
                if (au.size == au0_len[n_v0])
                    CHECK(memcmp(au.data, es0 + au0_off[n_v0], au.size) == 0, "video 0 AU bytes match stream 0 exactly");
                CHECK(au.has_pts == k_has_pts[n_v0], "video 0 PTS presence preserved");
                if (k_has_pts[n_v0])
                    CHECK(au.pts == (int64_t)n_v0 * FIX_PTS_STEP, "video 0 PTS timestamp normalized");
            }
            sr_psmf_au_release(&au);
            n_v0++;
        }
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_AUDIO, &au)) {
            CHECK(n_a0 < 2, "no extra audio frames for stream 0");
            if (n_a0 < 2) {
                CHECK(au.stream_id == 0x00, "audio AU has substream ID 0x00");
                uint8_t want_fill = (n_a0 == 0) ? 0x11 : 0x22;
                CHECK(au.data && au.size > 8 && au.data[8] == want_fill, "audio 0 frame has stream 0 payload");
                if (n_a0 == 0) {
                    CHECK(au.has_pts == 1, "audio 0 frame 0 has PTS");
                    CHECK(au.pts == 0, "audio 0 frame 0 timestamp normalized");
                } else {
                    CHECK(au.has_pts == 0, "audio 0 frame 1 has no PTS");
                }
            }
            sr_psmf_au_release(&au);
            n_a0++;
        }
    }
    CHECK(n_v0 == FIX_PICTURES, "got exactly 3 video AUs for stream 0");
    CHECK(n_a0 == 2, "got exactly 2 audio frames for stream 0");

    /* Test Track 1: Video 1, Audio 1 */
    CHECK(sr_psmf_producer_select_streams(p, 1, 1), "select video 1, audio 1");
    CHECK(sr_psmf_producer_selected_video_stream(p) == 1, "selected video is 1");
    CHECK(sr_psmf_producer_selected_audio_stream(p) == 1, "selected audio is 1");

    int n_v1 = 0, n_a1 = 0;
    for (int guard = 0; guard < 4096 && !sr_psmf_producer_eof(p); guard++) {
        sr_psmf_producer_pump(p, 2);
        SrPsmfAu au;
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) {
            CHECK(n_v1 < FIX_PICTURES, "no extra video AUs for stream 1");
            if (n_v1 < FIX_PICTURES) {
                CHECK(au.stream_id == 0xE1, "video AU has stream ID 0xE1");
                CHECK(au.size == au1_len[n_v1], "video 1 AU size matches authored picture");
                if (au.size == au1_len[n_v1])
                    CHECK(memcmp(au.data, es1 + au1_off[n_v1], au.size) == 0, "video 1 AU bytes match stream 1 exactly");
                int want_pts = (n_v1 != 0);
                CHECK(au.has_pts == want_pts, "video 1 PTS presence preserved");
                if (want_pts)
                    CHECK(au.pts == (int64_t)(n_v1 + 1) * 3000, "video 1 PTS timestamp normalized");
            }
            sr_psmf_au_release(&au);
            n_v1++;
        }
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_AUDIO, &au)) {
            CHECK(n_a1 < 2, "no extra audio frames for stream 1");
            if (n_a1 < 2) {
                CHECK(au.stream_id == 0x01, "audio AU has substream ID 0x01");
                uint8_t want_fill = (n_a1 == 0) ? 0x33 : 0x44;
                CHECK(au.data && au.size > 8 && au.data[8] == want_fill, "audio 1 frame has stream 1 payload");
                if (n_a1 == 0) {
                    CHECK(au.has_pts == 0, "audio 1 frame 0 has no PTS");
                } else {
                    CHECK(au.has_pts == 1, "audio 1 frame 1 has PTS");
                    CHECK(au.pts == 5000, "audio 1 frame 1 timestamp normalized");
                }
            }
            sr_psmf_au_release(&au);
            n_a1++;
        }
    }
    CHECK(n_v1 == FIX_PICTURES, "got exactly 3 video AUs for stream 1");
    CHECK(n_a1 == 2, "got exactly 2 audio frames for stream 1");

    /* Test Track with Video 0 and NO Audio */
    CHECK(sr_psmf_producer_select_streams(p, 0, SR_PSMF_STREAM_NONE), "select video 0, no audio");
    int n_v_noaudio = 0, n_a_noaudio = 0;
    for (int guard = 0; guard < 4096 && !sr_psmf_producer_eof(p); guard++) {
        sr_psmf_producer_pump(p, 2);
        SrPsmfAu au;
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_VIDEO, &au)) {
            sr_psmf_au_release(&au);
            n_v_noaudio++;
        }
        while (sr_psmf_producer_pop(p, SR_PSMF_AU_AUDIO, &au)) {
            sr_psmf_au_release(&au);
            n_a_noaudio++;
        }
    }
    CHECK(n_v_noaudio == FIX_PICTURES, "got exactly 3 video AUs when audio is disabled");
    CHECK(n_a_noaudio == 0, "got 0 audio frames when audio is disabled");

    sr_psmf_producer_close(p);
    free(bytes);
}

/* Exercise the production ringbuffer/get-AU seam with a deliberately invalid decoder handle.
 * The selftest build compiles the same SR_H264 integration blocks as SR_SDL3VK, so a failed
 * demux feed or AU take cannot accidentally become legacy synthetic timestamp success. */
static void test_mpeg_ps_demux_error_fails_closed(void) {
    enum {
        ERR_DESC = 0x08600000u,
        ERR_DATA = 0x08610000u,
        ERR_RING = 0x08620000u,
        ERR_RING_DATA = 0x08621000u,
        ERR_AU = 0x08630000u,
    };
    memset(SR_HOST(ERR_RING), 0, RB_BYTES);
    MEM_W32(ERR_RING + RB_packets, 2u);
    MEM_W32(ERR_RING + RB_packetsRead, 0u);
    MEM_W32(ERR_RING + RB_packetsWritePos, 0u);
    MEM_W32(ERR_RING + RB_packetsAvail, 0u);
    MEM_W32(ERR_RING + RB_packetSize, MPEG_PACKET_SIZE);
    MEM_W32(ERR_RING + RB_data, ERR_RING_DATA);
    MEM_W32(ERR_RING + RB_callback_addr, 0u);
    MEM_W32(ERR_RING + RB_callback_args, 0u);
    MEM_W32(ERR_RING + RB_dataUpperBound, ERR_RING_DATA + 2u * MPEG_PACKET_SIZE);
    MEM_W32(ERR_RING + RB_mpeg, 0u);
    MEM_W32(ERR_RING + RB_gp, 0u);
    memset(SR_HOST(ERR_RING_DATA), 0, 2u * MPEG_PACKET_SIZE);
    MEM_W32(ERR_DESC, 0u);
    CHECK(mpeg_create(ERR_DESC, ERR_DATA, 0x10000u, ERR_RING, 64u, 0u, 0u) == 0u,
          "demux error fixture creates an MPEG ring context");
    Mpeg *ctx = mpeg_find(ERR_DESC);
    CHECK(ctx != NULL, "demux error fixture finds its MPEG context");
    if (!ctx) return;
    ctx->h264Init = 1;
    ctx->h264 = 0x7fffffff; /* outside the decoder instance table: feed and take fail */
    uint32_t sid = mpeg_regist_stream(ERR_DESC, MPEG_AVC_STREAM, 0u);

    CHECK(mpeg_ringbuffer_put(NULL, ERR_RING, 1u, 1u) == 1u,
          "RingbufferPut still reports the guest packet it copied");
    CHECK(ctx->h264 >= 0 && rb_get(ERR_RING, RB_packetsAvail) == 1u,
          "the test reaches GetAvcAu after the internal H.264 feed refusal");
    CHECK(ctx->h264DemuxFailed,
          "RingbufferPut retains a failed H.264 demux feed for the next AU request");
    memset(SR_HOST(ERR_AU), 0xa5, 24u);
    uint32_t result = mpeg_get_avc_au(ERR_DESC, sid, ERR_AU, 0u);
    CHECK(result == SCE_MPEG_ERROR_NO_DATA,
          "a failed H.264 feed is returned as no data, never synthetic AU success");
    CHECK(rb_get(ERR_RING, RB_packetsAvail) == 1u,
          "a failed H.264 feed does not consume packets through the synthetic fallback");

    /* Also exercise a negative AU-take result without the feed-failure latch. */
    ctx->h264DemuxFailed = 0;
    memset(SR_HOST(ERR_AU), 0xa5, 24u);
    result = mpeg_get_avc_au(ERR_DESC, sid, ERR_AU, 0u);
    CHECK(result == SCE_MPEG_ERROR_NO_DATA && ctx->h264DemuxFailed,
          "a negative H.264 AU take is terminal, never synthetic AU success");
    CHECK(rb_get(ERR_RING, RB_packetsAvail) == 1u,
          "a negative H.264 AU take does not consume ring packets");
    CHECK(MEM_R32(ERR_AU) == UINT32_MAX && MEM_R32(ERR_AU + 4u) == UINT32_MAX,
          "a rejected AU reports unknown timestamps");
    CHECK(mpeg_delete(ERR_DESC) == 0u, "demux error fixture deletes its MPEG context");

    /* Run malformed raw PS through RingbufferPut, the real H.264 bridge, and GetAvcAu. The
     * unsupported start code fails in the producer before a decoder AU can be queued. */
    memset(SR_HOST(ERR_RING), 0, RB_BYTES);
    MEM_W32(ERR_RING + RB_packets, 2u);
    MEM_W32(ERR_RING + RB_packetsRead, 0u);
    MEM_W32(ERR_RING + RB_packetsWritePos, 0u);
    MEM_W32(ERR_RING + RB_packetsAvail, 0u);
    MEM_W32(ERR_RING + RB_packetSize, MPEG_PACKET_SIZE);
    MEM_W32(ERR_RING + RB_data, ERR_RING_DATA);
    MEM_W32(ERR_RING + RB_callback_addr, 0u);
    MEM_W32(ERR_RING + RB_callback_args, 0u);
    MEM_W32(ERR_RING + RB_dataUpperBound, ERR_RING_DATA + 2u * MPEG_PACKET_SIZE);
    MEM_W32(ERR_RING + RB_mpeg, 0u);
    MEM_W32(ERR_RING + RB_gp, 0u);
    memset(SR_HOST(ERR_RING_DATA), 0, 2u * MPEG_PACKET_SIZE);
    static const uint8_t malformed_ps[] = {0x00u, 0x00u, 0x01u, 0x01u};
    memcpy(SR_HOST(ERR_RING_DATA), malformed_ps, sizeof(malformed_ps));
    MEM_W32(ERR_DESC, 0u);
    CHECK(mpeg_create(ERR_DESC, ERR_DATA, 0x10000u, ERR_RING, 64u, 0u, 0u) == 0u,
          "malformed-PS fixture creates an MPEG ring context");
    ctx = mpeg_find(ERR_DESC);
    CHECK(ctx != NULL, "malformed-PS fixture finds its MPEG context");
    if (!ctx) return;
    sid = mpeg_regist_stream(ERR_DESC, MPEG_AVC_STREAM, 0u);
    CHECK(memcmp(SR_HOST(ERR_RING_DATA), malformed_ps, sizeof(malformed_ps)) == 0,
          "malformed PS start code is present in the ring packet");
    CHECK(mpeg_ringbuffer_put(NULL, ERR_RING, 1u, 1u) == 1u,
          "RingbufferPut submits the malformed synthetic PS packet");
    if (ctx->h264 < 0) {
        fprintf(stderr, "SKIP: malformed-PS MPEG integration needs a real H.264 backend\n");
    } else {
        CHECK(ctx->h264DemuxFailed,
              "the production H.264 bridge latches the malformed PS parser failure");
        uint32_t availAfterFeed = rb_get(ERR_RING, RB_packetsAvail);
        uint32_t readAfterFeed = rb_get(ERR_RING, RB_packetsRead);
        uint32_t writePosAfterFeed = rb_get(ERR_RING, RB_packetsWritePos);
        uint32_t fedAfterFeed = ctx->fedPackets;
        memset(SR_HOST(ERR_AU), 0xa5, 24u);
        result = mpeg_get_avc_au(ERR_DESC, sid, ERR_AU, 0u);
        CHECK(result == SCE_MPEG_ERROR_NO_DATA,
              "malformed PS maps to the existing no-data result, not synthetic AU success");
        CHECK(MEM_R32(ERR_AU) == UINT32_MAX && MEM_R32(ERR_AU + 4u) == UINT32_MAX &&
                  MEM_R32(ERR_AU + 8u) == UINT32_MAX && MEM_R32(ERR_AU + 12u) == UINT32_MAX,
              "malformed PS leaves both AU timestamps unknown");
        CHECK(rb_get(ERR_RING, RB_packetsAvail) == availAfterFeed &&
                  rb_get(ERR_RING, RB_packetsRead) == readAfterFeed &&
                  rb_get(ERR_RING, RB_packetsWritePos) == writePosAfterFeed &&
                  ctx->fedPackets == fedAfterFeed && ctx->auPacketsDone == 0u,
              "failed AU retrieval leaves the fed ring packet state unchanged");
    }
    if (ctx->h264 >= 0) {
        sr_h264_destroy(ctx->h264);
        ctx->h264 = -1;
    }
    CHECK(mpeg_delete(ERR_DESC) == 0u, "malformed-PS fixture deletes its MPEG context");
}

static void test_psmf_contract_fragmentation_and_malformed_rejection(void) {
    uint32_t size = 0;
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES];
    uint8_t *bytes = build_psmf(&size, au_off, au_len);
    CHECK(bytes != NULL && size > 2048u, "PSMF contract fixture is available");
    if (bytes && size > 2048u) {
        CHECK(sr_hle_test_psmf_stream_contract(bytes + 2048u, size - 2048u, 1u,
                                               NULL, FIX_PICTURES),
              "a valid PSMF stream split byte-by-byte reaches its video AUs through the player demux");
    }
    free(bytes);

    static const uint8_t malformed_ps[] = {0x00u, 0x00u, 0x01u, 0x01u};
    CHECK(sr_hle_test_psmf_stream_contract(malformed_ps, sizeof(malformed_ps), 1u,
                                           "unknown-start-code", 0u),
          "malformed PSMF input yields a named PSMF_CONTRACT refusal and no AU");
}

/* ---- the measured mode-1 YCbCr buffer (#302, PSP-MPEG-001) ---------------------------------
 * A reference model written from the measured layout and colour conversion, independently of
 * mpeg.c.  It reads the planes through the header's own pointers, so it follows any header. */
#define PSP_MPEG_INVALID 0x806101FEu   /* MEASURED SCE_MPEG_ERROR_INVALID_VALUE */
#define PSP_CSC_REFUSED  0x800001FEu   /* MEASURED sceMpegAvcCsc refusal */
#define NID_QUERY_YCBCR  0x211a057cu
#define NID_INIT_YCBCR   0x67179b1bu
#define NID_DECODE_YCBCR 0xf0eb1125u
#define NID_STOP_YCBCR   0xf2930c9cu
#define NID_COPY_YCBCR   0x0558b075u
#define NID_CSC          0x31bd0272u
#define NID_DECODE_MODE  0xa11c7026u

static uint32_t ref_ycbcr_luma(uint32_t buf, uint32_t x, uint32_t y) {
    uint32_t h = MEM_R32(buf) * 16u, s = x >> 4, p = (s & 1u) + 2u * (y & 1u);
    return MEM_R32(buf + 16u + 4u * p) + (s >> 1) * 16u * (h / 2u) + (y >> 1) * 16u + (x & 15u);
}
static uint32_t ref_ycbcr_chroma(uint32_t buf, uint32_t cx, uint32_t cy) {
    uint32_t h = MEM_R32(buf) * 16u, s = cx >> 3, p = 4u + (s & 1u) + 2u * (cy & 1u);
    return MEM_R32(buf + 16u + 4u * p) + (s >> 1) * 16u * (h / 4u) + (cy >> 1) * 16u + (cx & 7u) * 2u;
}
static uint8_t ref_clamp(int v) { return v < 0 ? 0 : v > 255 ? 255 : (uint8_t)v; }
/* The measured RGBA8888 conversion of one sample triple: R, G, B, alpha 0. */
static void ref_psp_rgba(int luma, int cb, int cr, uint8_t px[4]) {
    int l = 149 * ((luma < 16 ? 16 : luma) - 16);
    px[0] = ref_clamp((l + 204 * (cr - 128) + 64) >> 7);
    px[1] = ref_clamp((l - 50 * (cb - 128) - 104 * (cr - 128) + 64) >> 7);
    px[2] = ref_clamp((l + 258 * (cb - 128) + 64) >> 7);
    px[3] = 0u;
}
static void ref_ycbcr_rgba(uint32_t buf, uint32_t x, uint32_t y, uint8_t px[4]) {
    uint32_t c = ref_ycbcr_chroma(buf, x >> 1, y >> 1);
    ref_psp_rgba(MEM_R8(ref_ycbcr_luma(buf, x, y)), MEM_R8(c), MEM_R8(c + 1u), px);
}
/* Give an initialized buffer a decoded width x height picture whose samples vary with position;
 * flat != 0 writes every luma sample as luma and every chroma pair as (cb, cr) instead. */
static void ref_ycbcr_fill(uint32_t buf, uint32_t width, uint32_t height, int flat,
                           uint8_t luma, uint8_t cb, uint8_t cr) {
    MEM_W32(buf, height / 16u);
    MEM_W32(buf + 4u, width / 16u);
    for (uint32_t y = 0; y < height; y++)
        for (uint32_t x = 0; x < width; x++)
            MEM_W8(ref_ycbcr_luma(buf, x, y), flat ? luma : (uint8_t)(x * 7u + y * 13u));
    for (uint32_t cy = 0; cy < height / 2u; cy++)
        for (uint32_t cx = 0; cx < width / 2u; cx++) {
            uint32_t c = ref_ycbcr_chroma(buf, cx, cy);
            MEM_W8(c, flat ? cb : (uint8_t)(cx * 11u + cy * 5u + 40u));
            MEM_W8(c + 1u, flat ? cr : (uint8_t)(cx * 3u + cy * 17u + 90u));
        }
}
/* The RGBA8888 destination (stride frame_width) holds, from its first pixel, the source columns
 * x .. x + w - 1 of rows 0 .. h - 1. */
static int ref_csc_matches(uint32_t buf, uint32_t dest, uint32_t frame_width, uint32_t x,
                           uint32_t w, uint32_t h) {
    for (uint32_t r = 0; r < h; r++)
        for (uint32_t c = 0; c < w; c++) {
            uint8_t px[4];
            ref_ycbcr_rgba(buf, x + c, r, px);
            if (memcmp(SR_HOST(dest + (r * frame_width + c) * 4u), px, 4u) != 0) return 0;
        }
    return 1;
}
static void set_range(uint32_t addr, int32_t x, int32_t y, int32_t w, int32_t h) {
    MEM_W32(addr, (uint32_t)x);
    MEM_W32(addr + 4u, (uint32_t)y);
    MEM_W32(addr + 8u, (uint32_t)w);
    MEM_W32(addr + 12u, (uint32_t)h);
}

/* The measured sceMpegAvcQueryYCbCrSize / InitYCbCr / Csc / DecodeStopYCbCr / CopyYCbCr
 * contract on hand-built pictures, through the production HLE dispatch.  It needs no H.264
 * backend, so it runs on every host. */
static void test_mpeg_ycbcr_measured_contract(void) {
    enum {
        YM_DESC = 0x08200000u, YM_DATA = 0x08210000u, YM_SIZE = 0x08220000u, YM_RANGE = 0x08220100u,
        YM_PTR = 0x08220200u, YM_INIT = 0x08220300u, YM_AU = 0x08220400u, YM_MODE = 0x08220500u,
        YM_FULL = 0x08230000u,                       /* 480x272: 195968 bytes */
        YM_SMALL = 0x08260000u, YM_COPY = 0x08262000u, /* 64x32: 3200 bytes each */
        YM_DEST = 0x08270000u,                       /* 64x32 RGBA8888 */
    };
    const uint32_t full_size = 195968u, small_size = 3200u, dest_bytes = 64u * 32u * 4u;
    MEM_W32(YM_DESC, 0u);
    CHECK(mpeg_create(YM_DESC, YM_DATA, 0x10000u, 0, 64u, 0, 0) == 0, "ycbcr: a decoder-less context");
    Mpeg *ctx = mpeg_find(YM_DESC);
    CHECK(ctx != NULL, "ycbcr: the context is found");
    if (!ctx) return;
    ctx->streamWidth = 480u;   /* the measured stream: 480x224 */
    ctx->streamHeight = 224u;

    static const struct { uint32_t mode, w, h, rc, size; } q[] = {
        { 1u, 480u, 272u, 0u, 195968u }, { 1u, 16u, 16u, 0u, 512u },
        { 1u, 480u, 288u, PSP_MPEG_INVALID, 0u }, { 1u, 496u, 272u, PSP_MPEG_INVALID, 0u },
        { 1u, 15u, 16u, PSP_MPEG_INVALID, 0u }, { 1u, 16u, 15u, PSP_MPEG_INVALID, 0u },
        { 1u, 0u, 0u, PSP_MPEG_INVALID, 0u }, { 0u, 480u, 272u, PSP_MPEG_INVALID, 0u },
        { 4u, 480u, 272u, PSP_MPEG_INVALID, 0u }, { UINT32_MAX, 480u, 272u, PSP_MPEG_INVALID, 0u },
        { 2u, 480u, 272u, 0u, 128u }, { 2u, 720u, 480u, 0u, 128u }, { 2u, 0u, 0u, 0u, 128u },
        { 3u, 480u, 272u, 0u, 195840u }, { 3u, 480u, 288u, 0u, 207360u }, { 3u, 15u, 16u, 0u, 360u },
        { 3u, 0u, 0u, 0u, 0u },
    };
    int query_ok = 1;
    for (size_t i = 0; i < sizeof(q) / sizeof(q[0]); i++) {
        MEM_W32(YM_SIZE, 0xffffffffu);
        uint32_t rc = guest_mpeg_import(NID_QUERY_YCBCR, YM_DESC, q[i].mode, q[i].w, q[i].h, YM_SIZE);
        if (rc != q[i].rc || MEM_R32(YM_SIZE) != q[i].size) {
            fprintf(stderr, "  QueryYCbCrSize mode %d %ux%u: 0x%08x size %u\n", (int)q[i].mode,
                    (unsigned)q[i].w, (unsigned)q[i].h, (unsigned)rc, (unsigned)MEM_R32(YM_SIZE));
            query_ok = 0;
        }
    }
    CHECK(query_ok, "ycbcr: QueryYCbCrSize gives the measured size, or the measured refusal and a size "
                    "of 0, for every mode and size (the stream's own 480x224 is not checked)");
    MEM_W32(YM_SIZE, 0xffffffffu);
    CHECK(guest_mpeg_import(NID_QUERY_YCBCR, YM_DESC, 3u, 512u, 272u, YM_SIZE) == PSP_MPEG_INVALID &&
              MEM_R32(YM_SIZE) == 0u,
          "ycbcr: a mode-3 size wider than 480 (not 1.5 w h on the PSP) is refused as not modeled");

    memset(SR_HOST(YM_FULL), 0xa5, full_size);
    CHECK(guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 1u, 480u, 272u, YM_FULL) == 0u,
          "ycbcr: InitYCbCr mode 1 480x272 initializes on the 480x224 stream");
    static const uint32_t k_plane_off[8] = { 0x80u, 0x17F00u, 0x8000u, 0x1FE80u,
                                             0xFF80u, 0x27E00u, 0x13F40u, 0x2BDC0u };
    int header = guest_bytes_are(YM_FULL, 16u, 0u) && guest_bytes_are(YM_FULL + 48u, 80u, 0u);
    for (uint32_t i = 0; i < 8u; i++)
        if (MEM_R32(YM_FULL + 16u + 4u * i) != YM_FULL + k_plane_off[i]) header = 0;
    CHECK(header, "ycbcr: InitYCbCr writes the measured header: words 0-3 zero, the eight plane "
                  "pointers, the rest zero");
    CHECK(guest_bytes_are(YM_FULL + 128u, full_size - 128u, 0xa5u),
          "ycbcr: InitYCbCr leaves every plane byte as it was");
    CHECK(guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 2u, 480u, 272u, YM_FULL) == PSP_MPEG_INVALID &&
              guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 3u, 480u, 272u, YM_FULL) == PSP_MPEG_INVALID &&
              guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 1u, 480u, 288u, YM_FULL) == PSP_MPEG_INVALID &&
              guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 1u, 16u, 16u, YM_FULL) == PSP_MPEG_INVALID &&
              guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 1u, 480u, 272u, YM_FULL + 4u) == PSP_MPEG_INVALID,
          "ycbcr: InitYCbCr refuses modes 2 and 3 and an odd strip count (not measured), a size past "
          "the mode-1 limits and an unaligned buffer");
    CHECK(MEM_R32(YM_FULL + 16u) == YM_FULL + 0x80u, "ycbcr: a refused InitYCbCr writes nothing");

    MEM_W32(YM_MODE, 0u);
    MEM_W32(YM_MODE + 4u, 3u);
    CHECK(guest_mpeg_import(NID_DECODE_MODE, YM_DESC, YM_MODE, 0u, 0u, 0u) == 0u,
          "ycbcr: RGBA8888 output is selected");
    set_range(YM_RANGE, 0, 0, 480, 224);
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_FULL, YM_RANGE, 512u, YM_DEST) == PSP_CSC_REFUSED,
          "ycbcr: CSC of a buffer with no decoded picture (words 0 and 1 zero) is refused");
    memset(SR_HOST(YM_FULL), 0, 128u);
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_FULL, YM_RANGE, 512u, YM_DEST) == PSP_CSC_REFUSED,
          "ycbcr: CSC of a zeroed header is refused with the measured code");

    /* A hand-built 64x32 picture in an initialized buffer. */
    memset(SR_HOST(YM_SMALL), 0xa5, small_size);
    CHECK(guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 1u, 64u, 32u, YM_SMALL) == 0u,
          "ycbcr: a 64x32 buffer initializes");
    ref_ycbcr_fill(YM_SMALL, 64u, 32u, 1, 0x80u, 0x80u, 0x80u);
    static const uint8_t k_gray[4] = { 130u, 130u, 130u, 0u };
    set_range(YM_RANGE, 0, 0, 64, 32);
    memset(SR_HOST(YM_DEST), 0x5a, dest_bytes);
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_SMALL, YM_RANGE, 64u, YM_DEST) == 0u &&
              guest_rgba_matches(YM_DEST, 64u, 32u, k_gray),
          "ycbcr: planes of 0x80 convert to 130/130/130 with alpha 0, as measured");
    ref_ycbcr_fill(YM_SMALL, 64u, 32u, 1, 5u, 128u, 200u);
    static const uint8_t k_floor[4] = { 115u, 0u, 0u, 0u };   /* 8-bit 298/409 form: R 102 */
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_SMALL, YM_RANGE, 64u, YM_DEST) == 0u &&
              guest_rgba_matches(YM_DEST, 64u, 32u, k_floor),
          "ycbcr: luma below 16 converts as 16 (the measured floor), in 7-bit fixed point");
    ref_ycbcr_fill(YM_SMALL, 64u, 32u, 0, 0u, 0u, 0u);
    memset(SR_HOST(YM_DEST), 0x5a, dest_bytes);
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_SMALL, YM_RANGE, 64u, YM_DEST) == 0u &&
              ref_csc_matches(YM_SMALL, YM_DEST, 64u, 0u, 64u, 32u),
          "ycbcr: CSC converts every pixel of a varied picture from the guest planes, nearest chroma");

    set_range(YM_RANGE, 16, 16, 32, 16);
    memset(SR_HOST(YM_DEST), 0x5a, dest_bytes);
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_SMALL, YM_RANGE, 64u, YM_DEST) == 0u &&
              ref_csc_matches(YM_SMALL, YM_DEST, 64u, 16u, 32u, 16u) &&
              MEM_R8(YM_DEST + 32u * 4u) == 0x5au && MEM_R8(YM_DEST + 16u * 64u * 4u) == 0x5au,
          "ycbcr: a sub-range writes from the destination's first pixel, source columns from x and "
          "rows from the top, as measured for {16, 16, 64, 64}");

    static uint8_t before[64u * 32u * 4u];
    set_range(YM_RANGE, 0, 0, 64, 32);
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_SMALL, YM_RANGE, 64u, YM_DEST) == 0u,
          "ycbcr: the picture converts before its plane pointers are exchanged");
    memcpy(before, SR_HOST(YM_DEST), sizeof(before));
    const uint32_t p0 = MEM_R32(YM_SMALL + 16u), p2 = MEM_R32(YM_SMALL + 24u);
    MEM_W32(YM_SMALL + 16u, p2);
    MEM_W32(YM_SMALL + 24u, p0);
    CHECK(guest_mpeg_import(NID_CSC, YM_DESC, YM_SMALL, YM_RANGE, 64u, YM_DEST) == 0u &&
              ref_csc_matches(YM_SMALL, YM_DEST, 64u, 0u, 64u, 32u) &&
              memcmp(before, SR_HOST(YM_DEST), sizeof(before)) != 0,
          "ycbcr: CSC reads the planes through the header: exchanging P0 and P2 exchanges what it reads");
    MEM_W32(YM_SMALL + 16u, p0);
    MEM_W32(YM_SMALL + 24u, p2);

    static const struct { int32_t x, y, w, h; uint32_t fw, rc; } k_ranges[] = {
        { 1, 0, 32, 16, 64u, PSP_MPEG_INVALID }, { 0, 0, 63, 16, 64u, PSP_MPEG_INVALID },
        { 0, 0, 66, 16, 64u, PSP_CSC_REFUSED }, { 0, 0, 64, 34, 64u, PSP_CSC_REFUSED },
        { -16, 0, 32, 16, 64u, PSP_CSC_REFUSED }, { 0, 0, 64, 32, 32u, PSP_CSC_REFUSED },
        { 0, 0, 0, 0, 64u, 0u },
    };
    memset(SR_HOST(YM_DEST), 0x5a, dest_bytes);
    int ranges_ok = 1;
    for (size_t i = 0; i < sizeof(k_ranges) / sizeof(k_ranges[0]); i++) {
        set_range(YM_RANGE, k_ranges[i].x, k_ranges[i].y, k_ranges[i].w, k_ranges[i].h);
        uint32_t rc = guest_mpeg_import(NID_CSC, YM_DESC, YM_SMALL, YM_RANGE, k_ranges[i].fw, YM_DEST);
        if (rc != k_ranges[i].rc) {
            fprintf(stderr, "  CSC range %d,%d %dx%d fw %u: 0x%08x\n", (int)k_ranges[i].x, (int)k_ranges[i].y,
                    (int)k_ranges[i].w, (int)k_ranges[i].h, (unsigned)k_ranges[i].fw, (unsigned)rc);
            ranges_ok = 0;
        }
    }
    CHECK(ranges_ok && guest_bytes_are(YM_DEST, dest_bytes, 0x5au),
          "ycbcr: an odd x or w, a range past the picture, a negative origin and a narrower "
          "destination get the measured refusals, an empty range succeeds, and none writes");

    MEM_W32(YM_PTR, YM_SMALL);
    MEM_W32(YM_INIT, 0xdeadbeefu);
    memset(SR_HOST(YM_AU), 0, 24u);
    CHECK(guest_mpeg_import(NID_DECODE_YCBCR, YM_DESC, YM_AU, YM_PTR, YM_INIT, 0u) == SCE_MPEG_ERROR_NO_DATA &&
              MEM_R32(YM_INIT) == 0u,
          "ycbcr: without a decoder DecodeYCbCr reports no picture and clears init");
    static uint8_t snapshot[3200u];
    memcpy(snapshot, SR_HOST(YM_SMALL), sizeof(snapshot));
    MEM_W32(YM_INIT, 0xdeadbeefu);
    CHECK(guest_mpeg_import(NID_STOP_YCBCR, YM_DESC, YM_PTR, YM_INIT, 0u, 0u) == 0u && MEM_R32(YM_INIT) == 0u &&
              memcmp(snapshot, SR_HOST(YM_SMALL), sizeof(snapshot)) == 0,
          "ycbcr: DecodeStopYCbCr takes the address of the buffer pointer, reports status 0 and writes nothing");
    CHECK(guest_mpeg_import(NID_STOP_YCBCR, YM_DESC, YM_SMALL, YM_INIT, 0u, 0u) != 0u,
          "ycbcr: DecodeStopYCbCr given the buffer itself takes word 0 (2) as the buffer and refuses it");

    memset(SR_HOST(YM_COPY), 0xa5, small_size);
    CHECK(guest_mpeg_import(NID_INIT_YCBCR, YM_DESC, 1u, 64u, 32u, YM_COPY) == 0u &&
              guest_mpeg_import(NID_COPY_YCBCR, YM_DESC, YM_COPY, YM_SMALL, 0u, 0u) == 0u &&
              MEM_R32(YM_COPY) == 2u && MEM_R32(YM_COPY + 4u) == 4u,
          "ycbcr: CopyYCbCr copies a decoded picture and its words 0 and 1");
    int copied = 1;
    for (uint32_t y = 0; y < 32u; y++)
        for (uint32_t x = 0; x < 64u; x++)
            if (MEM_R8(ref_ycbcr_luma(YM_COPY, x, y)) != MEM_R8(ref_ycbcr_luma(YM_SMALL, x, y))) copied = 0;
    for (uint32_t cy = 0; cy < 16u; cy++)
        for (uint32_t cx = 0; cx < 32u; cx++)
            if (MEM_R16(ref_ycbcr_chroma(YM_COPY, cx, cy)) != MEM_R16(ref_ycbcr_chroma(YM_SMALL, cx, cy)))
                copied = 0;
    CHECK(copied, "ycbcr: every sample lands in the copy's own planes");
    CHECK(guest_mpeg_import(NID_COPY_YCBCR, YM_DESC, YM_COPY, YM_FULL, 0u, 0u) == SCE_MPEG_ERROR_INVALID_VALUE,
          "ycbcr: CopyYCbCr refuses a source with no decoded picture");
    mpeg_finish();
    CHECK(ycbcr_find(YM_DESC, YM_SMALL) == NULL, "ycbcr: teardown frees the host YCbCr slots");
}

/* sceMpegAvcDecodeYCbCr through the production dispatch writes the decoder's own samples into
 * the measured strip layout (the textured I_PCM fixture, checked against a second decode of the
 * same units through the host YUV target), and sceMpegAvcCsc converts them. */
static void test_mpeg_ycbcr_guest_decode(void) {
    enum {
        TD_DESC = 0x08100000u, TD_DATA = 0x08110000u, TD_YCBCR = 0x08130000u, TD_COPY = 0x08134000u,
        TD_RANGE = 0x08140000u, TD_DEST = 0x08150000u, TD_PTR = 0x08160000u, TD_INIT = 0x08170000u,
        TD_AU = 0x08180000u, TD_MODE = 0x08190000u, TD_SMALL = 0x081a0000u,
    };
    const uint32_t width = 64u, height = 64u, alloc_h = 96u;
    const uint32_t alloc = width * alloc_h * 3u / 2u + 128u;
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES], es_len = 0;
    static uint8_t es[65536];
    s_fixture_textured = 1;
    int built = build_stream(es, sizeof(es), au_off, au_len, &es_len);
    s_fixture_textured = 0;
    CHECK(built, "ycbcr-decode: the textured I_PCM stream builds");
    if (!built) return;

    MEM_W32(TD_DESC, 0u);
    CHECK(mpeg_create(TD_DESC, TD_DATA, 0x10000u, 0, 64u, 0, 0) == 0, "ycbcr-decode: a context");
    Mpeg *ctx = mpeg_find(TD_DESC);
    if (!ctx) return;
    ctx->streamWidth = width;
    ctx->streamHeight = height;
    ctx->h264 = sr_h264_create();
    ctx->h264Init = 1;
    ctx->totalPackets = 1u;
    ctx->fedPackets = 1u;
    int ref = sr_h264_create();
    if (ctx->h264 < 0 || ref < 0) {
        fprintf(stderr, "SKIP: the YCbCr decode layout needs a real H.264 backend\n");
        if (ref >= 0) sr_h264_destroy(ref);
        mpeg_finish();
        return;
    }
    for (int i = 0; i < FIX_PICTURES; i++)
        CHECK(sr_h264_submit_au(ctx->h264, es + au_off[i], au_len[i]) == 0 &&
                  sr_h264_submit_au(ref, es + au_off[i], au_len[i]) == 0,
              "ycbcr-decode: each access unit reaches both decoders");
    static uint8_t ry[64u * 64u], rcb[32u * 32u], rcr[32u * 32u];
    SrH264FrameTarget target;
    SrH264FrameInfo info;
    memset(&target, 0, sizeof(target));
    target.kind = SR_H264_TARGET_HOST_YUV;
    target.host_buffer = ry;
    target.host_width = 64;
    target.host_height = 64;
    target.host_stride = 64;
    target.host_cb = rcb;
    target.host_cr = rcr;
    target.host_c_stride = 32;
    CHECK(sr_h264_frame_ex(ref, 1, &target, &info) > 0 && info.width == 64 && info.height == 64,
          "ycbcr-decode: the host YUV target delivers the decoded 64x64 samples");
    int varied = 0;
    for (uint32_t i = 1; i < sizeof(ry); i++) if (ry[i] != ry[0]) varied = 1;
    CHECK(varied, "ycbcr-decode: the textured picture's samples differ with position");

    memset(SR_HOST(TD_YCBCR), 0xa5, alloc);
    CHECK(guest_mpeg_import(NID_INIT_YCBCR, TD_DESC, 1u, width, alloc_h, TD_YCBCR) == 0u,
          "ycbcr-decode: a 64x96 buffer initializes");
    MEM_W32(TD_MODE, 0u);
    MEM_W32(TD_MODE + 4u, 3u);
    CHECK(guest_mpeg_import(NID_DECODE_MODE, TD_DESC, TD_MODE, 0u, 0u, 0u) == 0u,
          "ycbcr-decode: RGBA8888 output is selected");
    MEM_W32(TD_PTR, TD_YCBCR);
    MEM_W32(TD_INIT, 0xdeadbeefu);
    memset(SR_HOST(TD_AU), 0, 24u);
    CHECK(guest_mpeg_import(NID_DECODE_YCBCR, TD_DESC, TD_AU, TD_PTR, TD_INIT, 0u) == 0u &&
              MEM_R32(TD_INIT) == 1u,
          "ycbcr-decode: DecodeYCbCr decodes a picture and sets init");
    CHECK(MEM_R32(TD_YCBCR) == 4u && MEM_R32(TD_YCBCR + 4u) == 4u,
          "ycbcr-decode: words 0 and 1 are the decoded height and width in 16-pixel units");
    int exact = 1;
    for (uint32_t y = 0; y < height; y++)
        for (uint32_t x = 0; x < width; x++)
            if (MEM_R8(ref_ycbcr_luma(TD_YCBCR, x, y)) != ry[y * 64u + x]) exact = 0;
    for (uint32_t cy = 0; cy < height / 2u; cy++)
        for (uint32_t cx = 0; cx < width / 2u; cx++) {
            uint32_t c = ref_ycbcr_chroma(TD_YCBCR, cx, cy);
            if (MEM_R8(c) != rcb[cy * 32u + cx] || MEM_R8(c + 1u) != rcr[cy * 32u + cx]) exact = 0;
        }
    CHECK(exact, "ycbcr-decode: every decoded sample sits where the measured strip layout puts it");
    /* 64 wide is two strips per parity: a 64-line picture fills 1024 of a luma plane's 1536 bytes
     * and 512 of a chroma plane's 768. */
    CHECK(guest_bytes_are(MEM_R32(TD_YCBCR + 16u) + 1024u, 512u, 0xa5u) &&
              guest_bytes_are(MEM_R32(TD_YCBCR + 32u) + 512u, 256u, 0xa5u),
          "ycbcr-decode: a decode writes only the picture's share of each plane");

    set_range(TD_RANGE, 0, 0, (int32_t)width, (int32_t)height);
    memset(SR_HOST(TD_DEST), 0x5a, width * height * 4u);
    CHECK(guest_mpeg_import(NID_CSC, TD_DESC, TD_YCBCR, TD_RANGE, width, TD_DEST) == 0u &&
              ref_csc_matches(TD_YCBCR, TD_DEST, width, 0u, width, height),
          "ycbcr-decode: CSC writes the measured conversion of the decoded samples");
    memset(SR_HOST(TD_COPY), 0xa5, alloc);
    memset(SR_HOST(TD_DEST), 0x5a, width * height * 4u);
    CHECK(guest_mpeg_import(NID_INIT_YCBCR, TD_DESC, 1u, width, alloc_h, TD_COPY) == 0u &&
              guest_mpeg_import(NID_COPY_YCBCR, TD_DESC, TD_COPY, TD_YCBCR, 0u, 0u) == 0u &&
              guest_mpeg_import(NID_CSC, TD_DESC, TD_COPY, TD_RANGE, width, TD_DEST) == 0u &&
              ref_csc_matches(TD_YCBCR, TD_DEST, width, 0u, width, height),
          "ycbcr-decode: a copy converts to the same picture");

    /* A picture larger than the InitYCbCr allocation is refused (not measured) and nothing is
     * written. */
    memset(SR_HOST(TD_SMALL), 0xa5, 3200u);
    CHECK(guest_mpeg_import(NID_INIT_YCBCR, TD_DESC, 1u, width, 32u, TD_SMALL) == 0u,
          "ycbcr-decode: a 64x32 buffer initializes");
    static uint8_t small_before[3200u];
    memcpy(small_before, SR_HOST(TD_SMALL), sizeof(small_before));
    MEM_W32(TD_PTR, TD_SMALL);
    MEM_W32(TD_INIT, 0xdeadbeefu);
    CHECK(guest_mpeg_import(NID_DECODE_YCBCR, TD_DESC, TD_AU, TD_PTR, TD_INIT, 0u) == SCE_MPEG_ERROR_INVALID_VALUE &&
              MEM_R32(TD_INIT) == 0u && memcmp(small_before, SR_HOST(TD_SMALL), sizeof(small_before)) == 0,
          "ycbcr-decode: a 64x64 picture is not written into a 64x32 allocation");
    sr_h264_destroy(ref);
    mpeg_finish();
}

/* The PCM access-unit and AU-mode boundaries of sceMpeg. */
static void test_mpeg_pcm_and_au_mode(void) {
    enum { PM_DESC = 0x08100000u, PM_DATA = 0x08110000u, PM_SIZE = 0x08120000u };
    MEM_W32(PM_DESC, 0u);
    CHECK(mpeg_create(PM_DESC, PM_DATA, 0x10000u, 0, 64u, 0, 0) == 0, "MPEG PCM fixture creates a context");
    CHECK(mpeg_query_pcm_es_size(PM_DESC, PM_SIZE + 0x20u, PM_SIZE + 0x24u) == 0 &&
              MEM_R32(PM_SIZE + 0x20u) == 320u && MEM_R32(PM_SIZE + 0x24u) == 320u,
          "MPEG PCM size query returns the documented fixed sizes");
    uint32_t pcm_sid = mpeg_regist_stream(PM_DESC, MPEG_PCM_STREAM, 0u);
    CHECK(pcm_sid != 0u &&
              mpeg_get_pcm_au(PM_DESC, pcm_sid, PM_SIZE + 0x28u, PM_SIZE + 0x40u) ==
                  SCE_MPEG_ERROR_NO_DATA,
          "MPEG PCM AU remains an explicit no-data refusal");
    CHECK(mpeg_change_get_au_mode(PM_DESC, pcm_sid, MPEG_AU_MODE_SKIP) == 0u &&
              mpeg_change_get_au_mode(PM_DESC, pcm_sid, 2u) != 0u,
          "MPEG AU skip mode is accepted and an unknown mode is refused");
    mpeg_finish();
}

/* ---- movie frame writers behind the swizzled VRAM mirrors (#1049) ------------------------
 * Hot Shots Tennis hands its movie buffers to sceMpegAvcCsc / sceMpegAvcDecode through the
 * 0x042 and 0x046 mirror views of VRAM. The bulk writers used to refuse such a span (and log
 * VRAM_MIRROR_BULK_UNSUPPORTED), so the picture never reached VRAM. Every case below compares
 * the whole 2 MiB of physical VRAM against an image built from sr_vram_cpu_address(). */

/* PSP pixel bytes of one RGBA source pixel, written from the public format definitions. */
static uint32_t ref_pixel_bytes(int mode, const uint8_t *px, uint8_t out[4]) {
    unsigned r = px[0], g = px[1], b = px[2];
    uint16_t v;
    switch (mode) {
        case 0: v = (uint16_t)((r >> 3) | ((g >> 2) << 5) | ((b >> 3) << 11)); break;
        case 1: v = (uint16_t)((r >> 3) | ((g >> 3) << 5) | ((b >> 3) << 10) | 0x8000u); break;
        case 2: v = (uint16_t)((r >> 4) | ((g >> 4) << 4) | ((b >> 4) << 8) | 0xF000u); break;
        default: memcpy(out, px, 4u); return 4u;
    }
    out[0] = (uint8_t)v;
    out[1] = (uint8_t)(v >> 8);
    return 2u;
}

/* The whole physical VRAM equals the expected image. */
static int vram_matches_image(const uint8_t *image) {
    return memcmp(vram_phys_byte(SR_VRAM_CPU_BASE), image, VRAM_PHYS_BYTES) == 0;
}

/* Record `n` bytes written at guest address `guest_addr` in the expected image. */
static void image_store(uint8_t *image, uint32_t guest_addr, const uint8_t *bytes, uint32_t n) {
    for (uint32_t i = 0; i < n; i++) {
        uint32_t phys = sr_vram_cpu_address(guest_addr + i);
        if (phys >= SR_VRAM_CPU_BASE && phys < SR_VRAM_CPU_BASE + VRAM_PHYS_BYTES)
            image[phys - SR_VRAM_CPU_BASE] = bytes[i];
    }
}

#define CSC_W 64u
#define CSC_H 32u

static void test_mpeg_csc_swizzled_vram_mirrors(void) {
    enum {
        MC_DESC = 0x08300000u,
        MC_DATA = 0x08310000u,
        MC_YCBCR = 0x08320000u,
        MC_RANGE = 0x08330000u,
        MC_MODE = 0x08340000u,
        MC_RAM_DEST = 0x08350000u,
    };
    static uint8_t image[VRAM_PHYS_BYTES];
    /* The measured placement: the destination is written from its first pixel, x selects the
     * source columns and the rows come from the top of the picture. */
    const struct { uint32_t x, y, w, h, frame_width; const char *name; } cases[] = {
        { 0u, 0u, CSC_W, CSC_H, CSC_W, "whole picture" },
        { 16u, 16u, 40u, 6u, 80u, "partial range in a wider buffer" },
    };

    MEM_W32(MC_DESC, 0u);
    CHECK(mpeg_create(MC_DESC, MC_DATA, 0x10000u, 0, CSC_W, 0, 0) == 0,
          "mirror CSC fixture creates a context");
    CHECK(mpeg_avc_init_ycbcr(MC_DESC, 1u, CSC_W, CSC_H, MC_YCBCR) == 0,
          "mirror CSC fixture initializes a YCbCr allocation");
    /* Samples that differ per pixel, so a displaced or repeated piece cannot match. */
    ref_ycbcr_fill(MC_YCBCR, CSC_W, CSC_H, 0, 0u, 0u, 0u);

    for (int mode = 0; mode <= 3; mode++) {
        MEM_W32(MC_MODE, 0u);
        MEM_W32(MC_MODE + 4u, (uint32_t)mode);
        CHECK(guest_mpeg_import(0xa11c7026u, MC_DESC, MC_MODE, 0u, 0u, 0u) == 0,
              "mirror CSC fixture selects the pixel mode through the guest import");
        const uint32_t bpp = mode == 3 ? 4u : 2u;
        for (size_t c = 0; c < sizeof(cases) / sizeof(cases[0]); c++) {
            MEM_W32(MC_RANGE, cases[c].x);
            MEM_W32(MC_RANGE + 4u, cases[c].y);
            MEM_W32(MC_RANGE + 8u, cases[c].w);
            MEM_W32(MC_RANGE + 12u, cases[c].h);
            /* Every VRAM destination, then linear RAM as the control. */
            for (size_t d = 0; d <= VRAM_DEST_COUNT; d++) {
                const int in_ram = d == VRAM_DEST_COUNT;
                const uint32_t dest = in_ram ? MC_RAM_DEST : k_vram_dests[d].base;
                const char *name = in_ram ? "RAM" : k_vram_dests[d].name;
                vram_fill_sentinel();
                memset(vram_phys_byte(MC_RAM_DEST), (int)VRAM_SENTINEL, 0x4000u);
                memset(image, (int)VRAM_SENTINEL, sizeof(image));
                uint32_t result = guest_mpeg_import(0x31bd0272u, MC_DESC, MC_YCBCR, MC_RANGE,
                                                    cases[c].frame_width, dest);
                int ok = result == 0u;
                for (uint32_t r = 0; r < cases[c].h; r++)
                    for (uint32_t col = 0; col < cases[c].w; col++) {
                        uint8_t px[4], bytes[4];
                        ref_ycbcr_rgba(MC_YCBCR, cases[c].x + col, r, px);
                        const uint32_t n = ref_pixel_bytes(mode, px, bytes);
                        const uint32_t addr = dest + (r * cases[c].frame_width + col) * bpp;
                        if (in_ram) {
                            for (uint32_t i = 0; i < n; i++)
                                if (*vram_phys_byte(addr + i) != bytes[i]) ok = 0;
                        } else {
                            image_store(image, addr, bytes, n);
                        }
                    }
                /* A VRAM destination must match its image; a RAM one must leave VRAM untouched. */
                if (!vram_matches_image(image)) ok = 0;
                if (!ok)
                    fprintf(stderr, "  CSC mode %d, %s, destination %s: result 0x%08x\n", mode,
                            cases[c].name, name, (unsigned)result);
                CHECK(ok, "sceMpegAvcCsc writes each pixel at the physical address its "
                          "destination address translates to, and nothing else");
            }
        }
    }
    mpeg_finish();
}

/* sceMpegAvcDecode's blank-frame path (no picture decoded yet) clears the whole buffer. */
static void test_mpeg_avc_decode_clear_in_vram_mirrors(void) {
    enum {
        MD_DESC = 0x08360000u,
        MD_DATA = 0x08370000u,
        MD_AU = 0x08380000u,
        MD_PTR = 0x08390000u,
        MD_INIT = 0x083a0000u,
    };
    static uint8_t image[VRAM_PHYS_BYTES];
    static const uint8_t zero = 0u;
    MEM_W32(MD_DESC, 0u);
    CHECK(mpeg_create(MD_DESC, MD_DATA, 0x10000u, 0, 64u, 0, 0) == 0,
          "mirror AvcDecode fixture creates a context");
    Mpeg *ctx = mpeg_find(MD_DESC);
    CHECK(ctx != NULL, "mirror AvcDecode fixture finds its context");
    if (!ctx) return;
    ctx->streamWidth = 64u;
    ctx->streamHeight = 64u;
    ctx->h264 = sr_h264_create();
    ctx->h264Init = 1;
    if (ctx->h264 < 0) {
        fprintf(stderr, "SKIP: sceMpegAvcDecode blank-frame clear needs a decoder instance\n");
        mpeg_finish();
        return;
    }
    for (int mode = 3; mode >= 0; mode -= 3) {
        ctx->pixelMode = mode;
        const uint32_t bytes = 64u * 64u * (mode == 3 ? 4u : 2u);
        for (size_t d = 0; d < VRAM_DEST_COUNT; d++) {
            vram_fill_sentinel();
            memset(image, (int)VRAM_SENTINEL, sizeof(image));
            for (uint32_t i = 0; i < bytes; i++)
                image_store(image, k_vram_dests[d].base + i, &zero, 1u);
            memset(SR_HOST(MD_AU), 0, 24u);
            MEM_W32(MD_PTR, k_vram_dests[d].base);
            MEM_W32(MD_INIT, 0xdeadbeefu);
            uint32_t result = guest_mpeg_import(0x0e3c2e9du, MD_DESC, MD_AU, 64u, MD_PTR, MD_INIT);
            int ok = result == SCE_MPEG_ERROR_NO_DATA && MEM_R32(MD_INIT) == 0u &&
                     vram_matches_image(image);
            if (!ok)
                fprintf(stderr, "  AvcDecode mode %d, destination %s: result 0x%08x\n", mode,
                        k_vram_dests[d].name, (unsigned)result);
            CHECK(ok, "sceMpegAvcDecode clears its blank frame through any VRAM view, "
                      "touching only the destination's physical bytes");
        }
    }
    mpeg_finish();
}

/* ---- scePsmfPlayer: A/V presentation timing at the guest boundaries (issue #279) -------- */

/* Latch SR_MPEGLOG before the player's first produce call: hle.c caches the flag the first
 * time it is consulted.  The feature-test macro above exposes the platform putenv prototype
 * on POSIX; the Windows CRT name (_putenv) comes from <stdlib.h>. */
static char s_av_mpeglog_env[] = "SR_MPEGLOG=1";
static void av_latch_mpeglog(void) {
#ifdef _WIN32
    _putenv(s_av_mpeglog_env);
#else
    putenv(s_av_mpeglog_env);
#endif
}

static void test_psmf_log_tick_instance_isolation(void) {
    const uint32_t first_guest = 0x085f0000u;
    const uint32_t second_guest = 0x085f0004u;
    av_latch_mpeglog();
    CHECK(sr_hle_test_psmf_summary_rejects_truncation(),
          "psmf counters detect a summary that cannot fit its destination");
    uint32_t before = sr_hle_test_psmf_summary_count();
    for (int i = 0; i < 8; i++) sr_hle_test_psmf_log_tick(first_guest);
    CHECK(sr_hle_test_psmf_summary_count() == before + 8u,
          "each player's first eight counter ticks are published");
    sr_hle_test_psmf_log_tick(first_guest);
    CHECK(sr_hle_test_psmf_summary_count() == before + 8u,
          "the periodic counter interval is per player");
    sr_hle_test_psmf_log_tick(second_guest);
    CHECK(sr_hle_test_psmf_summary_count() == before + 9u,
          "a second player starts with its own counter sampling interval");
    sr_hle_test_psmf_log_release(first_guest);
    sr_hle_test_psmf_log_release(second_guest);
}

/* The player's only source boundary is iso_lookup/iso_read.  While the player test runs,
 * this fixture serves its container straight out of memory -- the same pattern the
 * executable HLE harness uses -- so the production player path runs without mounting an
 * image.  iso_list/iso_physical_lba are linked from hle.c and stay deliberate dead ends. */
static const uint8_t *s_player_image;
static uint32_t s_player_image_size;
static const char s_player_path[] = "disc0:/media/av_timing.psmf";

int iso_lookup(const char *guest_path, uint32_t *out_lba, uint32_t *out_size) {
    if (s_player_image && guest_path && strcmp(guest_path, s_player_path) == 0) {
        if (out_lba) *out_lba = 0u;
        if (out_size) *out_size = s_player_image_size;
        return 0;
    }
    (void)guest_path; (void)out_lba; (void)out_size;
    return -1;
}

int iso_read(uint32_t lba, uint32_t offset, void *dst, uint32_t bytes) {
    if (s_player_image && lba == 0u && dst && offset < s_player_image_size) {
        uint32_t n = s_player_image_size - offset;
        if (n > bytes) n = bytes;
        memcpy(dst, s_player_image + offset, n);
        return (int)n;
    }
    (void)lba; (void)offset; (void)dst; (void)bytes;
    return -1;
}

int iso_list(const char *guest_path, uint32_t index, IsoDirEntry *out) {
    (void)guest_path; (void)index; (void)out;
    return -1;
}

uint32_t iso_physical_lba(uint32_t lba_or_token) { return lba_or_token; }

int iso_sector_count(uint32_t *out_sectors) {
    (void)out_sectors;
    return -1;
}

/* scePsmfPlayer NIDs and results (public PSP NIDs; same values the executable HLE harness
 * enters). */
#define AV_NID_CREATE      0x235d8787u
#define AV_NID_SET_PSMF    0x58b83577u
#define AV_NID_START       0x95a84ee5u
#define AV_NID_UPDATE      0xa0b8ca55u
#define AV_NID_GET_VIDEO   0x46f61f8bu
#define AV_NID_GET_AUDIO   0xb9848a74u
#define AV_NID_GET_STATUS  0xf8ef08a6u
#define AV_NID_DELETE      0x9b71a274u
#define AV_NID_GET_INFO    0xdf089680u
#define AV_NID_RELEASE     0xe792cd94u
#define AV_STATUS_PLAYING  0x00000004u
#define AV_STATUS_FINISHED 0x00000200u
#define AV_ERR_NO_DATA     0x8061600cu
#define AV_ERR_STATUS      0x80616001u
#define AV_ERR_ILLEGAL_ADDR 0x800200d3u

/* Guest addresses for this test; well above the FC_/TD_ blocks and GUEST_BUF. */
#define AV_PLAYER 0x08600000u   /* player uid, also the uid's out-pointer */
#define AV_CREATE 0x08601000u   /* ScePsmfPlayerCreateParams */
#define AV_PATH   0x08602000u   /* source path string */
#define AV_CONFIG 0x08603000u   /* ScePsmfPlayerConfigData */
#define AV_VIDEO  0x08604000u   /* ScePsmfPlayerVideoData: frameWidth, displaybuf, displaypts */
#define AV_AUDIO  0x08605000u   /* one 8192-byte PCM sink */
#define AV_INFO   0x08606000u   /* PsmfInfo (20 bytes), then the width and height words */

/* The authored timelines.  Video spacing *is* PSMF_VIDEO_PTS_STEP: 90000 * 1001 / 30000 = 3003
 * ticks exactly at 29.97 fps (30000/1001), so video PTS drift is identically 0.
 *
 * Audio presentation timing in 90 kHz ticks:
 *   2048 samples * 90000 / 44100 = 204800 / 49 = 4179 + 29/49 = 4179.5918367... ticks.
 * The player advances unanchored audio access units by integer PSMF_AUDIO_PTS_STEP = 4180 ticks,
 * over-advancing by +20/49 (~0.40816) ticks per block.
 *
 * PES packets carry PTS anchors every AV_AUDIO_ANCHOR = 8 blocks, resetting the clock to the
 * authored timeline.  Between anchors, at most AV_AUDIO_ANCHOR - 1 = 7 blocks are extrapolated,
 * accumulating at most 7 * (20/49) = 140/49 = 20/7 ≈ 2.857 ticks of step error.
 * With integer rounding of anchor timestamps (+-0.5 tick), the worst-case deviation between
 * the player's clock and the authored timeline is ceil(20/7 + 0.5) = 3 ticks.
 *
 * Because video PTS drift is 0, the A/V gap drift (avgap - authored) equals the audio PTS
 * drift exactly (|avgap - authored| <= 3 ticks).
 *
 * AV_AUDIO_PTS_DRIFT_TICKS = 7LL is therefore provably conservative: the theoretical maximum
 * drift is 3 ticks (AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT), leaving 4 ticks of safety margin. */
#define AV_PICTURES      90                 /* ~3.0 s of 29.97 fps pictures */
#define AV_AUDIO_BLOCKS  65                 /* ~3.0 s of 2048-sample blocks at 44.1 kHz */
#define AV_VIDEO_ANCHOR  4                  /* pictures whose PES packet carries a PTS */
#define AV_AUDIO_ANCHOR  8                  /* audio blocks whose PES packet carries a PTS */
#define AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT 3LL /* first-principles maximum audio / gap drift */
#define AV_AUDIO_PTS_DRIFT_TICKS 7LL        /* conservative tolerance bound (4-tick margin) */

static int64_t av_video_pts(int picture) { return (int64_t)picture * PSMF_VIDEO_PTS_STEP; }
static int64_t av_audio_pts(int block) {
    return (int64_t)(((uint64_t)block * 2048ull * 90000ull + 22050ull) / 44100ull);
}

/* Packet layouts of the A/V timing container.  SPLIT cuts every picture across two PES
 * packets and gives every ATRAC frame its own packet.  PACKED is the shape of a PSP movie:
 * one timestamped video packet carries two whole pictures and one timestamped audio packet
 * carries up to AV_AUDIO_PER_PES frames, so only the first unit commencing in each packet owns
 * that packet's time (ISO/IEC 13818-1 2.4.3.7) and every later one must be extrapolated. */
enum { AV_LAYOUT_SPLIT = 0, AV_LAYOUT_PACKED = 1 };
#define AV_AUDIO_PER_PES 3

/* Assemble the A/V timing container: a player-valid PSMF header (presentation base and
 * stream table included -- scePsmfPlayer refuses anything else), the authored I_PCM
 * pictures, and decodable ATRAC3+ frames interleaved with PTS anchors on both tracks, in
 * one of the packet layouts above. */
static uint8_t *build_psmf_av(uint32_t *size_out, int layout) {
    static uint8_t es[1024u * 1024u];
    uint32_t au_off[AV_PICTURES], au_len[AV_PICTURES];
    ByteOut o;
    o.d = es; o.cap = sizeof(es); o.n = 0; o.overflow = 0;
    for (int k = 0; k < AV_PICTURES; k++) {
        au_off[k] = o.n;
        build_au_ex(k, FIX_W_MBS, FIX_H_MBS,
                    k_y[k % FIX_PICTURES], k_cb[k % FIX_PICTURES], k_cr[k % FIX_PICTURES], &o);
        au_len[k] = o.n - au_off[k];
    }
    CHECK(!o.overflow, "A/V timing elementary stream fits its buffer");
    if (o.overflow) return NULL;

    Buf b;
    b.cap = 2048u + o.n * 2u + 16384u;
    b.d = (uint8_t *)calloc(1, b.cap);
    b.at = 2048u;
    b.overflow = 0;
    if (!b.d) return NULL;
    b.d[0] = 'P'; b.d[1] = 'S'; b.d[2] = 'M'; b.d[3] = 'F';
    be32_at(b.d + 8, 2048u);
    /* presentation base and duration, so the producer normalizes against the header the way * scePsmfPlayer does instead of against a test-side constant. */
    b.d[0x54] = 0; b.d[0x55] = 0; b.d[0x56] = 0;
    b.d[0x57] = (uint8_t)(FIX_BASE >> 16);
    b.d[0x58] = (uint8_t)(FIX_BASE >> 8);
    b.d[0x59] = (uint8_t)FIX_BASE;
    /* The last timestamp closes the final picture: base + AV_PICTURES picture steps. */
    be48_at(b.d + 0x5a, FIX_BASE + av_video_pts(AV_PICTURES));
    /* Stream table: one video entry (non-zero version fields keep playerVersion 0) and one
     * audio entry whose byte 14 declares the ATRAC3+ channel count. */
    b.d[0x80] = 0; b.d[0x81] = 2;
    b.d[0x82] = 0xe0u;
    be32_at(b.d + 0x86, 1u);
    be32_at(b.d + 0x8a, 1u);
    b.d[0x8e] = (uint8_t)FIX_W_MBS;        /* width in 16-pixel units */
    b.d[0x8f] = (uint8_t)FIX_H_MBS;        /* height */
    b.d[0x92] = 0xbdu;
    b.d[0x93] = 0x00u;                     /* sub-stream id 0x00 */
    /* Entry 14 of this entry (0x92 + 14 = 0xa0) is the ATRAC3+ channel count the
     * player copies into audioChannels; writing it anywhere else leaves the count zero
     * and every decoded-looking frame is rejected for an implausible channel count. */
    b.d[0x92 + 14] = 2u;                   /* stereo */
    for (int i = 0; i < AV_PICTURES; i++) mp4_picture_marks(es + au_off[i], au_len[i], i);

    uint8_t frame[64];
    uint8_t packed_frames[64u * AV_AUDIO_PER_PES];
    uint32_t frame_bytes = make_audio_frame(frame, sizeof(frame), 0x28, 0x00, 0x00);
    frame[8] = 0x60u;      /* terminator-first ATRAC unit: a frame the project's own
                            * ATRAC3+ bridge really decodes (2048 samples, stereo) */
    for (int i = 0; i < AV_AUDIO_PER_PES; i++)
        memcpy(packed_frames + (size_t)i * frame_bytes, frame, frame_bytes);
    int audio_next = 0;
    if (layout == AV_LAYOUT_PACKED) {
        CHECK(AV_PICTURES % 2 == 0, "the packed layout pairs every picture");
        for (int k = 0; k < AV_PICTURES; k += 2) {
            /* One timestamped packet, two whole pictures: the packet's PTS is picture k's. */
            uint32_t pair = au_len[k] + au_len[k + 1];
            CHECK(au_off[k] + au_len[k] == au_off[k + 1], "paired pictures are contiguous");
            add_video_pes(&b, 1, FIX_BASE + av_video_pts(k), es + au_off[k], pair);
            int upto = (k + 2) * AV_AUDIO_BLOCKS / AV_PICTURES;
            if (k + 2 >= AV_PICTURES) upto = AV_AUDIO_BLOCKS;
            /* Full packets while enough frames are due, the remainder with the last pair. */
            while (upto - audio_next >= AV_AUDIO_PER_PES ||
                   (k + 2 >= AV_PICTURES && audio_next < upto)) {
                int n = upto - audio_next;
                if (n > AV_AUDIO_PER_PES) n = AV_AUDIO_PER_PES;
                add_audio_pes_sub(&b, 0x00u, 1, FIX_BASE + av_audio_pts(audio_next),
                                  packed_frames, (uint32_t)n * frame_bytes);
                audio_next += n;
            }
        }
    } else {
        for (int k = 0; k < AV_PICTURES; k++) {
            uint32_t half = au_len[k] / 2u;
            add_video_pes(&b, (k % AV_VIDEO_ANCHOR) == 0,
                          FIX_BASE + av_video_pts(k), es + au_off[k], half);
            add_video_pes(&b, 0, 0, es + au_off[k] + half, au_len[k] - half);
            int upto = (k + 1) * AV_AUDIO_BLOCKS / AV_PICTURES;
            while (audio_next < upto) {
                int j = audio_next++;
                add_audio_pes_sub(&b, 0x00u, (j % AV_AUDIO_ANCHOR) == 0,
                                  FIX_BASE + av_audio_pts(j), frame, frame_bytes);
            }
        }
    }
    CHECK(audio_next == AV_AUDIO_BLOCKS, "every authored audio block is written");
    be32_at(b.d + 12, b.at - 2048u);
    CHECK(!b.overflow, "A/V timing container fits its buffer");
    uint32_t packets_written = layout == AV_LAYOUT_PACKED
        ? (uint32_t)(AV_PICTURES / 2 + (AV_AUDIO_BLOCKS + AV_AUDIO_PER_PES - 1) / AV_AUDIO_PER_PES)
        : (uint32_t)(AV_PICTURES * 2 + AV_AUDIO_BLOCKS);
    CHECK(pes_count(b.d, b.at) >= packets_written,
          "the A/V container holds every packet the builder wrote");
    *size_out = b.at;
    return b.d;
}

static void av_write_cstr(uint32_t addr, const char *s) {
    memcpy(SR_HOST(addr), s, strlen(s) + 1u);
}

/* ---- scePsmfPlayer lifecycle: a player gives back what it acquired (issue #279) -------- */

#define LC_CYCLES  8                    /* twice the four decoder instances a backend has */
#define LC_PLAYERS 0x08610000u          /* control blocks for the lifecycle cycles */

static void lc_prepare_guest(void) {
    MEM_W32(AV_CREATE + 0, 0x08700000u);      /* player read buffer (never dereferenced here) */
    MEM_W32(AV_CREATE + 4, 0x00285800u);      /* the size scePsmfPlayerCreate requires */
    MEM_W32(AV_CREATE + 8, 0x30u);            /* priority inside the accepted range */
    av_write_cstr(AV_PATH, s_player_path);
    MEM_W32(AV_CONFIG + 0, 0x0eu);            /* H.264 video */
    MEM_W32(AV_CONFIG + 4, 0u);
    MEM_W32(AV_CONFIG + 8, 0x0fu);            /* ATRAC3+ audio */
    MEM_W32(AV_CONFIG + 12, 0u);
    MEM_W32(AV_CONFIG + 16, 0u);
    MEM_W32(AV_CONFIG + 20, 0u);
    MEM_W32(AV_VIDEO + 0, 64u);
    MEM_W32(AV_VIDEO + 4, GUEST_BUF);
}

/* Open the A/V stream on `player`, start it and run it until the first picture reaches
 * the guest.  Returns 1 when that picture arrived with the first authored time. */
static int lc_play_first_picture(uint32_t player) {
    if (guest_mpeg_import(AV_NID_SET_PSMF, player, AV_PATH, 0, 0, 0) != 0 ||
        guest_mpeg_import(AV_NID_START, player, AV_CONFIG, 0, 0, 0) != 0)
        return 0;
    for (int i = 0; i < 64; i++) {
        if (guest_mpeg_import(AV_NID_GET_VIDEO, player, AV_VIDEO, 0, 0, 0) == 0)
            return (int64_t)MEM_R32(AV_VIDEO + 8) == av_video_pts(0);
        (void)guest_mpeg_import(AV_NID_GET_AUDIO, player, AV_AUDIO, 0, 0, 0);
        if (guest_mpeg_import(AV_NID_UPDATE, player, 0, 0, 0, 0) != 0) return 0;
    }
    return 0;
}

/* A backend has a fixed number of decoder instances (four for Media Foundation and for
 * FFmpeg).  scePsmfPlayerDelete used to reset the player's decoder and then forget its id,
 * and creating over a live control block forgot it too, so each movie kept one instance for
 * the rest of the session and the fifth movie got "H.264 backend unavailable" and no
 * picture.  A failed scePsmfPlayerCreate also kept the player slot it had claimed, so four
 * failures left no slot for a valid player. */
static void test_player_lifecycle_releases_what_it_acquired(void) {
    uint32_t size = 0;
    uint8_t *image = build_psmf_av(&size, AV_LAYOUT_SPLIT);
    if (!image) { CHECK(0, "lifecycle stream builds"); return; }
    av_latch_mpeglog();   /* hle.c caches SR_MPEGLOG at the first produce call */
    s_player_image = image;
    s_player_image_size = size;
    lc_prepare_guest();

    /* Failed creates claim nothing: four refusals, then a fifth control block is created. */
    MEM_W32(AV_CREATE + 4, 0x1000u);          /* smaller than scePsmfPlayerCreate requires */
    for (uint32_t i = 0; i < 4u; i++)
        CHECK(guest_mpeg_import(AV_NID_CREATE, LC_PLAYERS + i * 4u, AV_CREATE, 0, 0, 0) ==
                  0x80616005u,
              "psmf-lifecycle: an undersized player buffer is refused");
    MEM_W32(AV_CREATE + 4, 0x00285800u);
    CHECK(guest_mpeg_import(AV_NID_CREATE, LC_PLAYERS + 16u, AV_CREATE, 0, 0, 0) == 0,
          "psmf-lifecycle: refused creates leave every player slot free");
    CHECK(guest_mpeg_import(AV_NID_DELETE, LC_PLAYERS + 16u, 0, 0, 0, 0) == 0,
          "psmf-lifecycle: the probe player is deleted");

    if (!sr_h264_backend_available()) {
        fprintf(stderr, "SKIP: decoder-instance lifecycle needs an H.264 backend\n");
    } else {
        /* Create, play, delete: every cycle gets a decoder and a picture. */
        int pictures = 0;
        for (int c = 0; c < LC_CYCLES; c++) {
            CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0,
                  "psmf-lifecycle: the player is created");
            pictures += lc_play_first_picture(AV_PLAYER);
            CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0,
                  "psmf-lifecycle: the player is deleted");
        }
        CHECK(pictures == LC_CYCLES,
              "psmf-lifecycle: every create/play/delete cycle decodes its first picture");

        /* Creating over a live control block starts a fresh player and gives the old
         * player's decoder back. */
        pictures = 0;
        for (int c = 0; c < LC_CYCLES; c++) {
            CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0,
                  "psmf-lifecycle: a live control block is created again");
            pictures += lc_play_first_picture(AV_PLAYER);
        }
        CHECK(pictures == LC_CYCLES,
              "psmf-lifecycle: every re-created player decodes its first picture");
        CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0,
              "psmf-lifecycle: the re-created player is deleted");

        /* Nothing is left behind: the backend can still hand out a decoder. */
        int dec = sr_h264_create();
        CHECK(dec >= 0, "psmf-lifecycle: deleted players leave the decoder instances free");
        if (dec >= 0) sr_h264_destroy(dec);
    }
    s_player_image = NULL;
    s_player_image_size = 0;
    free(image);
}

/* ---- scePsmfPlayerGetPsmfInfo (issue #308) ------------------------------------------- */

static int av_info_is(uint32_t last, uint32_t video, uint32_t audio, uint32_t pcm, uint32_t ver) {
    return MEM_R32(AV_INFO + 0) == last && MEM_R32(AV_INFO + 4) == video &&
           MEM_R32(AV_INFO + 8) == audio && MEM_R32(AV_INFO + 12) == pcm &&
           MEM_R32(AV_INFO + 16) == ver;
}

/* A player is named by the handle Create stores in its ScePsmfPlayer word, not by the word's
 * address: a copy of the word passed from another structure names the same player, a word
 * holding anything else names none, and Delete ends the player for every copy. */
#define AV_PLAYER_COPY 0x08607000u
static void test_player_handle_word(void) {
    uint32_t size = 0;
    uint8_t *image = build_psmf_av(&size, AV_LAYOUT_SPLIT);
    if (!image) { CHECK(0, "psmf-handle stream builds"); return; }
    s_player_image = image;
    s_player_image_size = size;
    lc_prepare_guest();
    CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0 &&
              MEM_R32(AV_PLAYER) != 0u,
          "psmf-handle: Create stores a handle in the player word");
    MEM_W32(AV_PLAYER_COPY, MEM_R32(AV_PLAYER));
    CHECK(guest_mpeg_import(AV_NID_SET_PSMF, AV_PLAYER_COPY, AV_PATH, 0, 0, 0) == 0,
          "psmf-handle: a copy of the player word sets the PSMF");
    CHECK(guest_mpeg_import(AV_NID_GET_STATUS, AV_PLAYER, 0, 0, 0, 0) == 2u,
          "psmf-handle: the original word sees the state the copy set (STANDBY)");
    memset(SR_HOST(AV_INFO), 0xcc, 20u);
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER_COPY, AV_INFO, 0, 0, 0) == 0 &&
              MEM_R32(AV_INFO + 4u) == 1u,
          "psmf-handle: the copy reads the player's PSMF info");
    MEM_W32(AV_PLAYER_COPY + 4u, MEM_R32(AV_PLAYER) + 4u);
    CHECK(guest_mpeg_import(AV_NID_GET_STATUS, AV_PLAYER_COPY + 4u, 0, 0, 0, 0) == AV_ERR_STATUS,
          "psmf-handle: a word holding another value names no player");
    CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0 && MEM_R32(AV_PLAYER) == 0u,
          "psmf-handle: Delete clears the player word");
    CHECK(guest_mpeg_import(AV_NID_GET_STATUS, AV_PLAYER_COPY, 0, 0, 0, 0) == AV_ERR_STATUS,
          "psmf-handle: a copy of a deleted player's word names no player");
    s_player_image = NULL;
    s_player_image_size = 0;
    free(image);
}

/* The info is the opened PSMF's header as the player parsed it: the last picture's time
 * (the header duration less one picture), the video and audio stream counts, no PCM streams,
 * and the player version (0 when every video stream carries an EP map, 1 otherwise).  The
 * refusals are ILLEGAL_ADDR for an unusable player or info address and INVALID_STATUS for an
 * unknown player or one whose PSMF is not set; a refused call writes nothing.  The width and
 * height words are written only when the loaded libpsmfplayer build is 0x03090510, and then only
 * where the pointer is usable; any other build keeps the two-argument contract (#279). */
static void test_player_get_psmf_info(void) {
    uint32_t size = 0;
    uint8_t *image = build_psmf_av(&size, AV_LAYOUT_SPLIT);
    if (!image) { CHECK(0, "psmf-info stream builds"); return; }
    s_player_image = image;
    s_player_image_size = size;
    lc_prepare_guest();
    memset(SR_HOST(AV_INFO), 0xcc, 28u);

    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, AV_INFO + 20u, AV_INFO + 24u, 0) ==
              AV_ERR_STATUS,
          "psmf-info: a player that was never created is refused with INVALID_STATUS");
    CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0,
          "psmf-info: the player is created");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, AV_INFO + 20u, AV_INFO + 24u, 0) ==
              AV_ERR_STATUS,
          "psmf-info: a call before the PSMF is set is refused with INVALID_STATUS");
    CHECK(guest_bytes_are(AV_INFO, 28u, 0xcc), "psmf-info: a call before SetPsmf writes nothing");

    CHECK(guest_mpeg_import(AV_NID_SET_PSMF, AV_PLAYER, AV_PATH, 0, 0, 0) == 0,
          "psmf-info: the PSMF is set");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, 0, AV_INFO, 0, 0, 0) == AV_ERR_ILLEGAL_ADDR,
          "psmf-info: a null player address is refused with ILLEGAL_ADDR");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, 0x0c000000u, AV_INFO, 0, 0, 0) == AV_ERR_ILLEGAL_ADDR,
          "psmf-info: an unmapped player address is refused with ILLEGAL_ADDR");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, 0, 0, 0, 0) == AV_ERR_ILLEGAL_ADDR,
          "psmf-info: a null info pointer is refused with ILLEGAL_ADDR");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, 0x0bfffff0u, 0, 0, 0) == AV_ERR_ILLEGAL_ADDR,
          "psmf-info: an info span that leaves guest memory is refused with ILLEGAL_ADDR");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER + 4u, AV_INFO, 0, 0, 0) == AV_ERR_STATUS,
          "psmf-info: an address that holds no player is refused with INVALID_STATUS");
    CHECK(guest_bytes_are(AV_INFO, 28u, 0xcc), "psmf-info: refused calls write nothing");

    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, AV_INFO + 20u, AV_INFO + 24u, 0) == 0,
          "psmf-info: an opened player reports its PSMF info");
    CHECK(av_info_is((uint32_t)av_video_pts(AV_PICTURES - 1), 1u, 1u, 0u, 0u),
          "psmf-info: last picture time, one video and one audio stream, no PCM, version 0");
    CHECK(guest_bytes_are(AV_INFO + 20u, 8u, 0xcc),
          "psmf-info: the width and height words are left untouched");

    /* Build 0x03090510 writes the video size; any other build does not. */
    sr_hle_test_set_psmfplayer_lib_version(0x03090510u);
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, AV_INFO + 20u, AV_INFO + 24u, 0) == 0 &&
              MEM_R32(AV_INFO + 20u) == FIX_W_MBS * 16u && MEM_R32(AV_INFO + 24u) == FIX_H_MBS * 16u,
          "psmf-info: libpsmfplayer 0x03090510 writes the video width and height");
    memset(SR_HOST(AV_INFO + 20u), 0xcc, 8u);
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, 0, 0x0bfffffeu, 0) == 0 &&
              guest_bytes_are(AV_INFO + 20u, 8u, 0xcc),
          "psmf-info: 0x03090510 skips a null or unusable width or height pointer");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, AV_INFO + 20u, 0, 0) == 0 &&
              MEM_R32(AV_INFO + 20u) == FIX_W_MBS * 16u && guest_bytes_are(AV_INFO + 24u, 4u, 0xcc),
          "psmf-info: 0x03090510 writes the width alone when only that pointer is usable");
    memset(SR_HOST(AV_INFO + 20u), 0xcc, 8u);
    sr_hle_test_set_psmfplayer_lib_version(0x03090500u);
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, AV_INFO + 20u, AV_INFO + 24u, 0) == 0 &&
              guest_bytes_are(AV_INFO + 20u, 8u, 0xcc),
          "psmf-info: another libpsmfplayer build leaves the width and height words untouched");
    sr_hle_test_set_psmfplayer_lib_version(0u);
    CHECK(guest_mpeg_import(AV_NID_START, AV_PLAYER, AV_CONFIG, 0, 0, 0) == 0,
          "psmf-info: the player starts");
    memset(SR_HOST(AV_INFO), 0xcc, 20u);
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, 0, 0, 0) == 0 &&
              av_info_is((uint32_t)av_video_pts(AV_PICTURES - 1), 1u, 1u, 0u, 0u),
          "psmf-info: a playing player reports the same info");
    CHECK(guest_mpeg_import(AV_NID_RELEASE, AV_PLAYER, 0, 0, 0, 0) == 0,
          "psmf-info: the PSMF is released");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, 0, 0, 0) == AV_ERR_STATUS,
          "psmf-info: a released PSMF is refused with INVALID_STATUS");

    /* Two video and two audio streams; the second video stream has no EP map, which makes the
     * player a BASIC (version 1) player.  The header times are this test's own. */
    uint32_t a0o[FIX_PICTURES], a0l[FIX_PICTURES], a1o[FIX_PICTURES], a1l[FIX_PICTURES];
    uint32_t multi_size = 0;
    uint8_t *multi = build_multistream_psmf(&multi_size, a0o, a0l, a1o, a1l);
    if (!multi) {
        CHECK(0, "psmf-info multistream stream builds");
    } else {
        be48_at(multi + 0x54, FIX_BASE);
        be48_at(multi + 0x5a, FIX_BASE + 10 * PSMF_VIDEO_PTS_STEP);
        be32_at(multi + 0x96, 0u);           /* video entry 1: no EP map offset */
        s_player_image = multi;
        s_player_image_size = multi_size;
        CHECK(guest_mpeg_import(AV_NID_SET_PSMF, AV_PLAYER, AV_PATH, 0, 0, 0) == 0,
              "psmf-info: the multistream PSMF is set");
        memset(SR_HOST(AV_INFO), 0xcc, 20u);
        CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, 0, 0, 0) == 0 &&
                  av_info_is(9u * PSMF_VIDEO_PTS_STEP, 2u, 2u, 0u, 1u),
              "psmf-info: two video and two audio streams, no PCM, BASIC version 1");
        free(multi);
    }
    CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0,
          "psmf-info: the player is deleted");
    CHECK(guest_mpeg_import(AV_NID_GET_INFO, AV_PLAYER, AV_INFO, 0, 0, 0) == AV_ERR_STATUS,
          "psmf-info: a deleted player is refused with INVALID_STATUS");
    s_player_image = NULL;
    s_player_image_size = 0;
    free(image);
}

/* scePsmfPlayerGetVideoData with the display buffer behind each VRAM view: the first authored
 * picture must reach VRAM at the translated addresses (the Hot Shots Tennis Cinema path). */
static void test_psmf_player_display_in_vram_mirrors(void) {
    if (!sr_h264_backend_available()) {
        fprintf(stderr, "SKIP: PSMF player VRAM display needs an H.264 backend\n");
        return;
    }
    uint32_t size = 0;
    uint8_t *image = build_psmf_av(&size, AV_LAYOUT_SPLIT);
    if (!image) { CHECK(0, "VRAM display stream builds"); return; }
    av_latch_mpeglog();
    s_player_image = image;
    s_player_image_size = size;
    lc_prepare_guest();
    static const uint8_t picture0[4] = { 255u, 203u, 138u, 0u };   /* alpha 0, as the PSP writes it */
    for (size_t d = 0; d < VRAM_DEST_COUNT; d++) {
        vram_fill_sentinel();
        MEM_W32(AV_VIDEO + 4, k_vram_dests[d].base);
        CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0,
              "psmf-vram: the player is created");
        int first = lc_play_first_picture(AV_PLAYER);
        int pixels = vram_rgba_matches(k_vram_dests[d].base, 64, 64, picture0);
        int exact = vram_changed_bytes() == 64u * 64u * 4u;
        if (!first || !pixels || !exact)
            fprintf(stderr, "  PSMF display %s: picture=%d pixels=%d exact=%d\n",
                    k_vram_dests[d].name, first, pixels, exact);
        CHECK(first, "psmf-vram: the first picture is delivered into a VRAM display buffer");
        CHECK(pixels, "psmf-vram: scePsmfPlayerGetVideoData writes the picture at the "
                      "physical addresses of the display buffer");
        CHECK(exact, "psmf-vram: the picture changes exactly the display buffer's physical bytes");
        CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0,
              "psmf-vram: the player is deleted");
    }
    s_player_image = NULL;
    s_player_image_size = 0;
    free(image);
}

/* One "key=value" number from a published counter line. */
static int av_log_field(const char *line, const char *key, long long *out) {
    const char *p = (line && *line) ? strstr(line, key) : NULL;
    if (!p) return 0;
    *out = strtoll(p + strlen(key), NULL, 10);
    return 1;
}

/* Sampler state for the published counter line, reset by each test run. */
static long long s_av_ckpt_aout[96], s_av_ckpt_ats[96];
static int s_av_ckpt_n;
static int s_av_eof_seen;
static uint32_t s_av_seen_summaries;

/* Read every counter line published since the previous sample and run the issue #279
 * acceptance checks on it: conservation of both disposition censuses at a production
 * snapshot, the ring-loss invariant, and both presentation clocks against the authored
 * timelines at the guest-getter boundary. */
static void av_sample_summaries(void) {
    uint32_t count = sr_hle_test_psmf_summary_count();
    if (count == s_av_seen_summaries) return;
    s_av_seen_summaries = count;
    const char *line = sr_hle_test_psmf_last_summary();
    long long vsub = 0, vdec = 0, vout = 0, vhold = 0, veos = 0, vrej = 0;
    long long asub = 0, adec = 0, aout = 0, ahold = 0, aeos = 0, arej = 0;
    long long frames = 0, eof = 0, failed = 0, vts = 0, ats = 0;
    long long avgap = 0, vlead = 0, vlost = 0;
    int have =
        av_log_field(line, " vsub=", &vsub) && av_log_field(line, " vdec=", &vdec) &&
        av_log_field(line, " vout=", &vout) && av_log_field(line, " vhold=", &vhold) &&
        av_log_field(line, " veos=", &veos) && av_log_field(line, " vrej=", &vrej) &&
        av_log_field(line, " asub=", &asub) && av_log_field(line, " adec=", &adec) &&
        av_log_field(line, " aout=", &aout) && av_log_field(line, " ahold=", &ahold) &&
        av_log_field(line, " aeos=", &aeos) && av_log_field(line, " arej=", &arej) &&
        av_log_field(line, " frames=", &frames) && av_log_field(line, " eof=", &eof) &&
        av_log_field(line, " failed=", &failed) && av_log_field(line, " vts=", &vts) &&
        av_log_field(line, " ats=", &ats) && av_log_field(line, " avgap=", &avgap) &&
        av_log_field(line, " vlead=", &vlead) && av_log_field(line, " vlost=", &vlost);
    if (!have) {
        CHECK(0, "published counter line carries every media field");
        return;
    }
    (void)asub; (void)adec;
    check_media_conservation("published video", (uint64_t)vdec, (uint64_t)vout,
                             (uint64_t)vhold, (uint64_t)veos, (uint64_t)vrej);
    check_media_conservation("published audio", (uint64_t)adec, (uint64_t)aout,
                             (uint64_t)ahold, (uint64_t)aeos, (uint64_t)arej);
    CHECK(vlost == 0, "the presentation ring never displaces a submitted picture's time");
    CHECK(failed == 0, "the acceptance route never trips a demuxer failure");
    if (eof) s_av_eof_seen = 1;
    if (frames > 0) {
        CHECK(vts == av_video_pts((int)frames - 1),
              "published displaypts equals the authored picture time at the getter");
        long long lead_limit = (long long)(eof ? PSMF_OUT_PTS_CAPACITY :
                                                PSMF_OUT_PTS_RING) * PSMF_VIDEO_PTS_STEP;
        CHECK(vlead >= 0 && vlead <= lead_limit,
              "submitted-minus-delivered stays inside its normal or bounded EOS-tail capacity");
    }
    if (aout > 0 && ats >= 0) {
        CHECK(llabs(ats - av_audio_pts((int)aout - 1)) <= AV_AUDIO_PTS_DRIFT_TICKS,
              "published audio pts stays within the 90 kHz anchor-drift bound");
        CHECK(llabs(ats - av_audio_pts((int)aout - 1)) <= AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT,
              "published audio pts stays within the theoretical 3-tick drift bound");
        /* One checkpoint per delivered block: two samples taken between two deliveries
         * repeat the same presentation point, and comparing a point with itself would
         * claim the series stopped advancing when nothing was delivered yet. */
        if (s_av_ckpt_n == 0 || aout != s_av_ckpt_aout[s_av_ckpt_n - 1]) {
            if (s_av_ckpt_n < (int)(sizeof(s_av_ckpt_aout) / sizeof(s_av_ckpt_aout[0]))) {
                s_av_ckpt_aout[s_av_ckpt_n] = aout;
                s_av_ckpt_ats[s_av_ckpt_n] = ats;
                s_av_ckpt_n++;
            }
        }
    }
    if (frames > 0 && aout > 0) {
        int64_t authored = av_video_pts((int)frames - 1) - av_audio_pts((int)aout - 1);
        CHECK(llabs(avgap - authored) <= AV_AUDIO_PTS_DRIFT_TICKS,
              "the published A/V gap equals the two authored positions at comparable points");
        CHECK(llabs(avgap - authored) <= AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT,
              "the published A/V gap stays within theoretical 3-tick drift bound");
        CHECK(llabs(avgap) <= PSMF_AUDIO_PTS_STEP + 3 * PSMF_VIDEO_PTS_STEP,
              "the presentation-boundary A/V gap stays within a block plus a picture of slack");
    }
}

/* First-principles verification of the audio clock, video clock, and A/V gap drift bounds.
 * Demonstrates mathematically and empirically that:
 * 1. Video presentation step is exact (3003 ticks per frame at 29.97 fps, zero drift).
 * 2. Integer PSMF_AUDIO_PTS_STEP (4180) over-advances by 20/49 (~0.40816) ticks per block
 *    relative to exact 44.1 kHz mapping (4179 + 29/49 ticks).
 * 3. Over at most 7 unanchored blocks between 8-block PES anchors, accumulated drift is
 *    7 * (20/49) = 2.857 ticks, which with +-0.5 tick anchor rounding never exceeds 3 ticks.
 * 4. The terminal audio block (block 64) carries an anchor, so terminal drift is 0 ticks.
 * 5. Because video drift is 0, the A/V gap drift equals audio drift (<= 3 ticks).
 * 6. The 7-tick AV_AUDIO_PTS_DRIFT_TICKS bound has a comfortable 4-tick margin above the
 *    3-tick theoretical maximum drift. */
static void test_psmf_av_timing_first_principles(void) {
    /* 1. Video step is exact in 90 kHz ticks: 29.97 fps is 30000 / 1001 fps. */
    CHECK((int64_t)PSMF_VIDEO_PTS_STEP * 30000LL == 90000LL * 1001LL,
          "psmf first-principles: video PTS step 3003 is exact with zero drift");

    /* 2. Audio exact step: 2048 * 90000 / 44100 = 204800 / 49 = 4179 + 29/49 ticks.
     * The player integer step 4180 over-advances by 20/49 (~0.40816) ticks per block. */
    const uint64_t num = 2048ull * 90000ull;
    const uint64_t den = 44100ull;
    CHECK(num / den == 4179ull && num % den == 26100ull,
          "psmf first-principles: exact audio step quotient is 4179 ticks (remainder 26100)");
    CHECK((uint64_t)PSMF_AUDIO_PTS_STEP * den - num == 18000ull,
          "psmf first-principles: integer step 4180 exceeds exact step by 18000/44100 (20/49)");

    /* 3. Simulate audio clock across all blocks of the test stream. */
    int64_t clock = 0;
    int valid = 0;
    int64_t max_audio_drift = 0;
    for (int j = 0; j < AV_AUDIO_BLOCKS; j++) {
        int has_pts = (j % AV_AUDIO_ANCHOR) == 0;
        int64_t authored = av_audio_pts(j);
        if (has_pts) {
            clock = authored;
            valid = 1;
        } else if (valid) {
            clock += PSMF_AUDIO_PTS_STEP;
        }
        int64_t drift = llabs(clock - authored);
        if (drift > max_audio_drift) max_audio_drift = drift;
        CHECK(drift <= AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT,
              "psmf first-principles: simulated audio drift stays <= theoretical max (3 ticks)");
        CHECK(drift <= AV_AUDIO_PTS_DRIFT_TICKS,
              "psmf first-principles: simulated audio drift stays <= tolerance (7 ticks)");
    }
    CHECK(max_audio_drift == AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT,
          "psmf first-principles: maximum audio drift across the authored stream is exactly 3 ticks");

    /* 4. Terminal audio block (block 64) is an anchor: drift is identically zero. */
    CHECK((AV_AUDIO_BLOCKS - 1) % AV_AUDIO_ANCHOR == 0,
          "psmf first-principles: terminal audio block is a PTS anchor");
    CHECK(clock == av_audio_pts(AV_AUDIO_BLOCKS - 1),
          "psmf first-principles: terminal audio block has zero drift");

    /* 5. Exhaustive check across 10000 arbitrary anchor points and unanchored offsets. */
    int64_t worst_offset_drift = 0;
    for (int j0 = 0; j0 < 10000; j0++) {
        int64_t anchor_pts = av_audio_pts(j0);
        for (int k = 0; k < AV_AUDIO_ANCHOR; k++) {
            int64_t sim = anchor_pts + (int64_t)k * PSMF_AUDIO_PTS_STEP;
            int64_t target = av_audio_pts(j0 + k);
            int64_t d = llabs(sim - target);
            if (d > worst_offset_drift) worst_offset_drift = d;
        }
    }
    CHECK(worst_offset_drift <= AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT,
          "psmf first-principles: worst-case drift across 10000 anchor spans never exceeds 3 ticks");
}

/* Drive the production scePsmfPlayer end to end over the source-owned A/V stream and
 * assert where each issue #279 acceptance item is actually observable: every decoded
 * picture and audio block classified in every published snapshot, both presentation clocks
 * tracking the authored timeline at the guest getter boundaries, and the A/V separation at
 * those comparable points bounded for the whole run.  Both packet layouts must give the
 * same presentation times: the packed one is where a packet's PTS used to be handed to
 * every unit commencing in it (issue #279). */
static void test_player_av_presentation_timing(int layout) {
    uint32_t size = 0;
    int failures_before = failures;
    uint8_t *image = build_psmf_av(&size, layout);
    if (!image) { CHECK(0, "A/V timing container builds"); return; }
    av_latch_mpeglog();
    s_player_image = image;
    s_player_image_size = size;
    s_av_ckpt_n = 0; s_av_eof_seen = 0;
    s_av_seen_summaries = sr_hle_test_psmf_summary_count();

    MEM_W32(AV_CREATE + 0, 0x08700000u);      /* player read buffer (never dereferenced here) */
    MEM_W32(AV_CREATE + 4, 0x00285800u);      /* the size scePsmfPlayerCreate requires */
    MEM_W32(AV_CREATE + 8, 0x30u);            /* priority inside the accepted range */
    av_write_cstr(AV_PATH, s_player_path);
    MEM_W32(AV_CONFIG + 0, 0x0eu);            /* H.264 video */
    MEM_W32(AV_CONFIG + 4, 0u);               /* video stream 0 */
    MEM_W32(AV_CONFIG + 8, 0x0fu);            /* ATRAC3+ audio */
    MEM_W32(AV_CONFIG + 12, 0u);              /* audio stream 0 */
    MEM_W32(AV_CONFIG + 16, 0u);              /* play mode: play */
    MEM_W32(AV_CONFIG + 20, 0u);              /* play speed */
    MEM_W32(AV_VIDEO + 0, 64u);               /* frameWidth: the stream's own width */
    MEM_W32(AV_VIDEO + 4, GUEST_BUF);

    CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0,
          "psmf-av: the player is created");
    CHECK(guest_mpeg_import(AV_NID_SET_PSMF, AV_PLAYER, AV_PATH, 0, 0, 0) == 0,
          "psmf-av: the source-owned A/V stream is opened");
    CHECK(guest_mpeg_import(AV_NID_START, AV_PLAYER, AV_CONFIG, 0, 0, 0) == 0,
          "psmf-av: playback starts");
    CHECK(guest_mpeg_import(AV_NID_GET_STATUS, AV_PLAYER, 0, 0, 0, 0) == AV_STATUS_PLAYING,
          "psmf-av: the guest sees a playing player");

    /* Warm-up: the reference player reports "not yet" for its first pictures, and the
     * audio getter is gated by the same counter -- nothing is decoded, hence nothing can be
     * delivered, before it expires (the first published line must still conserve). */
    for (int i = 0; i < 2; i++) {
        CHECK(guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0) == AV_ERR_NO_DATA,
              "psmf-av: warm-up pictures report NO_DATA");
        CHECK(guest_mpeg_import(AV_NID_GET_AUDIO, AV_PLAYER, AV_AUDIO, 0, 0, 0) == AV_ERR_NO_DATA,
              "psmf-av: audio stays silent while the player warms up");
    }
    CHECK(guest_mpeg_import(AV_NID_GET_AUDIO, AV_PLAYER, AV_AUDIO, 0, 0, 0) == AV_ERR_NO_DATA,
          "psmf-av: audio is held until the third picture completes warm-up");
    CHECK(guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0) == AV_ERR_NO_DATA,
          "psmf-av: the third warm-up picture still reports NO_DATA");
    av_sample_summaries();

    /* Run: consume media in its own proportion -- one audio block per iteration and
     * pictures at 90/65 per block, which is what keeps the two presentation clocks at
     * comparable media positions instead of drifting apart by getter cadence. */
    int video_out = 0, audio_out = 0, guard;
    for (guard = 0; guard < 4096; guard++) {
        int target = (guard + 1) * AV_PICTURES / AV_AUDIO_BLOCKS -
                     guard * AV_PICTURES / AV_AUDIO_BLOCKS;
        for (int k = 0; k < target; k++) {
            uint32_t v = guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0);
            if (v == 0) {
                CHECK(video_out < AV_PICTURES, "psmf-av: no more pictures than were authored");
                if (video_out < AV_PICTURES) {
                    CHECK((int64_t)MEM_R32(AV_VIDEO + 8) == av_video_pts(video_out),
                          "psmf-av: guest displaypts equals the authored picture time");
                    video_out++;
                }
            } else {
                CHECK(v == AV_ERR_NO_DATA,
                      "psmf-av: the video getter reports NO_DATA or success, nothing else");
            }
        }
        uint32_t a = guest_mpeg_import(AV_NID_GET_AUDIO, AV_PLAYER, AV_AUDIO, 0, 0, 0);
        if (a == 0) {
            audio_out++;
        } else {
            CHECK(a == AV_ERR_NO_DATA,
                  "psmf-av: the audio getter reports NO_DATA or success, nothing else");
        }
        CHECK(guest_mpeg_import(AV_NID_UPDATE, AV_PLAYER, 0, 0, 0, 0) == 0,
              "psmf-av: updating a playing stream keeps succeeding");
        av_sample_summaries();
        if (audio_out >= AV_AUDIO_BLOCKS && s_av_eof_seen) break;
    }
    CHECK(audio_out == AV_AUDIO_BLOCKS,
          "psmf-av: the guest received every authored audio block exactly once");
    CHECK(guard < 4096, "psmf-av: the run terminates at end of stream, not at a guard limit");

    /* End of stream: drain whatever the decoder still holds, then the player reports its
     * end and publishes the terminal counter line. */
    for (int i = 0; i < 64; i++) {
        if (guest_mpeg_import(AV_NID_GET_STATUS, AV_PLAYER, 0, 0, 0, 0) == AV_STATUS_FINISHED)
            break;
        uint32_t v = guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0);
        if (v == 0 && video_out < AV_PICTURES) {
            CHECK((int64_t)MEM_R32(AV_VIDEO + 8) == av_video_pts(video_out),
                  "psmf-av: drained pictures also carry their authored displaypts");
            video_out++;
        }
        CHECK(guest_mpeg_import(AV_NID_GET_AUDIO, AV_PLAYER, AV_AUDIO, 0, 0, 0) == AV_ERR_NO_DATA,
              "psmf-av: no audio block appears after the authored stream ended");
        CHECK(guest_mpeg_import(AV_NID_UPDATE, AV_PLAYER, 0, 0, 0, 0) == 0,
              "psmf-av: the final updates keep succeeding");
        av_sample_summaries();
    }
    CHECK(guest_mpeg_import(AV_NID_GET_STATUS, AV_PLAYER, 0, 0, 0, 0) == AV_STATUS_FINISHED,
          "psmf-av: the player reports its end after the stream is consumed");
    av_sample_summaries();

    /* Terminal snapshot: the last published line is the FINISHED summary. */
    const char *last = sr_hle_test_psmf_last_summary();
    long long asub = 0, adec = 0, aout = 0, ahold = 0, aeos = 0, arej = 0;
    long long vsub = 0, vdec = 0, vout = 0, veos = 0, vrej = 0, vhold = 0;
    long long frames = 0, blocks = 0, eof = 0, failed = 0, vts = 0, ats = 0;
    long long avgap = 0, vlost = 0;
    int have =
        av_log_field(last, " asub=", &asub) && av_log_field(last, " adec=", &adec) &&
        av_log_field(last, " aout=", &aout) && av_log_field(last, " ahold=", &ahold) &&
        av_log_field(last, " aeos=", &aeos) && av_log_field(last, " arej=", &arej) &&
        av_log_field(last, " vsub=", &vsub) && av_log_field(last, " vdec=", &vdec) &&
        av_log_field(last, " vout=", &vout) && av_log_field(last, " vhold=", &vhold) &&
        av_log_field(last, " veos=", &veos) && av_log_field(last, " vrej=", &vrej) &&
        av_log_field(last, " frames=", &frames) &&
        av_log_field(last, " audio_blocks=", &blocks) &&
        av_log_field(last, " eof=", &eof) && av_log_field(last, " failed=", &failed) &&
        av_log_field(last, " vts=", &vts) && av_log_field(last, " ats=", &ats) &&
        av_log_field(last, " avgap=", &avgap) && av_log_field(last, " vlost=", &vlost);
    CHECK(have, "psmf-av: the terminal counter line carries every media field");
    CHECK(sr_hle_test_psmf_summary_count() > 0,
          "psmf-av: SR_MPEGLOG published counter lines during the run");
    if (!have) goto cleanup;

    /* Audio accounting at the terminal production snapshot (#279: audio blocks have
     * equivalent accounting, and the getter's successes are the published counter). */
    CHECK(asub == AV_AUDIO_BLOCKS && adec == AV_AUDIO_BLOCKS,
          "psmf-av: every authored audio block was submitted and decoded exactly once");
    CHECK(aout == AV_AUDIO_BLOCKS && ahold == 0 && aeos == 0 && arej == 0,
          "psmf-av: every decoded audio block was delivered to the guest");
    CHECK((long long)audio_out == aout && (long long)blocks == aout,
          "psmf-av: the published delivery count equals the guest's getter successes");
    CHECK(eof == 1 && failed == 0 && vlost == 0,
          "psmf-av: a clean end of stream with no demuxer failure and no displaced time");
    CHECK(s_av_ckpt_n >= 2, "psmf-av: the run published presentation-boundary samples");
    /* The delivered audio series is bounded at every checkpoint: anchors re-sync the clock,
     * so the integer audio step cannot accumulate across the run. */
    for (int i = 1; i < s_av_ckpt_n; i++) {
        CHECK(s_av_ckpt_ats[i] > s_av_ckpt_ats[i - 1],
              "psmf-av: the published audio presentation series advances monotonically");
    }

    if (sr_h264_backend_available()) {
        CHECK(video_out == AV_PICTURES && (long long)frames == AV_PICTURES,
              "psmf-av: every authored picture reached the guest display buffer");
        CHECK(vsub == AV_PICTURES && vdec == AV_PICTURES,
              "psmf-av: every submitted picture was decoded");
        CHECK(vout + veos + vrej == vdec && vhold == 0,
              "psmf-av: every decoded picture is delivered, drained, or rejected -- never lost");
        CHECK(vts == av_video_pts(AV_PICTURES - 1),
              "psmf-av: the terminal displaypts is the last authored picture time");
        CHECK(llabs(avgap - (av_video_pts(AV_PICTURES - 1) - av_audio_pts(AV_AUDIO_BLOCKS - 1))) <=
                  AV_AUDIO_PTS_DRIFT_TICKS,
              "psmf-av: the terminal A/V gap equals the authored interleave of the two tracks");
        CHECK(llabs(avgap - (av_video_pts(AV_PICTURES - 1) - av_audio_pts(AV_AUDIO_BLOCKS - 1))) <=
                  AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT,
              "psmf-av: terminal A/V gap stays within theoretical 3-tick bound");
    } else {
        fprintf(stderr, "SKIP: guest video presentation assertions need an H.264 backend\n");
        CHECK(vsub == 0 && (long long)frames == 0 && vts == 0,
              "psmf-av: without a backend no picture is submitted, delivered, or timed");
        CHECK(ats == av_audio_pts(AV_AUDIO_BLOCKS - 1) ||
                  llabs(ats - av_audio_pts(AV_AUDIO_BLOCKS - 1)) <= AV_AUDIO_PTS_DRIFT_TICKS,
              "psmf-av: the terminal audio presentation pts is the last authored block time");
        CHECK(ats == av_audio_pts(AV_AUDIO_BLOCKS - 1) ||
                  llabs(ats - av_audio_pts(AV_AUDIO_BLOCKS - 1)) <= AV_AUDIO_PTS_THEORETICAL_MAX_DRIFT,
              "psmf-av: terminal audio pts stays within theoretical 3-tick bound");
    }

cleanup:
    CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0,
          "psmf-av: the player is deleted");
    s_player_image = NULL;
    s_player_image_size = 0;
    free(image);
    if (failures != failures_before)
        fprintf(stderr, "FAIL: psmf-av: %d failed checks in the %s packet layout\n",
                failures - failures_before, layout == AV_LAYOUT_PACKED ? "packed" : "split");
}

/* ---- A/V offset at the host presentation boundaries (issue #279) -------------------------
 *
 * The tests above stop at the guest getters.  These drive the same synthetic PSMF fixture
 * through the production getters, then present every delivered picture with the production
 * sceDisplaySetFrameBuf handler (immediate and VBLANK-latched flips) and play every
 * delivered block with the production sceAudioOutput handlers, and assert what the
 * SR_MPEGAV measurement reports.  The fixture has no running scheduler and no host mixer, so
 * the guest clock and the host queue lead are injected through the test seam; every step
 * between a guest call and the recorded offset is production code.
 *
 * The clock is authored from the fixture's own presentation times: a picture with time P
 * is presented at VBASE + P, a block with time P is submitted at ABASE + P with a queue lead
 * of 2048 frames ahead of it, so the expected offsets are known constants and a stream that
 * ran slow shows up as a changing A/V offset. */
void sr_hle_test_psmf_av_reset(void);
void sr_hle_test_psmf_av_enable(int on);
void sr_hle_test_psmf_av_set_window_us(int64_t us);
void sr_hle_test_psmf_av_set_clock_us(int64_t us);
void sr_hle_test_psmf_av_set_queue_frames(int frames);
const char *sr_hle_test_psmf_av_last_window(void);
const char *sr_hle_test_psmf_av_last_final(void);
unsigned sr_hle_test_psmf_av_window_lines(void);
unsigned sr_hle_test_psmf_av_final_lines(void);
int64_t sr_hle_test_psmf_av_counter(int audio, const char *key);
void sr_hle_test_psmf_av_report(void);
void sr_vblank_tick(void);

#define PB_NID_SET_FRAMEBUF   0x289d82feu
#define PB_NID_CH_RESERVE     0x5ec81c55u
#define PB_NID_CH_RELEASE     0x6fc46853u
#define PB_NID_OUTPUT_BLOCK   0x136caf51u
#define PB_NID_OUT2_RESERVE   0x01562ba3u
#define PB_NID_OUT2_BLOCK     0x2d53f36eu
#define PB_NID_OUT2_RELEASE   0x43196845u
#define PB_STRIDE 512
#define PB_FMT 3                          /* 8888 */
#define PB_FB_A     0x08440000u           /* two framebuffers and one never delivered */
#define PB_FB_B     0x084d0000u
#define PB_FB_NEVER 0x08560000u
#define PB_AU_A     0x08620000u           /* two 8192-byte audio sinks and one never delivered */
#define PB_AU_B     0x08622000u
#define PB_AU_NEVER 0x08624000u
#define PB_FRAMES   2048
#define PB_LEAD_US  46439                 /* 2048 frames at 44.1 kHz, truncated */
#define PB_VBASE_US 100000
#define PB_ABASE_US 20000
#define PB_VLAG_US  5000                  /* delivery precedes presentation by this much */
#define PB_ALAG_US  7000
#define PB_SKIP_VIDEO 40                  /* never presented: overwritten by picture 42 */
#define PB_SKIP_AUDIO 30                  /* never played: overwritten by block 32 */
#define PB_VOFF_US  PB_VBASE_US
#define PB_AOFF_US  (PB_ABASE_US + PB_LEAD_US)
#define PB_AV_US    (PB_VOFF_US - PB_AOFF_US)
#define PB_AUDIO_TOL_US 36                /* 3 ticks of anchor extrapolation, plus rounding */

typedef struct {
    int enable;
    int lead_frames;        /* injected host queue lead; -1 = no host queue */
    int stretch_ppm;        /* audio plays this much slower than its presentation times */
    int layout;
    int output2;            /* sceAudioOutput2OutputBlocking instead of a regular channel */
} PbScenario;

static struct {
    unsigned seen_lines;
    int nav;
    long long av[64];
    int video_out, audio_out, channel;
} pb;

static int64_t pb_us(int64_t ticks) { return ticks * 100 / 9; }
static uint32_t pb_video_buf(int idx) { return (idx & 1) ? PB_FB_B : PB_FB_A; }
static uint32_t pb_audio_buf(int idx) { return (idx & 1) ? PB_AU_B : PB_AU_A; }
static int pb_is_na(const char *line, const char *key) {
    const char *p = line ? strstr(line, key) : NULL;
    return p && p[strlen(key)] == 'n' && p[strlen(key) + 1] == 'a';
}

/* Every closed window is checked as it is published, so no window escapes the bounds. */
static void pb_check_new_windows(const PbScenario *sc) {
    unsigned lines = sr_hle_test_psmf_av_window_lines();
    if (lines == pb.seen_lines) return;
    pb.seen_lines = lines;
    const char *w = sr_hle_test_psmf_av_last_window();
    long long vn = 0, an = 0, vo = 0, ao = 0, av = 0;
    int have = av_log_field(w, " vn=", &vn) && av_log_field(w, " an=", &an);
    CHECK(have, "psmf-present: a window line carries its sample counts");
    if (!have) return;
    if (vn > 0 && !pb_is_na(w, " voff_us="))
        if (av_log_field(w, " voff_us=", &vo) && sc->stretch_ppm == 0)
            CHECK(llabs(vo - PB_VOFF_US) <= 1,
                  "psmf-present: a window's video offset equals the clock authored from its pts");
    if (an > 0 && sc->lead_frames >= 0 && !pb_is_na(w, " aoff_us=")) {
        CHECK(av_log_field(w, " aoff_us=", &ao), "psmf-present: a window carries its audio offset");
        if (sc->stretch_ppm == 0)
            CHECK(llabs(ao - PB_AOFF_US) <= PB_AUDIO_TOL_US,
                  "psmf-present: a window's audio offset equals submit time plus queue lead minus pts");
    }
    if (sc->lead_frames < 0) {
        CHECK(an == 0 && pb_is_na(w, " aoff_us=") && pb_is_na(w, " av_us="),
              "psmf-present: without a host queue the audio offset and the A/V offset are not measured");
    } else if (vn > 0 && an > 0) {
        CHECK(av_log_field(w, " av_us=", &av), "psmf-present: a paired window carries an A/V offset");
        if (sc->stretch_ppm == 0)
            CHECK(llabs(av - PB_AV_US) <= PB_AUDIO_TOL_US + 1,
                  "psmf-present: a window's A/V offset equals the authored video minus audio offset");
        if (pb.nav < (int)(sizeof(pb.av) / sizeof(pb.av[0]))) pb.av[pb.nav++] = av;
    }
}

static void pb_video_step(const PbScenario *sc) {
    int idx = pb.video_out;
    if (idx >= AV_PICTURES) idx = AV_PICTURES - 1;
    int64_t t = PB_VBASE_US + pb_us(av_video_pts(idx));
    sr_hle_test_psmf_av_set_clock_us(t - PB_VLAG_US);
    MEM_W32(AV_VIDEO + 0, PB_STRIDE);
    MEM_W32(AV_VIDEO + 4, pb_video_buf(pb.video_out));
    uint32_t v = guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0);
    if (v != 0) {
        CHECK(v == AV_ERR_NO_DATA, "psmf-present: the video getter reports NO_DATA or success");
        return;
    }
    CHECK(pb.video_out < AV_PICTURES, "psmf-present: no more pictures than were authored");
    if (pb.video_out >= AV_PICTURES) return;
    CHECK((int64_t)MEM_R32(AV_VIDEO + 8) == av_video_pts(pb.video_out),
          "psmf-present: guest displaypts equals the authored picture time");
    int shown = pb.video_out;
    pb.video_out++;
    if (shown == PB_SKIP_VIDEO || shown == AV_PICTURES - 1) return;   /* delivered, never presented */
    sr_hle_test_psmf_av_set_clock_us(t);
    int latched = shown & 1;       /* odd pictures take the VBLANK-latched flip */
    CHECK(guest_mpeg_import(PB_NID_SET_FRAMEBUF, pb_video_buf(shown), PB_STRIDE, PB_FMT,
                            latched ? 1u : 0u, 0) == 0,
          "psmf-present: the production display handler accepts the flip");
    if (latched) sr_vblank_tick();
    pb_check_new_windows(sc);
}

static void pb_audio_step(const PbScenario *sc) {
    int idx = pb.audio_out;
    if (idx >= AV_AUDIO_BLOCKS) idx = AV_AUDIO_BLOCKS - 1;
    int64_t pts_us = pb_us(av_audio_pts(idx));
    int64_t t = PB_ABASE_US + pts_us + pts_us * sc->stretch_ppm / 1000000;
    sr_hle_test_psmf_av_set_clock_us(t - PB_ALAG_US);
    uint32_t a = guest_mpeg_import(AV_NID_GET_AUDIO, AV_PLAYER, pb_audio_buf(pb.audio_out), 0, 0, 0);
    if (a != 0) {
        CHECK(a == AV_ERR_NO_DATA, "psmf-present: the audio getter reports NO_DATA or success");
        return;
    }
    int played = pb.audio_out;
    pb.audio_out++;
    if (played == PB_SKIP_AUDIO || played == AV_AUDIO_BLOCKS - 1) return;   /* delivered, never played */
    sr_hle_test_psmf_av_set_clock_us(t);
    uint32_t r = sc->output2
        ? guest_mpeg_import(PB_NID_OUT2_BLOCK, 0x8000u, pb_audio_buf(played), 0, 0, 0)
        : guest_mpeg_import(PB_NID_OUTPUT_BLOCK, (uint32_t)pb.channel, 0x8000u,
                            pb_audio_buf(played), 0, 0);
    CHECK(sc->output2 ? r == 0u : r == (uint32_t)PB_FRAMES,
          "psmf-present: the production audio output handler accepts the block");
    pb_check_new_windows(sc);
}

static int pb_counter_is(int audio, const char *key, long long want) {
    return sr_hle_test_psmf_av_counter(audio, key) == want;
}

static void pb_run(const PbScenario *sc, const char *name) {
    uint32_t size = 0;
    int failures_before = failures;
    uint8_t *image = build_psmf_av(&size, sc->layout);
    if (!image) { CHECK(0, "A/V presentation container builds"); return; }
    const int video = sr_h264_backend_available();
    s_player_image = image;
    s_player_image_size = size;
    memset(&pb, 0, sizeof(pb));
    sr_hle_test_psmf_av_reset();
    sr_hle_test_psmf_av_enable(sc->enable);
    sr_hle_test_psmf_av_set_window_us(1000000);
    sr_hle_test_psmf_av_set_clock_us(0);
    sr_hle_test_psmf_av_set_queue_frames(sc->lead_frames);

    lc_prepare_guest();
    CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0,
          "psmf-present: the player is created");
    CHECK(guest_mpeg_import(AV_NID_SET_PSMF, AV_PLAYER, AV_PATH, 0, 0, 0) == 0,
          "psmf-present: the source-owned A/V stream is opened");
    CHECK(guest_mpeg_import(AV_NID_START, AV_PLAYER, AV_CONFIG, 0, 0, 0) == 0,
          "psmf-present: playback starts");
    if (sc->output2) {
        CHECK(guest_mpeg_import(PB_NID_OUT2_RESERVE, PB_FRAMES, 0, 0, 0, 0) == 0,
              "psmf-present: the Output2 channel is reserved");
    } else {
        pb.channel = (int)guest_mpeg_import(PB_NID_CH_RESERVE, 0xffffffffu, PB_FRAMES, 0u, 0, 0);
        CHECK(pb.channel >= 0 && pb.channel < 8, "psmf-present: a regular audio channel is reserved");
    }
    CHECK(guest_mpeg_import(PB_NID_SET_FRAMEBUF, 0u, PB_STRIDE, PB_FMT, 1u, 0) == 0,
          "psmf-present: the display mode is latched");

    /* The three warm-up pictures the getter test also consumes (audio is held until the third
     * completes), then media in its own proportion. */
    for (int i = 0; i < 3; i++)
        CHECK(guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0) == AV_ERR_NO_DATA,
              "psmf-present: warm-up pictures report NO_DATA");
    int guard;
    for (guard = 0; guard < 4096; guard++) {
        int target = (guard + 1) * AV_PICTURES / AV_AUDIO_BLOCKS - guard * AV_PICTURES / AV_AUDIO_BLOCKS;
        for (int k = 0; k < target; k++) pb_video_step(sc);
        pb_audio_step(sc);
        CHECK(guest_mpeg_import(AV_NID_UPDATE, AV_PLAYER, 0, 0, 0, 0) == 0,
              "psmf-present: updating a playing stream keeps succeeding");
        if (pb.audio_out >= AV_AUDIO_BLOCKS && (!video || pb.video_out >= AV_PICTURES - 4)) break;
    }
    for (int i = 0; i < 64 && video && pb.video_out < AV_PICTURES; i++) {
        pb_video_step(sc);
        (void)guest_mpeg_import(AV_NID_UPDATE, AV_PLAYER, 0, 0, 0, 0);
    }
    CHECK(pb.audio_out == AV_AUDIO_BLOCKS, "psmf-present: the guest received every authored audio block");
    CHECK(!video || pb.video_out == AV_PICTURES, "psmf-present: the guest received every authored picture");

    /* A buffer presented or played that was never delivered stays unmatched, and a buffer
     * that was already matched is not matched twice. */
    if (sc->enable) {
        int64_t v_match = sr_hle_test_psmf_av_counter(0, "matched");
        int64_t v_pend = sr_hle_test_psmf_av_counter(0, "pending");
        int64_t v_hits = sr_hle_test_psmf_av_counter(0, "hits");
        int64_t v_bnd = sr_hle_test_psmf_av_counter(0, "boundary");
        int64_t a_match = sr_hle_test_psmf_av_counter(1, "matched");
        int64_t a_unmeas = sr_hle_test_psmf_av_counter(1, "unmeasured");
        int64_t a_pend = sr_hle_test_psmf_av_counter(1, "pending");
        int64_t a_hits = sr_hle_test_psmf_av_counter(1, "hits");
        int64_t a_bnd = sr_hle_test_psmf_av_counter(1, "boundary");
        sr_hle_test_psmf_av_set_clock_us(9000000);
        CHECK(guest_mpeg_import(PB_NID_SET_FRAMEBUF, PB_FB_NEVER, PB_STRIDE, PB_FMT, 0u, 0) == 0,
              "psmf-present: a never-delivered buffer can be presented");
        CHECK(guest_mpeg_import(PB_NID_SET_FRAMEBUF, PB_FB_A, PB_STRIDE, PB_FMT, 0u, 0) == 0,
              "psmf-present: an already-presented buffer can be presented again");
        CHECK(pb_counter_is(0, "matched", v_match) && pb_counter_is(0, "pending", v_pend) &&
                  pb_counter_is(0, "hits", v_hits) && pb_counter_is(0, "boundary", v_bnd + 2),
              "psmf-present: presenting an undelivered or an already-matched buffer matches nothing");
        uint32_t r = sc->output2
            ? guest_mpeg_import(PB_NID_OUT2_BLOCK, 0x8000u, PB_AU_NEVER, 0, 0, 0)
            : guest_mpeg_import(PB_NID_OUTPUT_BLOCK, (uint32_t)pb.channel, 0x8000u, PB_AU_NEVER, 0, 0);
        (void)r;
        r = sc->output2
            ? guest_mpeg_import(PB_NID_OUT2_BLOCK, 0x8000u, PB_AU_B, 0, 0, 0)
            : guest_mpeg_import(PB_NID_OUTPUT_BLOCK, (uint32_t)pb.channel, 0x8000u, PB_AU_B, 0, 0);
        (void)r;
        CHECK(pb_counter_is(1, "matched", a_match) && pb_counter_is(1, "unmeasured", a_unmeas) &&
                  pb_counter_is(1, "pending", a_pend) && pb_counter_is(1, "hits", a_hits) &&
                  pb_counter_is(1, "boundary", a_bnd + 2),
              "psmf-present: playing an undelivered or an already-matched buffer matches nothing");
        /* The deliveries that were never presented or played are counted, not hidden. */
        CHECK(pb_counter_is(0, "superseded", video ? 1 : 0) && pb_counter_is(0, "pending", video ? 1 : 0),
              "psmf-present: a picture overwritten, and one never presented, are counted unmatched");
        CHECK(pb_counter_is(1, "superseded", 1) && pb_counter_is(1, "pending", 1),
              "psmf-present: a block overwritten, and one never played, are counted unmatched");
    } else {
        CHECK(pb_counter_is(0, "delivered", 0) && pb_counter_is(1, "delivered", 0) &&
                  pb_counter_is(0, "boundary", 0) && pb_counter_is(1, "boundary", 0),
              "psmf-present: a disabled measurement records nothing");
    }

    unsigned finals_before = sr_hle_test_psmf_av_final_lines();
    CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0,
          "psmf-present: the player is deleted");
    pb_check_new_windows(sc);
    if (sc->output2) (void)guest_mpeg_import(PB_NID_OUT2_RELEASE, 0, 0, 0, 0, 0);
    else (void)guest_mpeg_import(PB_NID_CH_RELEASE, (uint32_t)pb.channel, 0, 0, 0, 0);

    if (!sc->enable) {
        CHECK(sr_hle_test_psmf_av_final_lines() == finals_before && sr_hle_test_psmf_av_window_lines() == 0,
              "psmf-present: a disabled measurement prints no window and no summary");
        goto done;
    }
    CHECK(sr_hle_test_psmf_av_final_lines() == finals_before + 1u,
          "psmf-present: deleting the player publishes the final summary once");
    const char *f = sr_hle_test_psmf_av_last_final();
    long long vdel = 0, vmatch = 0, vunmeas = 0, vsuper = 0, vevict = 0, vnospan = 0, vpend = 0, vbnd = 0, vhit = 0;
    long long adel = 0, amatch = 0, aunmeas = 0, asuper = 0, aevict = 0, anospan = 0, apend = 0, abnd = 0, ahit = 0;
    long long windows = 0, paired = 0, drift = 0, avmin = 0, avmax = 0, avmean = 0, vlat = 0, alat = 0, vlatmax = 0;
    int have =
        av_log_field(f, " vdel=", &vdel) && av_log_field(f, " vmatch=", &vmatch) &&
        av_log_field(f, " vunmeas=", &vunmeas) && av_log_field(f, " vsuper=", &vsuper) &&
        av_log_field(f, " vevict=", &vevict) && av_log_field(f, " vnospan=", &vnospan) &&
        av_log_field(f, " vpend=", &vpend) && av_log_field(f, " vbnd=", &vbnd) &&
        av_log_field(f, " vhit=", &vhit) && av_log_field(f, " adel=", &adel) &&
        av_log_field(f, " amatch=", &amatch) && av_log_field(f, " aunmeas=", &aunmeas) &&
        av_log_field(f, " asuper=", &asuper) && av_log_field(f, " aevict=", &aevict) &&
        av_log_field(f, " anospan=", &anospan) && av_log_field(f, " apend=", &apend) &&
        av_log_field(f, " abnd=", &abnd) && av_log_field(f, " ahit=", &ahit) &&
        av_log_field(f, " windows=", &windows) && av_log_field(f, " paired=", &paired);
    CHECK(have && strstr(f, "reason=player_delete"), "psmf-present: the final summary carries every count");
    if (!have) goto done;

    CHECK(vdel == vmatch + vunmeas + vsuper + vevict + vnospan + vpend,
          "psmf-present: every delivered picture is matched, unmeasured or counted unmatched");
    CHECK(adel == amatch + aunmeas + asuper + aevict + anospan + apend,
          "psmf-present: every delivered block is matched, unmeasured or counted unmatched");
    CHECK(adel == AV_AUDIO_BLOCKS && asuper == 1 && apend == 1 && aevict == 0 && anospan == 0,
          "psmf-present: all 65 blocks delivered; one overwritten and one never played");
    CHECK(abnd - ahit == 2 && ahit == amatch + aunmeas,
          "psmf-present: the undelivered and the repeated submit are the only non-matching submits");
    if (sc->lead_frames >= 0) {
        CHECK(amatch == AV_AUDIO_BLOCKS - 2 && aunmeas == 0, "psmf-present: every played block was matched");
        CHECK(av_log_field(f, " alat_mean_us=", &alat) && alat == PB_ALAG_US + PB_LEAD_US &&
                  av_log_field(f, " alat_max_us=", &vlatmax) && vlatmax == PB_ALAG_US + PB_LEAD_US,
              "psmf-present: block delivery-to-play latency is the clock lag plus the queue lead");
    } else {
        CHECK(amatch == 0 && aunmeas == AV_AUDIO_BLOCKS - 2,
              "psmf-present: with no host queue every played block is unmeasured, none reads as zero lead");
        CHECK(pb_is_na(f, " alat_mean_us=") && pb_is_na(f, " av_mean_us=") && pb_is_na(f, " drift_us="),
              "psmf-present: unmeasured audio leaves the offsets and the drift unmeasured");
    }
    if (video) {
        CHECK(vdel == AV_PICTURES && vsuper == 1 && vpend == 1 && vevict == 0 && vnospan == 0,
              "psmf-present: all 90 pictures delivered; one overwritten and one never presented");
        CHECK(vmatch == AV_PICTURES - 2 && vunmeas == 0, "psmf-present: every presented picture was matched");
        CHECK(vbnd - vhit == 2 && vhit == vmatch,
              "psmf-present: the undelivered and the repeated present are the only non-matching presents");
        CHECK(av_log_field(f, " vlat_mean_us=", &vlat) && vlat == PB_VLAG_US &&
                  av_log_field(f, " vlat_max_us=", &vlatmax) && vlatmax == PB_VLAG_US,
              "psmf-present: picture delivery-to-present latency is the clock lag");
        CHECK(windows >= 3, "psmf-present: a three second run spans several windows");
        if (sc->lead_frames >= 0) {
            CHECK(paired >= 3 && av_log_field(f, " drift_us=", &drift) &&
                      av_log_field(f, " av_min_us=", &avmin) && av_log_field(f, " av_max_us=", &avmax) &&
                      av_log_field(f, " av_mean_us=", &avmean),
                  "psmf-present: the summary carries min, max, mean and drift of the A/V offset");
            if (sc->stretch_ppm == 0) {
                CHECK(llabs(avmin - PB_AV_US) <= PB_AUDIO_TOL_US + 1 && llabs(avmax - PB_AV_US) <= PB_AUDIO_TOL_US + 1 &&
                          llabs(avmean - PB_AV_US) <= PB_AUDIO_TOL_US + 1,
                      "psmf-present: the A/V offset equals the authored interleave at the host boundaries");
                CHECK(llabs(drift) <= 2 * PB_AUDIO_TOL_US,
                      "psmf-present: the A/V offset does not drift across the run");
            } else {
                /* Positive control: audio playing 1% slow must be seen as a falling A/V offset. */
                CHECK(drift < -10000, "psmf-present: a slow audio clock is reported as negative drift");
                int monotone = pb.nav >= 3;
                for (int i = 1; i < pb.nav; i++) if (pb.av[i] >= pb.av[i - 1]) monotone = 0;
                CHECK(monotone, "psmf-present: the A/V offset falls window after window under a slow audio clock");
            }
        }
    } else {
        fprintf(stderr, "SKIP: picture presentation assertions need an H.264 backend\n");
        CHECK(vdel == 0 && vmatch == 0, "psmf-present: without a backend no picture is delivered or matched");
    }
done:
    s_player_image = NULL;
    s_player_image_size = 0;
    free(image);
    if (failures != failures_before)
        fprintf(stderr, "FAIL: psmf-present: %d failed checks in scenario %s\n", failures - failures_before, name);
}

/* The fixture plays no sound: the null audio backend keeps the production output handlers
 * (and their pacing) off a real device, and reports "no host queue" for the pacing path. */
static char s_pb_audio_env[] = "SR_AUDIO_BACKEND=null";
static void test_player_av_presentation_boundary(void) {
    if (!getenv("SR_AUDIO_BACKEND")) {
#ifdef _WIN32
        _putenv(s_pb_audio_env);
#else
        putenv(s_pb_audio_env);
#endif
    }
    PbScenario in_step = { 1, PB_FRAMES, 0, AV_LAYOUT_SPLIT, 0 };
    pb_run(&in_step, "in-step regular channel");
    PbScenario packed = { 1, PB_FRAMES, 0, AV_LAYOUT_PACKED, 1 };
    pb_run(&packed, "in-step packed layout, Output2");
    PbScenario slow = { 1, PB_FRAMES, 10000, AV_LAYOUT_SPLIT, 0 };
    pb_run(&slow, "audio 1% slow");
    PbScenario no_queue = { 1, -1, 0, AV_LAYOUT_SPLIT, 0 };
    pb_run(&no_queue, "no host queue");
    PbScenario disabled = { 0, PB_FRAMES, 0, AV_LAYOUT_SPLIT, 0 };
    pb_run(&disabled, "disabled");
    sr_hle_test_psmf_av_reset();
    sr_hle_test_psmf_av_enable(0);   /* later tests record nothing */
}

/* A title that composites the movie (#279): it receives each picture in a texture buffer,
 * draws it through the GE into a framebuffer and presents that framebuffer, so the picture's
 * own buffer is never flipped.  The production GE hook (sr_ge_texture_sample_hook, installed
 * by the measurement at the first picture) carries each textured draw's texture and render
 * target; the first present of that target is the picture's presentation time.  Each matched
 * picture is presented PC_LAG_US after its delivery. */
#define PC_TEX      0x08700000u      /* 512-wide 8888 texture the pictures are delivered into */
#define PC_TEX_MISS 0x08780000u      /* a texture no picture was delivered into */
#define PC_LAG_US   10000
typedef void (*PcTextureHook)(uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t);
extern PcTextureHook sr_ge_texture_sample_hook;

static int pc_next_picture(int64_t clock_us) {
    sr_hle_test_psmf_av_set_clock_us(clock_us);
    for (int tries = 0; tries < 64; tries++) {
        MEM_W32(AV_VIDEO + 0, PB_STRIDE);
        MEM_W32(AV_VIDEO + 4, PC_TEX);
        uint32_t v = guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0);
        if (v == 0) return 1;
        if (v != AV_ERR_NO_DATA) return 0;
        (void)guest_mpeg_import(AV_NID_GET_AUDIO, AV_PLAYER, AV_AUDIO, 0, 0, 0);
        (void)guest_mpeg_import(AV_NID_UPDATE, AV_PLAYER, 0, 0, 0, 0);
    }
    return 0;
}

static void pc_draw(uint32_t tex, uint32_t target) {
    if (sr_ge_texture_sample_hook)
        sr_ge_texture_sample_hook(tex, PB_STRIDE, 512u, PB_FMT, target, PB_STRIDE, PB_FMT);
}

static void pc_flip(uint32_t target, int64_t clock_us) {
    sr_hle_test_psmf_av_set_clock_us(clock_us);
    CHECK(guest_mpeg_import(PB_NID_SET_FRAMEBUF, target, PB_STRIDE, PB_FMT, 0u, 0) == 0,
          "psmf-composite: the production display handler accepts the flip");
}

static void test_player_av_composited_presentation(void) {
    if (!sr_h264_backend_available()) {
        fprintf(stderr, "SKIP: composited presentation assertions need an H.264 backend\n");
        return;
    }
    uint32_t size = 0;
    uint8_t *image = build_psmf_av(&size, AV_LAYOUT_SPLIT);
    if (!image) { CHECK(0, "psmf-composite: the A/V container builds"); return; }
    s_player_image = image;
    s_player_image_size = size;
    sr_hle_test_psmf_av_reset();
    sr_hle_test_psmf_av_enable(1);
    sr_hle_test_psmf_av_set_window_us(1000000);
    sr_hle_test_psmf_av_set_clock_us(0);
    sr_hle_test_psmf_av_set_queue_frames(PB_FRAMES);
    sr_ge_texture_sample_hook = NULL;   /* an earlier measurement may have installed it */
    lc_prepare_guest();
    CHECK(guest_mpeg_import(AV_NID_CREATE, AV_PLAYER, AV_CREATE, 0, 0, 0) == 0 &&
              guest_mpeg_import(AV_NID_SET_PSMF, AV_PLAYER, AV_PATH, 0, 0, 0) == 0 &&
              guest_mpeg_import(AV_NID_START, AV_PLAYER, AV_CONFIG, 0, 0, 0) == 0,
          "psmf-composite: the player is created, opened and started");
    CHECK(guest_mpeg_import(PB_NID_SET_FRAMEBUF, 0u, PB_STRIDE, PB_FMT, 1u, 0) == 0,
          "psmf-composite: the display mode is latched");
    for (int i = 0; i < 3; i++)
        CHECK(guest_mpeg_import(AV_NID_GET_VIDEO, AV_PLAYER, AV_VIDEO, 0, 0, 0) == AV_ERR_NO_DATA,
              "psmf-composite: warm-up pictures report NO_DATA");

    /* Picture 1 is drawn into framebuffer A, which is then presented. */
    int64_t t = 1000000;
    CHECK(pc_next_picture(t), "psmf-composite: picture 1 is delivered into the texture");
    CHECK(sr_ge_texture_sample_hook != NULL,
          "psmf-composite: the measurement installs the GE texture hook at the first picture");
    pc_draw(PC_TEX_MISS, PB_FB_A);
    CHECK(pb_counter_is(0, "composited", 0),
          "psmf-composite: a draw from another texture composites nothing");
    pc_draw(PC_TEX, PB_FB_A);
    CHECK(pb_counter_is(0, "composited", 1) && pb_counter_is(0, "matched", 0),
          "psmf-composite: a draw from the picture's texture composites it, unmatched until the flip");
    pc_flip(PB_FB_A, t + PC_LAG_US);
    CHECK(pb_counter_is(0, "matched", 1) && pb_counter_is(0, "composited_matched", 1),
          "psmf-composite: the flip of the draw's render target presents the composited picture");

    /* Picture 2 is never drawn: the flip of A does not present it, and picture 3, delivered
     * into the same texture, supersedes it. Picture 3 is drawn into B, so only B's flip
     * presents it. */
    t += 100000;
    CHECK(pc_next_picture(t), "psmf-composite: picture 2 is delivered");
    pc_flip(PB_FB_A, t + PC_LAG_US);
    CHECK(pb_counter_is(0, "matched", 1) && pb_counter_is(0, "pending", 1),
          "psmf-composite: a flip does not present a picture that was never drawn");
    t += 100000;
    CHECK(pc_next_picture(t), "psmf-composite: picture 3 is delivered");
    CHECK(pb_counter_is(0, "superseded", 1),
          "psmf-composite: a picture overwritten before any draw is counted superseded");
    pc_draw(PC_TEX, PB_FB_B);
    pc_flip(PB_FB_A, t + PC_LAG_US / 2);
    CHECK(pb_counter_is(0, "matched", 1),
          "psmf-composite: the flip of another framebuffer does not present the composited picture");
    pc_flip(PB_FB_B, t + PC_LAG_US);
    CHECK(pb_counter_is(0, "matched", 2) && pb_counter_is(0, "composited_matched", 2),
          "psmf-composite: the flip of its render target presents the composited picture");

    /* Picture 4 is drawn into A; picture 5 lands in the texture before A is presented. The
     * drawn picture 4 is not superseded, and A's flip presents picture 4, not 5. */
    t += 100000;
    CHECK(pc_next_picture(t), "psmf-composite: picture 4 is delivered");
    pc_draw(PC_TEX, PB_FB_A);
    CHECK(pc_next_picture(t + PC_LAG_US / 2), "psmf-composite: picture 5 is delivered");
    CHECK(pb_counter_is(0, "superseded", 1),
          "psmf-composite: a delivery into the texture does not supersede a picture already drawn");
    pc_flip(PB_FB_A, t + PC_LAG_US);
    CHECK(pb_counter_is(0, "matched", 3) && pb_counter_is(0, "composited_matched", 3) &&
              pb_counter_is(0, "pending", 1),
          "psmf-composite: the flip presents the drawn picture and leaves the undrawn one pending");

    unsigned finals_before = sr_hle_test_psmf_av_final_lines();
    CHECK(guest_mpeg_import(AV_NID_DELETE, AV_PLAYER, 0, 0, 0, 0) == 0,
          "psmf-composite: the player is deleted");
    const char *f = sr_hle_test_psmf_av_last_final();
    long long vdel = 0, vmatch = 0, vsuper = 0, vpend = 0, vcomp = 0, vcompmatch = 0, vlat = 0, vlatmax = 0;
    CHECK(sr_hle_test_psmf_av_final_lines() == finals_before + 1u &&
              av_log_field(f, " vdel=", &vdel) && av_log_field(f, " vmatch=", &vmatch) &&
              av_log_field(f, " vsuper=", &vsuper) && av_log_field(f, " vpend=", &vpend) &&
              av_log_field(f, " vcomp=", &vcomp) && av_log_field(f, " vcompmatch=", &vcompmatch) &&
              vdel == 5 && vmatch == 3 && vsuper == 1 && vpend == 1 && vcomp == 3 && vcompmatch == 3,
          "psmf-composite: the final summary counts 5 delivered, 3 composited and presented, 1 superseded, 1 pending");
    CHECK(av_log_field(f, " vlat_mean_us=", &vlat) && vlat == PC_LAG_US &&
              av_log_field(f, " vlat_max_us=", &vlatmax) && vlatmax == PC_LAG_US,
          "psmf-composite: a composited picture's delivery-to-present latency is measured at its flip");

    s_player_image = NULL;
    s_player_image_size = 0;
    free(image);
    sr_hle_test_psmf_av_reset();
    sr_hle_test_psmf_av_enable(0);
}

/* sceMpegAvcDecodeDetail (an import ten library titles stop at): through the production HLE
 * dispatch it writes exactly the 13 words the PSP writes -- 0, pictures decoded, frame width and
 * height from the PSMF header, four zero crop words, the last decode's frame status, four more
 * words (zero here) -- and
 * refuses an invalid pointer or an unknown handle. */
#define DD_NID 0x0f6c18d7u
static void test_mpeg_avc_decode_detail(void) {
    enum {
        DD_DESC = 0x08650000u, DD_DATA = 0x08660000u, DD_HDR = 0x08670000u, DD_OFF = 0x08671000u,
        DD_DETAIL = 0x08672000u, DD_UNKNOWN = 0x08674000u,
    };
    uint32_t size = 0;
    uint8_t *image = build_psmf_av(&size, AV_LAYOUT_SPLIT);
    if (!image) { CHECK(0, "decode-detail: the A/V container builds"); return; }
    memcpy(SR_HOST(DD_HDR), image, 2048u);
    memcpy(SR_HOST(DD_HDR + 4u), "0015", 4u);
    free(image);
    MEM_W32(DD_DESC, 0u);
    CHECK(mpeg_create(DD_DESC, DD_DATA, 0x10000u, 0u, 512u, 0u, 0u) == 0u &&
              mpeg_query_stream_offset(DD_DESC, DD_HDR, DD_OFF) == 0u,
          "decode-detail: a context analyses the header");
    memset(SR_HOST(DD_DETAIL), 0xa5, 64u);
    CHECK(guest_mpeg_import(DD_NID, DD_DESC, DD_DETAIL, 0, 0, 0) == 0u,
          "decode-detail: the import has a handler and succeeds");
    CHECK(MEM_R32(DD_DETAIL + 0u) == 0u && MEM_R32(DD_DETAIL + 4u) == 0u &&
              MEM_R32(DD_DETAIL + 8u) == FIX_W_MBS * 16u && MEM_R32(DD_DETAIL + 12u) == FIX_H_MBS * 16u &&
              guest_bytes_are(DD_DETAIL + 16u, 16u, 0x00) && MEM_R32(DD_DETAIL + 32u) == 0u &&
              guest_bytes_are(DD_DETAIL + 36u, 16u, 0x00) && guest_bytes_are(DD_DETAIL + 52u, 12u, 0xa5),
          "decode-detail: the 13 measured words before any decode, nothing past them");
    Mpeg *ctx = mpeg_find(DD_DESC);
    if (ctx) { ctx->h264Frames = 2; ctx->avcFrameStatus = 1; }
    CHECK(guest_mpeg_import(DD_NID, DD_DESC, DD_DETAIL, 0, 0, 0) == 0u &&
              MEM_R32(DD_DETAIL + 4u) == 2u && MEM_R32(DD_DETAIL + 32u) == 1u,
          "decode-detail: the picture count and the last decode's frame status");
    CHECK(guest_mpeg_import(DD_NID, DD_DESC, 0u, 0, 0, 0) == (uint32_t)-1 &&
              guest_mpeg_import(DD_NID, DD_DESC, DD_DETAIL + 2u, 0, 0, 0) == (uint32_t)-1 &&
              guest_mpeg_import(DD_NID, DD_UNKNOWN, DD_DETAIL, 0, 0, 0) == (uint32_t)-1,
          "decode-detail: a null or misaligned pointer and an unknown handle are refused");
    CHECK(mpeg_delete(DD_DESC) == 0u, "decode-detail: the context is deleted");
}

/* The sceMpeg ATRAC path a guest PSMF player drives (#286): the registered ATRAC3+ stream is
 * demultiplexed from the ring packets, GetAtracAu hands out one frame per call, and AtracDecode
 * writes exactly what the ATRAC3+ decoder produces for that frame.  Before any data, and after
 * the last frame, GetAtracAu reports NO_DATA; AtracDecode with no held frame refuses and leaves
 * the block untouched.  A flush restarts the stream. */
static void test_mpeg_atrac_au_decode(void) {
    enum {
        AT_DESC = 0x08600000u, AT_DATA = 0x08610000u, AT_RING = 0x08630000u, AT_HDR = 0x08640000u,
        AT_AU = 0x08641000u, AT_OUT = 0x08642000u, AT_ATTR = 0x08644000u, AT_OFF = 0x08644010u,
        AT_RING_DATA = 0x08680000u,
    };
    uint32_t size = 0;
    uint8_t *image = build_psmf_av(&size, AV_LAYOUT_SPLIT);
    if (!image) { CHECK(0, "mpeg-atrac: the A/V container builds"); return; }
    const uint32_t packets = (size - 2048u + MPEG_PACKET_SIZE - 1u) / MPEG_PACKET_SIZE;
    uint8_t frame[64];
    uint32_t frame_bytes = make_audio_frame(frame, sizeof(frame), 0x28, 0x00, 0x00);
    frame[8] = 0x60u;                                 /* the fixture's decodable frame */
    Atrac3pBridge *ref = NULL;
    int16_t ref_pcm[2 * 2048];
    CHECK(atrac3p_bridge_create(2, (int)frame_bytes - 8, &ref) == 0 && ref,
          "mpeg-atrac: a reference ATRAC3+ decoder for the fixture frame");
    if (!ref) { free(image); return; }

    /* A PSMF file holds whole 2048-byte packets: the fixture's program stream is completed with
     * an MPEG padding packet (stream 0xBE), and the header gets a version sceMpeg accepts and
     * the padded stream size. */
    const uint32_t ps = size - 2048u;
    const uint32_t pad = packets * MPEG_PACKET_SIZE - ps;
    CHECK(pad == 0u || pad >= 6u, "mpeg-atrac: the tail is long enough for a padding packet");
    if (AT_RING_DATA + packets * MPEG_PACKET_SIZE > 0x08000000u + ARENA_BYTES) {
        CHECK(0, "mpeg-atrac: the ring data fits in the fixture arena");
        atrac3p_bridge_destroy(ref);
        free(image);
        return;
    }
    memcpy(SR_HOST(AT_RING_DATA), image + 2048u, ps);
    if (pad >= 6u) {
        uint8_t *tail = (uint8_t *)SR_HOST(AT_RING_DATA + ps);
        tail[0] = 0x00; tail[1] = 0x00; tail[2] = 0x01; tail[3] = 0xbe;
        tail[4] = (uint8_t)((pad - 6u) >> 8); tail[5] = (uint8_t)(pad - 6u);
        memset(tail + 6, 0xff, pad - 6u);
    }
    memcpy(SR_HOST(AT_HDR), image, 2048u);
    memcpy(SR_HOST(AT_HDR + 4u), "0015", 4u);
    be32_at((uint8_t *)SR_HOST(AT_HDR + 12u), packets * MPEG_PACKET_SIZE);
    MEM_W32(AT_DESC, 0u);
    CHECK(mpeg_ringbuffer_construct(AT_RING, packets, AT_RING_DATA, packets * MPEG_RING_BYTES_PER_PKT,
                                    0u, 0u) == 0u &&
              mpeg_create(AT_DESC, AT_DATA, 0x10000u, AT_RING, 512u, 0u, 0u) == 0u &&
              mpeg_query_stream_offset(AT_DESC, AT_HDR, AT_OFF) == 0u,
          "mpeg-atrac: the ring, the context and the header are set up");
    uint32_t sid = mpeg_regist_stream(AT_DESC, MPEG_ATRAC_STREAM, 0u);
    CHECK(mpeg_get_atrac_au(AT_DESC, sid, AT_AU, AT_ATTR) == SCE_MPEG_ERROR_NO_DATA,
          "mpeg-atrac: before any packet GetAtracAu reports no data");
    memset(SR_HOST(AT_OUT), 0xa5, MPEG_ATRAC_ES_OUTPUT_SIZE);
    CHECK(mpeg_atrac_decode(AT_DESC, AT_AU, AT_OUT, 1u) == SCE_MPEG_ERROR_NO_DATA &&
              MEM_R32(AT_OUT) == 0xa5a5a5a5u && MEM_R32(AT_OUT + MPEG_ATRAC_ES_OUTPUT_SIZE - 4u) == 0xa5a5a5a5u,
          "mpeg-atrac: AtracDecode with no access unit refuses and writes nothing");

    CHECK(mpeg_ringbuffer_put(NULL, AT_RING, packets, packets) == packets,
          "mpeg-atrac: the whole stream is put into the ring");
    Mpeg *ctx = mpeg_find(AT_DESC);
    /* Skip mode hands out the clock and holds no frame: the decode that follows has nothing. */
    CHECK(mpeg_change_get_au_mode(AT_DESC, sid, MPEG_AU_MODE_SKIP) == 0u &&
              mpeg_get_atrac_au(AT_DESC, sid, AT_AU, AT_ATTR) == 0u &&
              mpeg_atrac_decode(AT_DESC, AT_AU, AT_OUT, 1u) == SCE_MPEG_ERROR_NO_DATA &&
              mpeg_change_get_au_mode(AT_DESC, sid, MPEG_AU_MODE_DECODE) == 0u,
          "mpeg-atrac: in skip mode GetAtracAu consumes no frame");
    int blocks = 0, exact = 1, clock = 1;
    for (int guard = 0; ctx && guard < 4 * AV_AUDIO_BLOCKS; guard++) {
        uint32_t r = mpeg_get_atrac_au(AT_DESC, sid, AT_AU, AT_ATTR);
        if (r == SCE_MPEG_ERROR_NO_DATA) break;
        CHECK(r == 0u, "mpeg-atrac: GetAtracAu returns a frame or no data");
        if (r) break;
        if (au_read_pts(AT_AU) != ctx->firstTimestamp + (int64_t)blocks * 4180) clock = 0;
        memset(SR_HOST(AT_OUT), 0xa5, MPEG_ATRAC_ES_OUTPUT_SIZE);
        r = mpeg_atrac_decode(AT_DESC, AT_AU, AT_OUT, blocks == 0 ? 1u : 0u);
        CHECK(r == 0u, "mpeg-atrac: a held frame decodes");
        if (r) break;
        int samples = 0;
        if (atrac3p_bridge_decode(ref, frame + 8, (int)frame_bytes - 8, ref_pcm, &samples) != 0 ||
            samples != 2048 || memcmp(SR_HOST(AT_OUT), ref_pcm, sizeof(ref_pcm)) != 0)
            exact = 0;
        blocks++;
    }
    CHECK(blocks == AV_AUDIO_BLOCKS, "mpeg-atrac: every authored ATRAC3+ frame comes out once");
    CHECK(exact, "mpeg-atrac: each block is exactly the ATRAC3+ decoder's output for its frame");
    CHECK(clock, "mpeg-atrac: each AU carries the clock, first timestamp + 4180 per decoded block");
    CHECK(mpeg_get_atrac_au(AT_DESC, sid, AT_AU, AT_ATTR) == SCE_MPEG_ERROR_NO_DATA,
          "mpeg-atrac: after the last frame GetAtracAu reports no data");

    /* A flush starts the stream over: refed packets give the first frame again. */
    CHECK(mpeg_flush_all_stream(AT_DESC) == 0u, "mpeg-atrac: the streams are flushed");
    CHECK(mpeg_ringbuffer_put(NULL, AT_RING, packets, packets) == packets &&
              mpeg_get_atrac_au(AT_DESC, sid, AT_AU, AT_ATTR) == 0u &&
              mpeg_atrac_decode(AT_DESC, AT_AU, AT_OUT, 1u) == 0u,
          "mpeg-atrac: after a flush the refed stream decodes again");
    CHECK(mpeg_delete(AT_DESC) == 0u, "mpeg-atrac: the context is deleted");

    /* A guest PSMF player parses the header with scePsmf and hands sceMpeg only the ring (title
     * X's libpsmfplayer, 2026-10-31): the decoder is set up from the frame's own header (0x28:
     * 44.1 kHz stereo), and a frame that names no mono or stereo layout is refused untouched. */
    atrac3p_bridge_destroy(ref);
    ref = NULL;
    MEM_W32(AT_DESC, 0u);
    CHECK(atrac3p_bridge_create(2, (int)frame_bytes - 8, &ref) == 0 && ref &&
              mpeg_ringbuffer_construct(AT_RING, packets, AT_RING_DATA, packets * MPEG_RING_BYTES_PER_PKT,
                                        0u, 0u) == 0u &&
              mpeg_create(AT_DESC, AT_DATA, 0x10000u, AT_RING, 512u, 0u, 0u) == 0u,
          "mpeg-atrac: a context that never sees the PSMF header");
    sid = mpeg_regist_stream(AT_DESC, MPEG_ATRAC_STREAM, 0u);
    memset(SR_HOST(AT_OUT), 0xa5, MPEG_ATRAC_ES_OUTPUT_SIZE);
    int samples = 0;
    CHECK(ref && mpeg_ringbuffer_put(NULL, AT_RING, packets, packets) == packets &&
              mpeg_get_atrac_au(AT_DESC, sid, AT_AU, AT_ATTR) == 0u &&
              mpeg_atrac_decode(AT_DESC, AT_AU, AT_OUT, 1u) == 0u &&
              atrac3p_bridge_decode(ref, frame + 8, (int)frame_bytes - 8, ref_pcm, &samples) == 0 &&
              samples == 2048 && memcmp(SR_HOST(AT_OUT), ref_pcm, sizeof(ref_pcm)) == 0,
          "mpeg-atrac: without the PSMF header a frame decodes from its own header");
    ctx = mpeg_find(AT_DESC);
    CHECK(ctx && mpeg_get_atrac_au(AT_DESC, sid, AT_AU, AT_ATTR) == 0u && ctx->audioHeld,
          "mpeg-atrac: the next frame is held");
    if (ctx && ctx->audioHeld) ctx->audioHeld[2] = 0x20u;   /* 44.1 kHz, channel id 0 */
    memset(SR_HOST(AT_OUT), 0xa5, MPEG_ATRAC_ES_OUTPUT_SIZE);
    CHECK(mpeg_atrac_decode(AT_DESC, AT_AU, AT_OUT, 0u) == SCE_MPEG_ERROR_INVALID_VALUE &&
              MEM_R32(AT_OUT) == 0xa5a5a5a5u && MEM_R32(AT_OUT + MPEG_ATRAC_ES_OUTPUT_SIZE - 4u) == 0xa5a5a5a5u,
          "mpeg-atrac: a frame naming no mono or stereo layout is refused and writes nothing");
    CHECK(mpeg_delete(AT_DESC) == 0u, "mpeg-atrac: the header-less context is deleted");
    atrac3p_bridge_destroy(ref);
    free(image);
}

/* The sceMpeg path: a picture decoded by sceMpegAvcDecodeYCbCr carries its access unit's
 * time, and sceMpegAvcCsc is where it lands in guest memory. */
static void test_mpeg_csc_presentation_boundary(void) {
    enum {
        PC_DESC = 0x08100000u, PC_DATA = 0x08110000u, PC_YCBCR = 0x08130000u,
        PC_RANGE = 0x08140000u, PC_DEST = 0x08150000u, PC_PTR = 0x08160000u,
        PC_INIT = 0x08170000u, PC_AU = 0x08180000u, PC_MODE = 0x08190000u,
    };
    if (!sr_h264_backend_available()) {
        fprintf(stderr, "SKIP: sceMpegAvcCsc presentation assertions need an H.264 backend\n");
        return;
    }
    const uint32_t width = 64u, height = 64u;
    uint32_t au_off[FIX_PICTURES], au_len[FIX_PICTURES], es_len = 0;
    uint8_t es[65536];
    CHECK(build_stream(es, sizeof(es), au_off, au_len, &es_len), "sceMpeg presentation fixture builds");
    if (!es_len) return;
    sr_hle_test_psmf_av_reset();
    sr_hle_test_psmf_av_enable(1);
    sr_hle_test_psmf_av_set_window_us(1000000);
    sr_hle_test_psmf_av_set_clock_us(1500000);
    MEM_W32(PC_DESC, 0u);
    CHECK(mpeg_create(PC_DESC, PC_DATA, 0x10000u, 0, 64u, 0, 0) == 0, "sceMpeg presentation context is created");
    Mpeg *ctx = mpeg_find(PC_DESC);
    CHECK(ctx != NULL, "sceMpeg presentation context is found");
    if (!ctx) return;
    ctx->streamWidth = width;
    ctx->streamHeight = height;
    ctx->h264 = sr_h264_create();
    ctx->h264Init = 1;
    ctx->totalPackets = 1u;
    ctx->fedPackets = 1u;
    CHECK(ctx->h264 >= 0 && sr_h264_submit_au(ctx->h264, es + au_off[0], au_len[0]) == 0,
          "sceMpeg presentation picture reaches the decoder");
    memset(SR_HOST(PC_AU), 0, 24u);
    MEM_W32(PC_AU + 0u, 0u);                  /* pts 90000 ticks = 1 s, stored high word first */
    MEM_W32(PC_AU + 4u, 90000u);
    CHECK(guest_mpeg_import(0x67179b1bu, PC_DESC, 1u, width, height, PC_YCBCR) == 0,
          "sceMpeg presentation YCbCr storage initializes");
    MEM_W32(PC_MODE, 0u);
    MEM_W32(PC_MODE + 4u, 3u);
    CHECK(guest_mpeg_import(0xa11c7026u, PC_DESC, PC_MODE, 0u, 0u, 0u) == 0,
          "sceMpeg presentation selects RGBA output");
    MEM_W32(PC_PTR, PC_YCBCR);
    MEM_W32(PC_RANGE, 0u); MEM_W32(PC_RANGE + 4u, 0u);
    MEM_W32(PC_RANGE + 8u, width); MEM_W32(PC_RANGE + 12u, height);
    MEM_W32(PC_INIT, 0u);
    CHECK(guest_mpeg_import(0xf0eb1125u, PC_DESC, PC_AU, PC_PTR, PC_INIT, 0u) == 0 && MEM_R32(PC_INIT) == 1u,
          "sceMpeg presentation picture decodes");
    CHECK(sr_hle_test_psmf_av_counter(0, "delivered") == 0,
          "sceMpeg: a decoded YCbCr picture is not delivered to the guest until sceMpegAvcCsc");
    CHECK(guest_mpeg_import(0x31bd0272u, PC_DESC, PC_YCBCR, PC_RANGE, width, PC_DEST) == 0,
          "sceMpeg presentation Csc writes the picture");
    CHECK(sr_hle_test_psmf_av_counter(0, "delivered") == 1 && sr_hle_test_psmf_av_counter(0, "pending") == 1,
          "sceMpeg: sceMpegAvcCsc delivers the picture with the access unit's time");
    sr_hle_test_psmf_av_set_clock_us(2000000);
    CHECK(guest_mpeg_import(PB_NID_SET_FRAMEBUF, PC_DEST, 64u, PB_FMT, 1u, 0) == 0,
          "sceMpeg presentation latches the destination for display");
    CHECK(sr_hle_test_psmf_av_counter(0, "matched") == 0,
          "sceMpeg: a latched flip is not a presentation before the VBLANK that applies it");
    sr_vblank_tick();
    CHECK(sr_hle_test_psmf_av_counter(0, "matched") == 1 && sr_hle_test_psmf_av_counter(0, "pending") == 0,
          "sceMpeg: the VBLANK-applied flip presents the Csc destination");
    sr_hle_test_psmf_av_report();
    const char *w = sr_hle_test_psmf_av_last_window();
    long long vo = 0;
    CHECK(av_log_field(w, " voff_us=", &vo) && vo == 1000000,
          "sceMpeg: the picture's presentation offset is present time minus its access unit time");
    mpeg_finish();
    sr_hle_test_psmf_av_reset();
}

/* A guest PSMF player (#286) copies each block sceMpegAtracDecode writes into its own output
 * buffer before the game plays it.  The copy the game plays meets its block by its bytes, also
 * after the decode buffer was overwritten, and a silent block is never matched. */
static void test_mpeg_av_audio_followed_by_content(void) {
    enum { AC_DECODE = 0x086c0000u, AC_GAME = 0x086c4000u, AC_GAME2 = 0x086c8000u };
    const uint32_t block = 8192u;
    sr_hle_test_psmf_av_reset();
    sr_hle_test_psmf_av_enable(1);
    sr_hle_test_psmf_av_set_window_us(1000000);
    sr_hle_test_psmf_av_set_queue_frames(PB_FRAMES);
    sr_hle_test_psmf_av_set_clock_us(1000000);
    int ch = (int)guest_mpeg_import(PB_NID_CH_RESERVE, 0xffffffffu, PB_FRAMES, 0u, 0, 0);
    CHECK(ch >= 0 && ch < 8, "psmf-content: an audio channel is reserved");
    for (uint32_t i = 0; i < block; i++) MEM_W8(AC_DECODE + i, (uint8_t)(i * 3u + 1u));
    sr_psmf_av_note_audio_delivery(AC_DECODE, block, 90000, 1);
    memcpy(SR_HOST(AC_GAME), SR_HOST(AC_DECODE), block);
    for (uint32_t i = 0; i < block; i++) MEM_W8(AC_DECODE + i, (uint8_t)(i * 5u + 2u));
    sr_psmf_av_note_audio_delivery(AC_DECODE, block, 90000 + 4180, 1);
    memcpy(SR_HOST(AC_GAME2), SR_HOST(AC_DECODE), block);
    CHECK(sr_hle_test_psmf_av_counter(1, "superseded") == 0,
          "psmf-content: a block overwritten in the decode buffer is still pending");
    sr_hle_test_psmf_av_set_clock_us(1010000);
    CHECK(guest_mpeg_import(PB_NID_OUTPUT_BLOCK, (uint32_t)ch, 0x8000u, AC_GAME, 0, 0) == (uint32_t)PB_FRAMES &&
              sr_hle_test_psmf_av_counter(1, "matched") == 1 &&
              sr_hle_test_psmf_av_counter(1, "content_matched") == 1,
          "psmf-content: the copy the game plays meets the first block by its bytes");
    CHECK(guest_mpeg_import(PB_NID_OUTPUT_BLOCK, (uint32_t)ch, 0x8000u, AC_GAME2, 0, 0) == (uint32_t)PB_FRAMES &&
              sr_hle_test_psmf_av_counter(1, "matched") == 2,
          "psmf-content: the second copy meets the second block");
    memset(SR_HOST(AC_DECODE), 0, block);
    sr_psmf_av_note_audio_delivery(AC_DECODE, block, 90000 + 2 * 4180, 1);
    memset(SR_HOST(AC_GAME), 0, block);
    CHECK(guest_mpeg_import(PB_NID_OUTPUT_BLOCK, (uint32_t)ch, 0x8000u, AC_GAME, 0, 0) == (uint32_t)PB_FRAMES &&
              sr_hle_test_psmf_av_counter(1, "matched") == 2,
          "psmf-content: a silent block is not matched by its bytes");
    (void)guest_mpeg_import(PB_NID_CH_RELEASE, (uint32_t)ch, 0, 0, 0, 0);
    sr_hle_test_psmf_av_reset();
    sr_hle_test_psmf_av_enable(0);
}

int main(int argc, char **argv) {
    sr_perf_init();
    sr_flight_init();
    unsigned fuzz_iterations = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--fuzz-iters") == 0 && i + 1 < argc) {
            char *end = NULL;
            unsigned long value = strtoul(argv[++i], &end, 10);
            if (end && *end == '\0' && value > 0 && value <= 100000ul) {
                fuzz_iterations = (unsigned)value;
            }
        }
    }
    static uint8_t arena[GUEST_VRAM_PREFIX_BYTES + ARENA_BYTES];
    /* SR_HOST maps VRAM at g_mem - 0x04000000, so reserve that prefix in the fixture arena. */
    g_mem = arena + GUEST_VRAM_PREFIX_BYTES;
    memset(arena, 0, sizeof(arena));

#if defined(SR_H264_FFMPEG)
    CHECK(sr_h264_select_backend("ffmpeg"),
          "H264_FFMPEG=1 selects the FFmpeg backend explicitly");
    CHECK(strcmp(sr_h264_selected_backend(), "ffmpeg") == 0,
          "the media fixture reports the FFmpeg backend selection");
    CHECK(sr_h264_backend_available(), "the explicitly selected FFmpeg backend is available");
#endif

    test_demux_and_au_contract();
    test_media_disposition_conservation();
    test_multistream_selection();
    test_track_independence();
    test_real_decode_into_guest_buffer();
    test_decoded_pixels();
    test_guest_vram_write_coherence();
    test_instance_isolation();
    test_destination_refusal();
    test_legacy_feed_take_path();
    test_backend_registry_fail_closed();
    test_backend_reset_and_restart();
    test_backend_malformed_input();
    test_video_eos_waits_for_all_access_units();
    test_mpeg_ps_demux_error_fails_closed();
    test_mpeg_ycbcr_measured_contract();
    test_mpeg_ycbcr_guest_decode();
    test_mpeg_pcm_and_au_mode();
    test_mpeg_csc_swizzled_vram_mirrors();
    test_mpeg_avc_decode_clear_in_vram_mirrors();
    test_player_lifecycle_releases_what_it_acquired();
    test_player_get_psmf_info();
    test_player_handle_word();
    test_psmf_player_display_in_vram_mirrors();
    test_psmf_log_tick_instance_isolation();
    test_psmf_av_timing_first_principles();
    test_player_av_presentation_timing(AV_LAYOUT_SPLIT);
    test_player_av_presentation_timing(AV_LAYOUT_PACKED);
    test_player_av_presentation_boundary();
    test_player_av_composited_presentation();
    test_mpeg_csc_presentation_boundary();
    test_mpeg_av_audio_followed_by_content();
    test_mpeg_atrac_au_decode();
    test_mpeg_avc_decode_detail();
    test_psmf_contract_fragmentation_and_malformed_rejection();
    if (fuzz_iterations) test_legacy_demux_mutations(fuzz_iterations);

    if (failures) {
        fprintf(stderr, "psmf_media_selftest: %d checks, %d FAILURES\n", checks, failures);
        return 1;
    }
    printf("psmf_media_selftest: %d checks, 0 failures\n", checks);
    return 0;
}
